    {"id": "q-f202-s01-018", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "For this exam, which MIP/NIF range indicates weaning readiness?", "choices": ["−20 to −30 cm H₂O or more negative", "−5 to −10 cm H₂O", "−10 to −15 cm H₂O", "+20 to +30 cm H₂O"], "correct": 0, "explanation": "Use the weaning deck's −20 to −30 cm H₂O (in 20 sec) or more negative; −20 is the floor every source agrees on.", "srcItem": "MIP / NIF"},
    {"id": "q-f202-s01-019", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A patient generates a MIP of −15 cm H₂O. How should this be interpreted?", "choices": ["Inadequate inspiratory strength for weaning", "Normal inspiratory strength", "Strong enough for extubation", "Better than a MIP of −30 cm H₂O"], "correct": 0, "explanation": "More negative = stronger. −15 does not reach the −20 floor, so strength is inadequate.", "srcItem": "MIP / NIF"},
    {"id": "q-f202-s01-020", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the normal MIP/NIF range given in the weaning deck?", "choices": ["−80 to −100 cm H₂O", "−20 to −30 cm H₂O", "−40 to −50 cm H₂O", "−5 to −15 cm H₂O"], "correct": 0, "explanation": "Normal MIP is −80 to −100 (weaning deck slide 15; Neuro slide 21).", "srcItem": "MIP / NIF"},
    {"id": "q-f202-s01-021", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How long is the airway occluded when measuring MIP per the Chang text?", "choices": ["About 20 seconds", "About 2 seconds", "About 2 minutes", "About 5 minutes"], "correct": 0, "explanation": "MIP is the negative pressure generated in 20 sec when inspiring against an occluded manometer; maximal effort may take 20–30 sec.", "srcItem": "MIP / NIF"},
    {"id": "q-f202-s01-022", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What vital capacity does the weaning deck require for weaning?", "choices": ["> 10 mL/kg", "> 50 mL/kg", "> 3 mL/kg", "> 30 mL/kg"], "correct": 0, "explanation": "Use > 10 mL/kg (weaning deck). Normal VC is ~50 mL/kg; RCP 203 notes and Hess mention 15 mL/kg.", "srcItem": "VC (vital capacity)"},
    {"id": "q-f202-s01-023", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which volumes make up the vital capacity?", "choices": ["IRV + VT + ERV", "IRV + VT + RV", "ERV + RV", "VT + RV + ERV"], "correct": 0, "explanation": "VC = maximum exhalation after maximum inspiration = IRV + VT + ERV.", "srcItem": "VC (vital capacity)"},
    {"id": "q-f202-s01-024", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Before measuring bedside VC in a patient who has been on full ventilatory support, what should the therapist do?", "choices": ["Let the patient breathe spontaneously for 3 minutes first", "Paralyze the patient to get a stable reading", "Increase the FiO₂ to 1.0 for 10 minutes", "Measure it only during mandatory breaths"], "correct": 0, "explanation": "If on full support, allow 3 min of spontaneous breathing, suction if needed, disconnect, attach a respirometer, and reconnect promptly.", "srcItem": "VC (vital capacity)"},
    {"id": "q-f202-s01-025", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How is the rapid shallow breathing index calculated?", "choices": ["RR ÷ VT in liters", "VT in mL ÷ RR", "RR × VT in liters", "V̇E ÷ RR"], "correct": 0, "explanation": "RSBI = f ÷ VT (L), in breaths/min/L — \"Rate ÷ Size,\" in L, not mL.", "srcItem": "RSBI"},
    {"id": "q-f202-s01-026", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A patient breathes 38/min with an average VT of 300 mL. What is the RSBI and what does it predict?", "choices": ["127; weaning failure", "11; weaning success", "127; weaning success", "0.13; weaning failure"], "correct": 0, "explanation": "38 ÷ 0.3 L = 127, above 100/105, so it predicts weaning failure.", "srcItem": "RSBI"},
    {"id": "q-f202-s01-027", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A patient's measured V̇E is 10 L/min at a rate of 25/min. What is the RSBI?", "choices": ["62.5 — a good weaning candidate", "250 — likely to fail", "0.06 — a good weaning candidate", "40 — likely to fail"], "correct": 0, "explanation": "VT = 10 ÷ 25 = 0.4 L; RSBI = 25 ÷ 0.4 = 62.5, which is < 100.", "srcItem": "RSBI"},
    {"id": "q-f202-s01-028", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which RSBI cutoff appears on the Chang deck slide, and which is common on the NBRC?", "choices": ["< 100 (Chang); < 105 (NBRC)", "< 105 (Chang); < 100 (NBRC)", "< 60 (Chang); < 80 (NBRC)", "< 150 (Chang); < 200 (NBRC)"], "correct": 0, "explanation": "Know Chang's < 100 (\"rounded from 105\"); for the NBRC you will commonly see < 105.", "srcItem": "RSBI"},
    {"id": "q-f202-s01-029", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why does rapid shallow breathing make weaning less likely to succeed?", "choices": ["Dead-space ventilation rises because anatomic dead space is unchanged while VT falls", "It increases lung compliance", "It lowers the PaCO₂ to dangerous levels", "It increases the VC"], "correct": 0, "explanation": "Rapid shallow breathing increases dead-space ventilation: anatomic dead space stays the same while VT falls.", "srcItem": "RSBI"},
    {"id": "q-f202-s01-030", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the minimal spontaneous VT consistent with successful weaning (weaning deck)?", "choices": ["5 mL/kg", "2 mL/kg", "10 mL/kg", "15 mL/kg"], "correct": 0, "explanation": "The minimal spontaneous VT is 5 mL/kg (normal 5–10 mL/kg). The NHLBI ARDS protocol accepts ≥ 4 mL/kg PBW.", "srcItem": "V̇E (minute ventilation), spontaneous VT and RR"},
    {"id": "q-f202-s01-031", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Above what minute ventilation is weaning often associated with poor outcomes (deck value)?", "choices": ["10 L/min", "6 L/min", "4 L/min", "20 L/min"], "correct": 0, "explanation": "Use the deck's 10 L/min ceiling (normal V̇E 6–10 L/min); recognize Hess's 12 L/min.", "srcItem": "V̇E (minute ventilation), spontaneous VT and RR"},
    {"id": "q-f202-s01-032", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does a high minute ventilation indicate in a weaning patient?", "choices": ["A high ventilatory demand", "Strong respiratory muscles ready for extubation", "A low VD/VT", "Adequate pulmonary reserve"], "correct": 0, "explanation": "High V̇E means high ventilatory demand; the higher the VD/VT, the greater the minute volume demand.", "srcItem": "V̇E (minute ventilation), spontaneous VT and RR"},
    {"id": "q-f202-s01-033", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which oxygenation finding meets the weaning deck's criteria?", "choices": ["PaO₂ > 60 mm Hg on FiO₂ ≤ 0.40", "PaO₂ > 60 mm Hg on FiO₂ 0.80", "PaO₂ 55 mm Hg on FiO₂ 0.30", "SaO₂ 85% on FiO₂ 0.40"], "correct": 0, "explanation": "Deck/Chang: PaO₂ > 60 mm Hg (or SaO₂ > 90%) on FiO₂ ≤ 0.40, P/F ≥ 150, shunt < 20%, P(A−a)O₂ < 350 on 100%.", "srcItem": "ABG and oxygenation criteria"},
    {"id": "q-f202-s01-034", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A patient is comfortable on FiO₂ 1.0 and PEEP 15 cm H₂O. Is the patient ready to wean?", "choices": ["Usually not — they still need a lot of O₂ and PEEP", "Yes — comfort is the main criterion", "Yes, if the RSBI is below 105", "Only after a T-piece trial confirms it"], "correct": 0, "explanation": "The deck's example: FiO₂ 100% and PEEP 15 is \"usually not ready\" even if the patient is comfortable.", "srcItem": "ABG and oxygenation criteria"},
    {"id": "q-f202-s01-035", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What shunt fraction should be corrected before any weaning attempt?", "choices": ["> 20%", "> 5%", "> 10%", "> 50%"], "correct": 0, "explanation": "Shunt (QS/QT) must be < 20%; a shunt > 20% should be corrected before weaning.", "srcItem": "ABG and oxygenation criteria"},
    {"id": "q-f202-s01-036", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "During an SBT, which pH limit does RCP 203 use?", "choices": ["≥ 7.30", "≥ 7.20", "≥ 7.40", "≥ 7.50"], "correct": 0, "explanation": "During an SBT: SpO₂ ≥ 85–90% or PaO₂ ≥ 50–60 torr, pH ≥ 7.30, and a rise in PaCO₂ ≤ 10 torr.", "srcItem": "ABG and oxygenation criteria"},
    {"id": "q-f202-s01-037", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "During weaning, a patient's PaCO₂ drops from 40 to 30 mm Hg. What should the therapist NOT do?", "choices": ["Reduce ventilatory support because the PaCO₂ is low", "Look for hypoxia, pain or anxiety", "Check the ventilator settings", "Assess the patient's comfort"], "correct": 0, "explanation": "Hyperventilation during weaning may be from hypoxia, pain, anxiety or bad settings; reducing support then further increases WOB.", "srcItem": "ABG and oxygenation criteria"},
    {"id": "q-f202-s01-038", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which heart-rate finding during an SBT is acceptable per RCP 203?", "choices": ["HR < 120–140/min with a change of less than 20%", "HR > 140/min with a 30% increase", "Any HR as long as SpO₂ stays above 90%", "HR below 60/min"], "correct": 0, "explanation": "During the SBT: HR < 120–140/min with change < 20%; SBP 90–180/200 with change < 20%; no vasopressors.", "srcItem": "Hemodynamic stability"},
    {"id": "q-f202-s01-039", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why might a patient with marginal left-ventricular function pass a CPAP trial but fail after extubation?", "choices": ["Positive pressure supported the failing heart, then CHF develops once it is removed", "CPAP causes ventilator-induced lung injury", "The ETT was too small during the trial", "CPAP lowers the patient's respiratory drive"], "correct": 0, "explanation": "Hess's CPAP trap: positive pressure supports the failing heart; after extubation the patient can develop congestive heart failure.", "srcItem": "Hemodynamic stability"},
    {"id": "q-f202-s01-040", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What static compliance does the weaning deck require for weaning?", "choices": ["> 30 mL/cm H₂O", "> 10 mL/cm H₂O", "> 100 mL/cm H₂O", "> 5 mL/cm H₂O"], "correct": 0, "explanation": "Use the deck's > 30 mL/cm H₂O. RCP 203: Crs < 25–30 is linked with weaning difficulty.", "srcItem": "Pulmonary mechanics"},
    {"id": "q-f202-s01-041", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How is static compliance calculated?", "choices": ["VT ÷ (Pplat − PEEP)", "VT ÷ (PIP − PEEP)", "(PIP − Pplat) ÷ flow", "(PaCO₂ − PĒCO₂) ÷ PaCO₂"], "correct": 0, "explanation": "CST = VT ÷ (Pplat − PEEP). (PIP − Pplat) ÷ flow is airway resistance.", "srcItem": "Pulmonary mechanics"},
    {"id": "q-f202-s01-042", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "PaCO₂ is 40 mm Hg and mixed exhaled PCO₂ is 27 mm Hg. What is the VD/VT?", "choices": ["0.325", "0.675", "0.13", "1.48"], "correct": 0, "explanation": "VD/VT = (40 − 27) ÷ 40 = 0.325 (32.5%); normal is about 0.3, and < 60% is needed while intubated.", "srcItem": "Pulmonary mechanics"},
    {"id": "q-f202-s01-043", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which pulmonary measurements do NOT depend on patient cooperation or effort?", "choices": ["Static compliance, VD/VT and airway resistance", "VC and MIP", "RSBI and VC", "MEP and cough peak flow"], "correct": 0, "explanation": "Compliance, VD/VT and Raw do not depend on effort; VC and MIP do.", "srcItem": "Pulmonary mechanics"},
    {"id": "q-f202-s01-044", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "According to the deck, how long does a spontaneous breathing trial last?", "choices": ["Up to 30 minutes", "At least 4 hours", "Exactly 5 minutes", "24 hours"], "correct": 0, "explanation": "Chang: up to 30 min, since patients who fail do so in the first 20–30 min. RCP 203 and Hess: 30–120 min.", "srcItem": "Spontaneous breathing trial (SBT)"},
    {"id": "q-f202-s01-045", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which method is NOT recommended as a stand-alone weaning mode?", "choices": ["SIMV", "T-piece", "Low PS of 5–8 cm H₂O", "CPAP of about 5 cm H₂O"], "correct": 0, "explanation": "SIMV is not recommended as a stand-alone weaning mode; Hess notes the poorest outcomes were reported with SIMV.", "srcItem": "Spontaneous breathing trial (SBT)"},
    {"id": "q-f202-s01-046", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A patient fails an SBT. What is the next step?", "choices": ["Return to full support, find and correct the cause, and repeat the SBT in 24 hours", "Extubate to NIV immediately", "Repeat the SBT every hour until it is passed", "Switch to SIMV weaning"], "correct": 0, "explanation": "Stop, return to full support and rest, correct the cause, and repeat the SBT every 24 hours.", "srcItem": "Spontaneous breathing trial (SBT)"},
    {"id": "q-f202-s01-047", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which finding is a sign of SBT failure?", "choices": ["Diaphoresis and paradoxical abdominal movement", "RR of 18/min with a stable SpO₂", "A rise in PaCO₂ of 4 torr", "Calm, alert and following commands"], "correct": 0, "explanation": "Failure signs: agitation/anxiety, ↓ mental status, diaphoresis, cyanosis, ↑ WOB, tachypnea, accessory-muscle use, paradoxical abdominal movement.", "srcItem": "Spontaneous breathing trial (SBT)"},
    {"id": "q-f202-s01-048", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In the NHLBI ARDS protocol, which settings make a patient ready for an SBT?", "choices": ["FiO₂ ≤ 0.40 with PEEP ≤ 8, or FiO₂ ≤ 0.50 with PEEP ≤ 5", "FiO₂ ≤ 0.60 with PEEP ≤ 10", "FiO₂ ≤ 0.30 with PEEP ≤ 3", "Any FiO₂ with PEEP ≤ 12"], "correct": 0, "explanation": "Ready: FiO₂ ≤ 0.40/PEEP ≤ 8 or FiO₂ ≤ 0.50/PEEP ≤ 5, SBP ≥ 90 without vasopressors, no neuromuscular blockade.", "srcItem": "Spontaneous breathing trial (SBT)"},
    {"id": "q-f202-s01-049", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which patient should NOT receive a spontaneous awakening trial (SAT)?", "choices": ["A patient with increased ICP", "A patient with stable pneumonia", "A patient on low-dose fentanyl", "A post-operative patient who is hemodynamically stable"], "correct": 0, "explanation": "No SAT with active seizures, alcohol withdrawal, escalating sedatives, neuromuscular blockers, MI in the past 24 h or increased ICP.", "srcItem": "Spontaneous breathing trial (SBT)"},
    {"id": "q-f202-s01-050", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A patient passed the SBT. What else must be assessed before removing the ETT?", "choices": ["Ability to protect the airway and clear secretions", "Only the RSBI", "The patient's VC trend over 7 days", "The cuff pressure"], "correct": 0, "explanation": "Passing the SBT answers \"Can the patient breathe?\" Extubation also needs airway protection and secretion clearance.", "srcItem": "Secretions, cough and airway protection"},
    {"id": "q-f202-s01-051", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What MEP reflects an ineffective cough and poor secretion clearance?", "choices": ["< 40 cm H₂O", "< 100 cm H₂O", "< 80 cm H₂O", "> 60 cm H₂O"], "correct": 0, "explanation": "MEP (\"think cough\"): normal 60–100 cm H₂O; < 40 cm H₂O = ineffective cough.", "srcItem": "Secretions, cough and airway protection"},
    {"id": "q-f202-s01-052", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How often can suctioning be needed before it should preclude extubation (Hess)?", "choices": ["More often than every 2 hours", "More often than every 8 hours", "Once per shift", "More often than every 24 hours"], "correct": 0, "explanation": "Hess Ch 20: suctioning more often than every 2 hours should preclude extubation.", "srcItem": "Secretions, cough and airway protection"},
    {"id": "q-f202-s01-053", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which patient is at high risk of post-extubation stridor and a candidate for a cuff-leak test?", "choices": ["A woman intubated for 8 days with a large ETT", "A man intubated for 1 day after elective surgery", "A patient with a small ETT intubated 12 hours", "A patient extubated on a planned schedule after 2 days"], "correct": 0, "explanation": "Risk factors: traumatic intubation, intubation > 6 days, large ETT, female sex, reintubation after unplanned extubation.", "srcItem": "Cuff-leak test and post-extubation stridor"},
    {"id": "q-f202-s01-054", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "If a patient fails a cuff-leak test, what does the 2017 ATS/ACCP guideline suggest?", "choices": ["Systemic steroids at least 4 hours before extubation", "Immediate tracheostomy", "Repeat the cuff-leak test every hour until it passes", "Extubate directly to heliox"], "correct": 0, "explanation": "Give systemic steroids ≥ 4 h before extubation; a repeat cuff-leak test is not required.", "srcItem": "Cuff-leak test and post-extubation stridor"},
    {"id": "q-f202-s01-055", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Stridor develops after extubation. What should the therapist recommend?", "choices": ["Cool humidified O₂ by aerosol mask and aerosolized racemic epinephrine", "Immediate reintubation in every case", "An albuterol MDI and incentive spirometry", "Chest physiotherapy and postural drainage"], "correct": 0, "explanation": "RCP 203: give cool, humidified O₂ via aerosol mask and recommend aerosolized racemic epinephrine; NPO for 24 h.", "srcItem": "Cuff-leak test and post-extubation stridor"},
    {"id": "q-f202-s01-056", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the most serious complication of extubation?", "choices": ["Laryngospasm", "Sore throat", "Hoarseness", "Cough"], "correct": 0, "explanation": "RCP 203 Ch 9: the most serious complication of extubation is laryngospasm.", "srcItem": "Cuff-leak test and post-extubation stridor"},
    {"id": "q-f202-s01-057", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which electrolyte abnormality is specifically listed as contributing to respiratory muscle weakness and weaning failure?", "choices": ["Hypophosphatemia", "Hypernatremia", "Hyperkalemia", "Hypercalcemia"], "correct": 0, "explanation": "Contributors include hypokalemia, hypophosphatemia, hypocalcemia and hypomagnesemia.", "srcItem": "Why patients fail weaning, and what to fix first"},
    {"id": "q-f202-s01-058", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why can overfeeding make weaning harder?", "choices": ["It raises O₂ consumption, CO₂ production and RQ", "It depletes diaphragm glycogen", "It lowers the respiratory drive", "It increases lung compliance"], "correct": 0, "explanation": "Overfeeding raises VO₂, VCO₂ and RQ, which can cause respiratory distress during weaning; undernutrition depletes diaphragm glycogen and protein.", "srcItem": "Why patients fail weaning, and what to fix first"},
    {"id": "q-f202-s01-059", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which cause of increased airway resistance during weaning is patient-related rather than mechanical?", "choices": ["Bronchospasm", "Kinked ETT", "Secretions in the ETT", "A small ETT"], "correct": 0, "explanation": "Bronchospasm is patient-related; a small ETT, secretions in it, kinking or biting, and condensation are mechanical.", "srcItem": "Why patients fail weaning, and what to fix first"},
    {"id": "q-f202-s01-060", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What three factors is weaning failure related to?", "choices": ["Increased airflow resistance, decreased compliance and respiratory muscle fatigue", "Hypoxemia, hypercapnia and alkalosis", "Fever, tachycardia and anemia", "Low PEEP, low FiO₂ and low rate"], "correct": 0, "explanation": "Weaning failure relates to ↑ resistance, ↓ compliance and respiratory muscle fatigue.", "srcItem": "Why patients fail weaning, and what to fix first"},
    {"id": "q-f202-s01-061", "topic": "f202-s01", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How long might a rest period need to be after respiratory muscle fatigue (Hess)?", "choices": ["24 hours", "15 minutes", "2 hours", "7 days"], "correct": 0, "explanation": "Hess: a 24-hour rest may be needed after fatigue; atrophy can develop in as little as 24 h of total rest on controlled ventilation.", "srcItem": "Why patients fail weaning, and what to fix first"},
    {"id": "q-f202-s02-001", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the main purpose of therapeutic hypothermia after cardiac arrest?", "choices": ["To protect the brain from secondary neurological injury", "To lower the heart rate and myocardial workload", "To prevent ventilator-associated pneumonia", "To treat post-arrest hyperthermia only"], "correct": 0, "explanation": "The TH deck's first Key Point: the primary goal is to protect the brain from secondary neurological injury after cardiac arrest.", "srcItem": "What Therapeutic Hypothermia is"},
    {"id": "q-f202-s02-002", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which is listed as a cause of hypoxic-ischemic encephalopathy (HIE)?", "choices": ["Decreased CPP from a low MAP or high ICP", "Hyperglycemia from insulin resistance", "Respiratory alkalosis from hyperventilation", "Excess surfactant production"], "correct": 0, "explanation": "HIE causes: inadequate ventilation/oxygenation (respiratory arrest, CO poisoning), inadequate perfusion (cardiac arrest, shock), and ↓ CPP from ↓ MAP or ↑ ICP.", "srcItem": "What Therapeutic Hypothermia is"},
    {"id": "q-f202-s02-003", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "During coronary artery bypass surgery, what can excessive cooling cause?", "choices": ["Paralysis of the hemidiaphragms from phrenic nerve cooling", "Laryngospasm on extubation", "Rebound hyperkalemia", "Pulmonary embolism"], "correct": 0, "explanation": "The Monitoring deck notes that excessive cooling of the phrenic nerves during CABG may paralyze the hemidiaphragms.", "srcItem": "What Therapeutic Hypothermia is"},
    {"id": "q-f202-s02-004", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does Hess define hypothermia?", "choices": ["Core temperature of 35 °C (95 °F) or less", "Core temperature of 37 °C or less", "Core temperature of 30 °C or less", "Skin temperature below 33 °C"], "correct": 0, "explanation": "Hess gives normal body temperature as 37 °C (98.6 °F) and defines hypothermia as core temperature ≤ 35 °C (95 °F).", "srcItem": "What Therapeutic Hypothermia is"},
    {"id": "q-f202-s02-005", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which cooling approach does Hess say reaches the target temperature faster with better outcomes?", "choices": ["Internal cooling such as cold saline or endovascular catheters", "Ice packs to the groin and axillae", "Lowering the room thermostat", "Cold-air fans"], "correct": 0, "explanation": "Internal cooling (cold saline, endovascular cooling catheters) reaches target faster and gives better outcomes.", "srcItem": "What Therapeutic Hypothermia is"},
    {"id": "q-f202-s02-006", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why does the brain depend on a constant supply of glucose and oxygen?", "choices": ["It stores little glycogen and cannot use fatty acids", "It stores large glycogen reserves that are used first", "It can switch to fatty acids only during cooling", "It uses only 2% of the body's energy"], "correct": 0, "explanation": "The brain is ~2% of body weight but uses 15% of the body's energy; it holds little glycogen and cannot use fatty acids.", "srcItem": "Hyperglycemia, Hypoglycemia and Hypokalemia in the cooled, brain-injur"},
    {"id": "q-f202-s02-007", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What normal glucose range does the deck give?", "choices": ["70–110 mg/dL", "140–180 mg/dL", "40–60 mg/dL", "200–250 mg/dL"], "correct": 0, "explanation": "Normal glucose is 70–110 mg/dL; ↑ = hyperglycemia (insulin), ↓ = hypoglycemia (give glucose).", "srcItem": "Hyperglycemia, Hypoglycemia and Hypokalemia in the cooled, brain-injur"},
    {"id": "q-f202-s02-008", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which ECG change is linked with hypokalemia on the RCP 103 lab slide?", "choices": ["Flattened T wave", "Peaked T wave", "ST elevation", "Widened P wave"], "correct": 0, "explanation": "Hypokalemia: flattened T wave (RCP 103); PVCs and respiratory muscle weakness (RCP 203).", "srcItem": "Hyperglycemia, Hypoglycemia and Hypokalemia in the cooled, brain-injur"},
    {"id": "q-f202-s02-009", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which rule applies when giving IV potassium chloride for hypokalemia?", "choices": ["Never give it undiluted, and keep UOP above 40–50 mL/hour", "Push it rapidly IV to correct the level", "Give at least 60 mEq in the first hour", "Stop all urine output monitoring"], "correct": 0, "explanation": "Never give undiluted KCl (arrhythmias, arrest); < 40 mEq/hour, < 200 mEq/24 h, drip < 40 mEq/L, UOP > 40–50 mL/h.", "srcItem": "Hyperglycemia, Hypoglycemia and Hypokalemia in the cooled, brain-injur"},
    {"id": "q-f202-s02-010", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is cold diuresis?", "choices": ["Increased urine output during cooling", "Decreased urine output during rewarming", "Urine retention caused by sedation", "Osmotic diuresis from hyperglycemia"], "correct": 0, "explanation": "Cold diuresis = increased urine output during cooling; it causes loss of fluid, K⁺, Mg²⁺ and phosphate and hypovolemia.", "srcItem": "Cold Diuresis"},
    {"id": "q-f202-s02-011", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What mechanism does the TH deck give for cold diuresis?", "choices": ["Peripheral vasoconstriction shifts blood to the core, ANP rises and ADH falls", "Cooling increases ADH release, concentrating the urine", "Hyperglycemia causes osmotic water loss", "Diuretics given with cooling cause the loss"], "correct": 0, "explanation": "Vasoconstriction → more blood to the core → ANP released, ADH falls → large volumes of dilute urine.", "srcItem": "Cold Diuresis"},
    {"id": "q-f202-s02-012", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What are the maximum points for the eye, verbal and motor components of the GCS?", "choices": ["Eyes 4, verbal 5, motor 6", "Eyes 5, verbal 5, motor 5", "Eyes 6, verbal 5, motor 4", "Eyes 4, verbal 6, motor 5"], "correct": 0, "explanation": "GCS = Eyes up to 4 + Verbal up to 5 + Motor up to 6; maximum 15, minimum 3.", "srcItem": "Glasgow Coma Scale (GCS)"},
    {"id": "q-f202-s02-013", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A patient opens the eyes to pain, makes incomprehensible sounds and withdraws from pain. What is the GCS?", "choices": ["8", "6", "10", "12"], "correct": 0, "explanation": "E2 + V2 + M4 = 8 (the deck's worked example).", "srcItem": "Glasgow Coma Scale (GCS)"},
    {"id": "q-f202-s02-014", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which GCS component does the instructor call the best predictor of neurologic outcome?", "choices": ["Motor response", "Eye opening", "Verbal response", "Pupil size"], "correct": 0, "explanation": "The instructor stresses that the motor response is the best predictor of neurologic outcome.", "srcItem": "Glasgow Coma Scale (GCS)"},
    {"id": "q-f202-s02-015", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In an intubated patient, how is the GCS reported?", "choices": ["From 2T to 10T, because the verbal score cannot be tested", "From 3 to 15, using the best guess for verbal", "From 1 to 6, using motor only", "It cannot be scored at all"], "correct": 0, "explanation": "The verbal score cannot be tested when intubated, so the GCS runs 2T to 10T (\"T\" = intubated).", "srcItem": "Glasgow Coma Scale (GCS)"},
    {"id": "q-f202-s02-016", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What score on the motor scale means the patient extends to pain (decerebrate)?", "choices": ["2", "3", "4", "5"], "correct": 0, "explanation": "Motor: obeys 6, localizes 5, withdraws 4, flexes (decorticate) 3, extends (decerebrate) 2, none 1.", "srcItem": "Glasgow Coma Scale (GCS)"},
    {"id": "q-f202-s02-017", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "When cerebral circulation stops, how quickly are neuronal oxygen stores used up?", "choices": ["About 20 seconds", "About 5 minutes", "About 1 hour", "About 24 hours"], "correct": 0, "explanation": "Oxygen stores are gone within about 20 seconds (loss of consciousness); glucose and ATP are lost within 5 minutes of complete anoxia.", "srcItem": "Cell Injury, Excitatory Neurotransmitters and Apoptosis"},
    {"id": "q-f202-s02-018", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which sequence matches the instructor's one-line summary of neuronal injury?", "choices": ["Energy failure → calcium overload → neuronal death", "Calcium overload → glucose excess → recovery", "Hyperoxia → vasodilation → edema", "Fever → hyperventilation → alkalosis"], "correct": 0, "explanation": "\"Energy failure → Calcium overload → Neuronal death.\"", "srcItem": "Cell Injury, Excitatory Neurotransmitters and Apoptosis"},
    {"id": "q-f202-s02-019", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the brain's primary excitatory neurotransmitter, released in excess during hypoxia?", "choices": ["Glutamate", "Acetylcholine", "GABA", "Dopamine"], "correct": 0, "explanation": "Glutamate; excess release lets too much calcium into neurons and speeds cell death.", "srcItem": "Cell Injury, Excitatory Neurotransmitters and Apoptosis"},
    {"id": "q-f202-s02-020", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does apoptosis mean?", "choices": ["Programmed cell death", "Uncontrolled cell death with inflammation", "Cell swelling from sodium influx", "Regeneration of damaged neurons"], "correct": 0, "explanation": "Apoptosis = programmed (regulated) cell death; necrosis is uncontrolled death with membrane disruption and inflammation.", "srcItem": "Cell Injury, Excitatory Neurotransmitters and Apoptosis"},
    {"id": "q-f202-s02-021", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is cerebral autoregulation?", "choices": ["The brain keeping its blood flow stable despite changes in blood pressure", "The brain raising ICP to protect itself", "Automatic control of breathing by the medulla", "The kidneys regulating blood pressure"], "correct": 0, "explanation": "Autoregulation constricts and dilates cerebral vessels to keep flow constant; it may be lost in severe hypotension or TBI.", "srcItem": "Autoregulation (cerebral) and CPP"},
    {"id": "q-f202-s02-022", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How is cerebral perfusion pressure calculated?", "choices": ["CPP = MAP − ICP", "CPP = ICP − MAP", "CPP = SBP − DBP", "CPP = MAP + ICP"], "correct": 0, "explanation": "CPP = MAP − ICP.", "srcItem": "Autoregulation (cerebral) and CPP"},
    {"id": "q-f202-s02-023", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "MAP stays at 90 mm Hg while ICP rises from 10 to 30 mm Hg. What happens to the CPP?", "choices": ["It falls from 80 to 60 mm Hg", "It rises from 80 to 120 mm Hg", "It stays at 90 mm Hg", "It falls from 100 to 70 mm Hg"], "correct": 0, "explanation": "90 − 10 = 80 → 90 − 30 = 60 (the deck's worked example).", "srcItem": "Autoregulation (cerebral) and CPP"},
    {"id": "q-f202-s02-024", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "For a therapeutic hypothermia/HIE question, what are the normal ICP and its critical value?", "choices": ["8–12 mm Hg; critical 20 mm Hg", "20–30 mm Hg; critical 40 mm Hg", "0–2 mm Hg; critical 5 mm Hg", "60–80 mm Hg; critical 100 mm Hg"], "correct": 0, "explanation": "Use CPP 70–80 (≥ 70) and ICP 8–12 (critical 20) from the RCP 105 deck; the Trauma deck uses CPP > 60.", "srcItem": "Autoregulation (cerebral) and CPP"},
    {"id": "q-f202-s02-025", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "For a trauma or head-injury question, what CPP goal does the Trauma deck give?", "choices": ["> 60 mm Hg", "> 100 mm Hg", "> 40 mm Hg", "> 120 mm Hg"], "correct": 0, "explanation": "Trauma deck: maintain CPP > 60 mm Hg by lowering ICP, raising MAP, or both (Hess agrees).", "srcItem": "Autoregulation (cerebral) and CPP"},
    {"id": "q-f202-s02-026", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "At what temperature does the blood gas analyzer measure every ABG?", "choices": ["37 °C", "The patient's actual core temperature", "33 °C", "Room temperature"], "correct": 0, "explanation": "The electrodes are kept at 37 °C, so every ABG is measured at 37 °C regardless of the patient's temperature.", "srcItem": "ABG changes based on temperature (T°)"},
    {"id": "q-f202-s02-027", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In a hypothermic patient, how do the patient's actual values compare with the 37 °C printout?", "choices": ["Lower PaO₂, lower PaCO₂ and higher pH", "Higher PaO₂, higher PaCO₂ and lower pH", "Identical in every value", "Lower pH only"], "correct": 0, "explanation": "Cold → ↑ solubility → ↓ partial pressures and ↑ pH (\"looks alkalotic\"). Hot → the opposite.", "srcItem": "ABG changes based on temperature (T°)"},
    {"id": "q-f202-s02-028", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A patient cooled to 33 °C has a 37 °C ABG of pH 7.40, PCO₂ 40, PO₂ 90. Using the deck formulas, what are the corrected values?", "choices": ["pH 7.46, PCO₂ 32, PO₂ 70", "pH 7.34, PCO₂ 48, PO₂ 110", "pH 7.40, PCO₂ 40, PO₂ 90", "pH 7.52, PCO₂ 24, PO₂ 50"], "correct": 0, "explanation": "37 − 33 = 4: pH + 0.015×4 = 7.46; PCO₂ − 2×4 = 32; PO₂ − 5×4 = 70 (Hess gives 68).", "srcItem": "ABG changes based on temperature (T°)"},
    {"id": "q-f202-s02-029", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which ABG value does NOT change with temperature?", "choices": ["HCO₃⁻", "PaO₂", "PaCO₂", "pH"], "correct": 0, "explanation": "HCO₃⁻, O₂ content, O₂ capacity and saturation do not change with temperature.", "srcItem": "ABG changes based on temperature (T°)"},
    {"id": "q-f202-s02-030", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does a decrease in temperature shift the oxyhemoglobin dissociation curve?", "choices": ["To the left, with increased Hb affinity for O₂", "To the right, with decreased Hb affinity for O₂", "It does not affect the curve", "It flattens the curve completely"], "correct": 0, "explanation": "Cooling shifts the curve left (↑ affinity, lower P50); fever shifts it right.", "srcItem": "ABG changes based on temperature (T°)"},
    {"id": "q-f202-s02-031", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which is an advantage of therapeutic hypothermia?", "choices": ["It lowers oxygen consumption and brain metabolism", "It improves clotting", "It prevents pneumonia", "It raises the seizure threshold permanently"], "correct": 0, "explanation": "TH lowers O₂ utilization and brain metabolism and reduces inflammatory responses after reperfusion.", "srcItem": "Advantages and Disadvantages of Therapeutic Hypothermia"},
    {"id": "q-f202-s02-032", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why should an HME not be used in a hypothermic patient?", "choices": ["It decreases the exhaled humidity available", "It warms the patient too quickly", "It increases the FiO₂", "It blocks the temperature probe"], "correct": 0, "explanation": "RCP 203 Equipment: do not use an HME in a hypothermic patient because it decreases the exhaled humidity available.", "srcItem": "Advantages and Disadvantages of Therapeutic Hypothermia"},
    {"id": "q-f202-s02-033", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which complication occurs if the temperature drops below the desired range during TH?", "choices": ["Coagulopathy and arrhythmias", "Hypertension and tachycardia", "Polycythemia", "Hypercalcemia"], "correct": 0, "explanation": "Hess: below the desired range → coagulopathy and arrhythmias; also more pneumonia/sepsis and hyperglycemia.", "srcItem": "Advantages and Disadvantages of Therapeutic Hypothermia"},
    {"id": "q-f202-s02-034", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "For a post-arrest brain-injured patient, what PaCO₂ should be targeted under current practice?", "choices": ["35–45 mm Hg (normal)", "20–25 mm Hg", "26–30 mm Hg routinely", "50–60 mm Hg"], "correct": 0, "explanation": "Keep PaCO₂ normal (35–45); routine hyperventilation is no longer recommended. 30–35 only for emergency ICP control.", "srcItem": "Ventilating the post-arrest / brain-injured patient"},
    {"id": "q-f202-s02-035", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why is routine hyperventilation no longer recommended in brain injury?", "choices": ["Excess cerebral vasoconstriction can worsen brain ischemia", "It raises ICP", "It causes cerebral vasodilation", "It increases CO₂ production"], "correct": 0, "explanation": "↓ PaCO₂ → vasoconstriction → ↓ ICP but ↓ blood flow, which can worsen ischemia.", "srcItem": "Ventilating the post-arrest / brain-injured patient"},
    {"id": "q-f202-s02-036", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why is a TBI patient on the ventilator sedated?", "choices": ["To prevent sudden ICP spikes from coughing or dyssynchrony", "To lower the PaO₂ target", "To allow routine hyperventilation", "To make suctioning unnecessary"], "correct": 0, "explanation": "Sedation prevents ICP spikes from coughing or patient–ventilator dyssynchrony; suction only when needed.", "srcItem": "Ventilating the post-arrest / brain-injured patient"},
    {"id": "q-f202-s02-037", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Per the current TH deck (2025 AHA), what temperature is maintained in adults who remain unresponsive after ROSC?", "choices": ["A constant temperature between 32 °C and 37.5 °C", "Exactly 32 °C", "Below 30 °C", "38–39 °C"], "correct": 0, "explanation": "Slide 16: select and maintain a constant temperature between 32 and 37.5 °C.", "srcItem": "TTM today, from the TH PowerPoint"},
    {"id": "q-f202-s02-038", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "For a current-practice question, how long is temperature control maintained after ROSC?", "choices": ["At least 36 hours", "Exactly 12 hours", "At least 7 days", "Until the patient is extubated"], "correct": 0, "explanation": "Current deck: at least 36 hours after ROSC (HACA used 24 hours).", "srcItem": "TTM today, from the TH PowerPoint"},
    {"id": "q-f202-s02-039", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In the HACA trial (2002), what temperature and duration were used?", "choices": ["32–34 °C for 24 hours", "32–37.5 °C for 36 hours", "35–36 °C for 72 hours", "28–30 °C for 12 hours"], "correct": 0, "explanation": "HACA cooled to 32–34 °C for 24 hours, then slow rewarming over about 8 hours.", "srcItem": "TTM today, from the TH PowerPoint"},
    {"id": "q-f202-s02-040", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which rhythm showed the clearest benefit from hypothermia in the early studies?", "choices": ["Ventricular fibrillation", "Asystole", "PEA", "Sustained shock"], "correct": 0, "explanation": "V-fib: 56% vs 26% good outcome; the benefit was clearest in shockable rhythms.", "srcItem": "TTM today, from the TH PowerPoint"},
    {"id": "q-f202-s02-041", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "About how much does cerebral metabolism fall for each 1 °C of cooling?", "choices": ["About 5–7%", "About 50%", "About 1%", "About 20–25%"], "correct": 0, "explanation": "Slide 7: about 5–7% per °C (slide 35: 5–8%), with less glucose and O₂ consumed.", "srcItem": "TTM today, from the TH PowerPoint"},
    {"id": "q-f202-s02-042", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What MAP target accompanies TTM in the current deck?", "choices": ["≥ 65 mm Hg, individualized", "≥ 100 mm Hg", "≤ 50 mm Hg", "Exactly 120 mm Hg"], "correct": 0, "explanation": "Avoid hypotension with IV fluids and vasopressors to a MAP ≥ 65 mm Hg.", "srcItem": "TTM today, from the TH PowerPoint"},
    {"id": "q-f202-s02-043", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why is routine prophylactic hypothermia not recommended for traumatic brain injury?", "choices": ["It may lower ICP but has not consistently improved neurological outcomes", "It always raises ICP", "It cannot be done in trauma patients", "It causes immediate hyperthermia"], "correct": 0, "explanation": "Lowering ICP does not necessarily improve recovery; Clifton (2001) found no improvement and more complications.", "srcItem": "Why TH is not used routinely in traumatic brain injury"},
    {"id": "q-f202-s02-044", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why must rewarming after TH in TBI be slow?", "choices": ["Rapid rewarming can cause rebound intracranial hypertension and instability", "Slow rewarming prevents hypoglycemia only", "Rapid rewarming lowers the ICP too much", "Slow rewarming is needed to keep the patient paralyzed"], "correct": 0, "explanation": "Rapid rewarming can bring physiologic instability and rebound intracranial hypertension.", "srcItem": "Why TH is not used routinely in traumatic brain injury"},
    {"id": "q-f202-s02-045", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does necrosis differ from apoptosis?", "choices": ["Necrosis is uncontrolled death with inflammation; apoptosis is programmed and causes little inflammation", "Necrosis is programmed; apoptosis is uncontrolled", "Both are reversible", "Apoptosis always happens within seconds"], "correct": 0, "explanation": "Necrosis: uncontrolled, membrane disruption, inflammation. Apoptosis: regulated, can occur hours–days later, cleared without inflammation.", "srcItem": "How cooling protects the brain"},
    {"id": "q-f202-s02-046", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which row of the mechanism charts do the notes call the most clinically important?", "choices": ["Fever", "Thrombosis", "Blood–brain barrier damage", "Oxidative damage"], "correct": 0, "explanation": "Fever raises cerebral metabolic demand and lowers the seizure threshold; controlled temperature management prevents it.", "srcItem": "How cooling protects the brain"},
    {"id": "q-f202-s02-047", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How may TH reduce apoptosis?", "choices": ["By reducing activation of caspase enzymes", "By increasing glutamate release", "By raising intracellular calcium", "By increasing free-radical production"], "correct": 0, "explanation": "TH may reduce caspase activation, up-regulate survival pathways, and limit hyperexcitability and oxidative damage.", "srcItem": "How cooling protects the brain"},
    {"id": "q-f202-s02-048", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "After ROSC, why does hypotension worsen brain ischemia?", "choices": ["Autoregulation is impaired, so brain blood flow depends on systemic BP", "Hypotension raises the ICP directly", "Hypotension increases glutamate uptake", "Hypotension lowers CO₂ production"], "correct": 0, "explanation": "Post-resuscitation encephalopathy: with autoregulation impaired, brain flow depends on systemic BP.", "srcItem": "How cooling protects the brain"},
    {"id": "q-f202-s02-049", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What are the three phases of therapeutic hypothermia?", "choices": ["Induction, maintenance and rewarming", "Cooling, freezing and thawing", "Sedation, paralysis and extubation", "Assessment, cooling and discharge"], "correct": 0, "explanation": "Phase I induction, phase II maintenance, phase III rewarming.", "srcItem": "The three phases"},
    {"id": "q-f202-s02-050", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What rewarming rate does the TH deck recommend?", "choices": ["About 0.2–0.5 °C per hour", "About 2–3 °C per hour", "About 5 °C per hour", "As fast as the device allows"], "correct": 0, "explanation": "Slide 24: 0.2–0.5 °C/h; slide 34: 0.25–0.5 °C/h. The ceiling of 0.5 °C/h is the same.", "srcItem": "The three phases"},
    {"id": "q-f202-s02-051", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is 'afterdrop' during rewarming?", "choices": ["A further fall in core temperature as cold peripheral blood returns to the core", "A rise above the target temperature", "A sudden drop in glucose", "A drop in heart rate from vagal stimulation"], "correct": 0, "explanation": "Afterdrop = further core cooling as cold peripheral blood returns; overshoot = rising above target (rebound hyperthermia).", "srcItem": "The three phases"},
    {"id": "q-f202-s02-052", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why must shivering be treated during TTM?", "choices": ["It slows cooling and raises O₂ consumption and CO₂ production", "It lowers the metabolic rate too much", "It causes hypoglycemia", "It improves cooling and should be encouraged"], "correct": 0, "explanation": "Shivering (up to 40% of TTM patients) slows cooling and raises VO₂, VCO₂ and metabolic demand, possibly up to sixfold.", "srcItem": "The three phases"},
    {"id": "q-f202-s02-053", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the last-resort treatment for refractory shivering during TTM?", "choices": ["Neuromuscular blockade such as vecuronium, with monitoring", "Stopping the cooling device", "Rapid rewarming", "IV potassium chloride"], "correct": 0, "explanation": "Sedation, buspirone/meperidine and counter-warming come first; neuromuscular blockade is the monitored last resort.", "srcItem": "The three phases"},
    {"id": "q-f202-s02-054", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "During cooling, what happens to potassium and glucose?", "choices": ["Hypokalemia and hyperglycemia", "Hyperkalemia and hypoglycemia", "Hyperkalemia and hyperglycemia", "No change in either"], "correct": 0, "explanation": "Cooling: K⁺ shifts into cells and is lost in cold diuresis; insulin resistance → hyperglycemia.", "srcItem": "Adverse effects of cooling, system by system"},
    {"id": "q-f202-s02-055", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "During rewarming, which electrolyte problem must the RT and team watch for?", "choices": ["Rebound hyperkalemia", "Hypokalemia worsening", "Hypernatremia", "Hypercalcemia"], "correct": 0, "explanation": "Rewarming shifts K⁺ back out of cells (rebound hyperkalemia, dysrhythmias), and insulin sensitivity returns (possible hypoglycemia).", "srcItem": "Adverse effects of cooling, system by system"},
    {"id": "q-f202-s02-056", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which ECG finding is characteristic of hypothermia?", "choices": ["Osborn (J) waves", "Peaked T waves", "Delta waves", "Shortened QT interval"], "correct": 0, "explanation": "Hypothermia ECG: prolonged PR, widened QRS, prolonged QT, Osborn (J) waves; HR 45–55 at 33 °C is expected.", "srcItem": "Adverse effects of cooling, system by system"},
    {"id": "q-f202-s02-057", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why can coagulation lab results look near normal while a cooled patient bleeds?", "choices": ["PT/INR and aPTT are run at 37 °C", "Cooling improves platelet function", "The lab adds clotting factors to the sample", "Bleeding is impossible below 35 °C"], "correct": 0, "explanation": "Lab tests run at 37 °C, so they can look near normal while clotting enzymes are slowed in the cold patient.", "srcItem": "Adverse effects of cooling, system by system"},
    {"id": "q-f202-s02-058", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why might infection develop without fever in a patient on TTM?", "choices": ["The febrile response is masked by cooling", "Cooling kills all bacteria", "Antibiotics are always given", "Fever is prevented by glucose control"], "correct": 0, "explanation": "Immune function is reduced and the febrile response masked, so keep a low threshold to treat infection.", "srcItem": "Adverse effects of cooling, system by system"},
    {"id": "q-f202-s02-059", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "If minute ventilation is left unchanged while a patient cools, what happens?", "choices": ["PaCO₂ falls and cerebral vasoconstriction reduces brain blood flow", "PaCO₂ rises and ICP increases", "PaO₂ rises to toxic levels", "No change occurs"], "correct": 0, "explanation": "↓ temperature → ↓ metabolism → ↓ CO₂ production; unchanged V̇E drops PaCO₂ → vasoconstriction.", "srcItem": "The RT’s job during TH"},
    {"id": "q-f202-s02-060", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What PaO₂ and PaCO₂ targets does the TH deck's slide text give after ROSC?", "choices": ["PaO₂ 60–105 mm Hg; PaCO₂ 35–45 mm Hg", "PaO₂ 150–200 mm Hg; PaCO₂ 25–30 mm Hg", "PaO₂ 40–50 mm Hg; PaCO₂ 50–60 mm Hg", "PaO₂ > 300 mm Hg; PaCO₂ 20–25 mm Hg"], "correct": 0, "explanation": "Slide 28 text (updated): PaCO₂ 35–45, PaO₂ 60–105, MAP ≥ 65.", "srcItem": "The RT’s job during TH"},
    {"id": "q-f202-s02-061", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "During rewarming, how might minute ventilation need to change?", "choices": ["It may need to go back up as CO₂ production rises", "It should be reduced as CO₂ production falls", "It must stay fixed", "It should be set to zero"], "correct": 0, "explanation": "Rewarming reverses the trend: metabolism and CO₂ production rise, so V̇E may need to increase.", "srcItem": "The RT’s job during TH"},
    {"id": "q-f202-s02-062", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which blood gas strategy uses the uncorrected 37 °C values?", "choices": ["Alpha-stat", "pH-stat", "Bohr-stat", "Haldane-stat"], "correct": 0, "explanation": "Alpha-stat uses uncorrected 37 °C values; pH-stat uses temperature-corrected values. Follow the prescribed strategy.", "srcItem": "The RT’s job during TH"},
    {"id": "q-f202-s02-063", "topic": "f202-s02", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why should the RT handle the airway gently during TH?", "choices": ["Suctioning and ABG punctures can bleed when clotting is impaired", "Cooling makes the trachea brittle", "Suctioning raises the core temperature", "Gentle handling prevents shivering"], "correct": 0, "explanation": "Clotting is impaired during TH, so suctioning and punctures can bleed.", "srcItem": "The RT’s job during TH"},
    {"id": "q-f202-s03-001", "topic": "f202-s03", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A patient arrives in obvious respiratory distress. Which type of question is most useful first?", "choices": ["Closed-ended, to get specific information quickly", "Open-ended, to let the patient tell their story", "Leading, to speed the answer", "Compound, to cover several symptoms at once"], "correct": 0, "explanation": "Closed-ended questions are extremely useful when you need specific information quickly, especially in respiratory distress.", "srcItem": "Closed-ended vs Open-ended Questions"},
    {"id": "q-f202-s03-002", "topic": "f202-s03", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which is an open-ended question?", "choices": ["\"Tell me about your breathing today.\"", "\"Do you use oxygen at home?\"", "\"How many liters do you use?\"", "\"Are you short of breath?\""], "correct": 0, "explanation": "Open-ended questions give broader information and let the patient tell their story; they usually start with what, why or how.", "srcItem": "Closed-ended vs Open-ended Questions"},
    {"id": "q-f202-s03-003", "topic": "f202-s03", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What interview strategy does the deck teach?", "choices": ["Start broad with open-ended questions, then narrow with closed-ended ones", "Start with closed-ended questions, then never change", "Use only leading questions to save time", "Ask compound questions to cover everything at once"], "correct": 0, "explanation": "\"Tell me about your cough\" → \"When did it start?\" → \"Is it productive?\" → \"What color is the sputum?\"", "srcItem": "Closed-ended vs Open-ended Questions"},
    {"id": "q-f202-s03-004", "topic": "f202-s03", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "\"You're feeling better after that treatment, aren't you?\" is an example of which questioning technique to avoid?", "choices": ["Leading question", "Open-ended question", "Clarification", "Facilitation"], "correct": 0, "explanation": "A leading question suggests the answer you expect; Hess says it can produce useless, unreliable or inaccurate responses.", "srcItem": "Closed-ended vs Open-ended Questions"},
    {"id": "q-f202-s03-005", "topic": "f202-s03", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the problem with a compound question?", "choices": ["The patient often answers only the last part, so a 'yes' is ambiguous", "It is too open-ended", "It always leads the patient", "It takes too long to answer"], "correct": 0, "explanation": "Compound questions ask several things at once; Hess says patients generally respond to the last part only.", "srcItem": "Closed-ended vs Open-ended Questions"},
    {"id": "q-f202-s03-006", "topic": "f202-s03", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which level of communication is 'cliché conversation'?", "choices": ["Level 5", "Level 1", "Level 3", "Level 2"], "correct": 0, "explanation": "Level 5 is the most superficial (\"How are you today?\" \"Fine.\"); level 1 is peak communication.", "srcItem": "The 5 Levels of Communication"},
    {"id": "q-f202-s03-007", "topic": "f202-s03", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A patient says, \"I'm scared I'm going to end up on the ventilator again.\" Which communication level is this?", "choices": ["Level 2 — feelings and emotions", "Level 4 — reporting facts", "Level 5 — cliché conversation", "Level 1 — peak communication"], "correct": 0, "explanation": "Level 2 is feelings and emotions: the patient trusts you enough to say how they actually feel.", "srcItem": "The 5 Levels of Communication"},
    {"id": "q-f202-s03-008", "topic": "f202-s03", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which levels does the deck call the 'sweet spot' for therapeutic communication?", "choices": ["Levels 2–3", "Levels 4–5", "Level 1 only", "Levels 1–2"], "correct": 0, "explanation": "The RT should move past levels 4–5 to reach meaningful therapeutic communication, often levels 2–3.", "srcItem": "The 5 Levels of Communication"},
    {"id": "q-f202-s03-009", "topic": "f202-s03", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "\"I've been coughing for three days\" belongs to which communication level?", "choices": ["Level 4 — reporting facts", "Level 3 — personal ideas", "Level 2 — feelings", "Level 5 — cliché"], "correct": 0, "explanation": "Level 4 is exchanging objective information, where much routine healthcare communication occurs.", "srcItem": "The 5 Levels of Communication"},
    {"id": "q-f202-s03-010", "topic": "f202-s03", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why is level 1 (peak communication) NOT the goal in the RT–patient relationship?", "choices": ["It is intimate and reserved for close personal relationships", "It is too superficial", "It only involves reporting facts", "It requires an interpreter"], "correct": 0, "explanation": "Level 1 is \"highest level; intimate; reserved for select few\" — professional boundaries matter.", "srcItem": "The 5 Levels of Communication"},
    {"id": "q-f202-s03-011", "topic": "f202-s03", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the intimate zone distance in the deck?", "choices": ["0 to 1.5 ft (1″ to 18″)", "1.5 to 4 ft", "4 to 12 ft", "12 to 25 ft"], "correct": 0, "explanation": "Intimate 0–1.5 ft (1″–18″); personal 1.5–4 ft; social 4–12 ft; public 12–25 ft.", "srcItem": "Social, Personal, and Intimate Space"},
    {"id": "q-f202-s03-012", "topic": "f202-s03", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Interviewing or educating a patient one-on-one usually happens in which zone?", "choices": ["Personal space, 1.5 to 4 ft", "Intimate space, 0 to 1.5 ft", "Social space, 4 to 12 ft", "Public space, 12 to 25 ft"], "correct": 0, "explanation": "Personal space (1.5–4 ft) is the comfortable distance for one-on-one conversation with a patient.", "srcItem": "Social, Personal, and Intimate Space"},
    {"id": "q-f202-s03-013", "topic": "f202-s03", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which RT task takes place in the patient's intimate space?", "choices": ["Placing a BiPAP mask", "Leading a group education class", "Speaking to coworkers in a meeting", "Giving a lecture"], "correct": 0, "explanation": "Suctioning, auscultating, masking, intubating and drawing an ABG all occur inside the intimate zone.", "srcItem": "Social, Personal, and Intimate Space"},
    {"id": "q-f202-s03-014", "topic": "f202-s03", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is proxemics?", "choices": ["The use and interpretation of space between people", "The study of body motion", "The tone and pitch of voice", "The use of touch in care"], "correct": 0, "explanation": "Proxemics is how physical distance affects communication; kinesics is body motion and paralinguistics is vocal characteristics.", "srcItem": "Social, Personal, and Intimate Space"},
    {"id": "q-f202-s03-015", "topic": "f202-s03", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What should the RT do before entering a patient's intimate space?", "choices": ["Explain what they are about to do and ask permission", "Enter quickly so the patient is not alarmed", "Wait until the patient is asleep", "Ask a family member to leave first"], "correct": 0, "explanation": "E.g. \"I'm going to listen to your lungs now. Is that okay?\" — don't take the privilege for granted.", "srcItem": "Social, Personal, and Intimate Space"},
    {"id": "q-f202-s03-016", "topic": "f202-s03", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "According to the 3 V's, what percentage of communication is visual?", "choices": ["55%", "7%", "38%", "93%"], "correct": 0, "explanation": "Verbal 7%, vocal 38%, visual 55%; therefore 93% is nonverbal (Mehrabian, an overgeneralization).", "srcItem": "The 3 V's of Communication"},
    {"id": "q-f202-s03-017", "topic": "f202-s03", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which of the 3 V's includes tone, volume, pitch and rate?", "choices": ["Vocal (38%)", "Verbal (7%)", "Visual (55%)", "Vibrational (0%)"], "correct": 0, "explanation": "Vocal = 38%: tone, volume, pitch, rate. Verbal = the words; visual = expressions, gestures, posture.", "srcItem": "The 3 V's of Communication"},
    {"id": "q-f202-s04-001", "topic": "f202-s04", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "On the Burn deck's pulmonary-mechanics slide, what is the normal static compliance range?", "choices": ["70–100 mL/cm H₂O", "50–100 mL/cm H₂O", "20–30 mL/cm H₂O", "200 mL/cm H₂O"], "correct": 0, "explanation": "Burn deck slide 37: lung compliance 50–100 and static compliance 70–100 mL/cm H₂O.", "srcItem": "Static and Dynamic Lung Compliance Ranges"},
    {"id": "q-f202-s04-002", "topic": "f202-s04", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "On the Burn deck, what range is listed as 'lung compliance (how easily the lungs expand)'?", "choices": ["50–100 mL/cm H₂O", "70–100 mL/cm H₂O", "10–20 mL/cm H₂O", "150–200 mL/cm H₂O"], "correct": 0, "explanation": "Use the Burn deck's 50–100 (\"lung compliance\") and 70–100 (\"static\") on this exam.", "srcItem": "Static and Dynamic Lung Compliance Ranges"},
    {"id": "q-f202-s04-003", "topic": "f202-s04", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which pressure is used to calculate dynamic compliance, and which for static compliance?", "choices": ["PIP for dynamic; Pplat for static", "Pplat for dynamic; PIP for static", "PEEP for both", "Mean airway pressure for both"], "correct": 0, "explanation": "Principles of MV: use PIP for dynamic compliance and Pplat for static compliance.", "srcItem": "Static vs Dynamic Compliance"},
    {"id": "q-f202-s04-004", "topic": "f202-s04", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "VT 320 mL, Pplat 40 cm H₂O, PEEP 26 cm H₂O. What is the static compliance?", "choices": ["About 23 mL/cm H₂O", "About 8 mL/cm H₂O", "About 12 mL/cm H₂O", "About 80 mL/cm H₂O"], "correct": 0, "explanation": "320 ÷ (40 − 26) = 320 ÷ 14 ≈ 23 mL/cm H₂O — decreased, below the acceptable 50–100.", "srcItem": "Static vs Dynamic Compliance"},
    {"id": "q-f202-s04-005", "topic": "f202-s04", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why does dynamic compliance read lower than static compliance?", "choices": ["Its PIP-based denominator includes the airway-resistance pressure", "It is measured with no airflow", "It excludes PEEP", "It uses the exhaled VT only"], "correct": 0, "explanation": "PIP − PEEP = resistive (PIP − Pplat) + elastic (Pplat − PEEP) pressure, so Cdyn includes resistance.", "srcItem": "Static vs Dynamic Compliance"},
    {"id": "q-f202-s04-006", "topic": "f202-s04", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "During volume control, airway resistance rises but lung compliance is unchanged. What happens?", "choices": ["PIP rises, Pplat is unchanged, and Cdyn falls", "PIP and Pplat both rise equally", "Pplat rises and PIP is unchanged", "Cstat falls and Cdyn rises"], "correct": 0, "explanation": "↑ Raw: ↑ PIP, ↑ PIP − Pplat, no change in Pplat, ↓ Cdyn.", "srcItem": "Static vs Dynamic Compliance"},
    {"id": "q-f202-s04-007", "topic": "f202-s04", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Compliance decreases while airway resistance is unchanged. What happens to PIP and Pplat?", "choices": ["Both rise, and PIP − Pplat stays the same", "Only PIP rises", "Only Pplat falls", "Both fall"], "correct": 0, "explanation": "↓ Crs: ↑ PIP and ↑ Pplat with no change in PIP − Pplat; Cdyn and Crs fall proportionately.", "srcItem": "Static vs Dynamic Compliance"},
    {"id": "q-f202-s04-008", "topic": "f202-s04", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What COHb level does RCP 203 list as CO poisoning?", "choices": ["> 20%", "1–3%", "5–10%", "10–15%"], "correct": 0, "explanation": "COHb 1–3% WNL; 5–10% smokers; 10–15% heavy smokers; > 20% CO poisoning.", "srcItem": "Carbon Monoxide (CO) Levels: COHb percentages"},
    {"id": "q-f202-s04-009", "topic": "f202-s04", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A heavy smoker's COHb would typically be in which range per RCP 203?", "choices": ["10–15%", "1–3%", "Under 1%", "Over 40%"], "correct": 0, "explanation": "RCP 203 Lssn 3a/3b: heavy smokers 10–15%.", "srcItem": "Carbon Monoxide (CO) Levels: COHb percentages"},
    {"id": "q-f202-s04-010", "topic": "f202-s04", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "For mild–moderate CO poisoning on a non-rebreather, what is the treatment end point?", "choices": ["COHb less than 5%", "COHb less than 20%", "SpO₂ above 95%", "PaO₂ above 100 mm Hg"], "correct": 0, "explanation": "Give 100% O₂ until COHb is less than 5% (RCP 105 Nontraditional Settings).", "srcItem": "Carbon Monoxide (CO) Levels: COHb percentages"},
    {"id": "q-f202-s04-011", "topic": "f202-s04", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How strongly does CO bind to hemoglobin compared with O₂ (Burn deck)?", "choices": ["About 200–250 times more strongly", "About 2 times more strongly", "About the same", "About 10 times less strongly"], "correct": 0, "explanation": "CO binds Hb about 200–250× more strongly (RCP 203 says about 210×), forming COHb.", "srcItem": "Carbon Monoxide (CO) Levels: COHb percentages"},
    {"id": "q-f202-s04-012", "topic": "f202-s04", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which way does carbon monoxide shift the oxyhemoglobin dissociation curve?", "choices": ["To the left, so O₂ is released less readily", "To the right, so O₂ is released more readily", "It does not shift it", "Upward without a shift"], "correct": 0, "explanation": "COHb causes a leftward shift, so the remaining O₂ is held more tightly.", "srcItem": "Carbon Monoxide (CO) Levels: COHb percentages"},
    {"id": "q-f202-s04-013", "topic": "f202-s04", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How should carboxyhemoglobin be measured?", "choices": ["CO-oximetry on an arterial blood sample", "Standard two-wavelength pulse oximetry", "PaO₂ on a blood gas", "Capnography"], "correct": 0, "explanation": "Measure COHb with CO-oximetry; a normal PaO₂/SpO₂ does not rule out CO poisoning.", "srcItem": "How CO Is Measured"},
    {"id": "q-f202-s04-014", "topic": "f202-s04", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why can the PaO₂ be normal in CO poisoning?", "choices": ["PaO₂ measures dissolved O₂ in plasma, not O₂ on hemoglobin", "CO raises the PaO₂ directly", "The analyzer subtracts COHb automatically", "CO only affects venous blood"], "correct": 0, "explanation": "PaO₂ reflects dissolved O₂, not O₂ bound to Hb, so it can be normal despite severe CO poisoning.", "srcItem": "How CO Is Measured"},
    {"id": "q-f202-s04-015", "topic": "f202-s04", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A pulse oximeter reads 90% and the COHb is 7%. What is the true saturation?", "choices": ["83%", "97%", "90%", "63%"], "correct": 0, "explanation": "Subtract COHb from SpO₂: 90 − 7 = 83%. Pulse oximeters read falsely high with COHb.", "srcItem": "How CO Is Measured"},
    {"id": "q-f202-s04-016", "topic": "f202-s04", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Exhaled CO is 48 ppm in a conscious, cooperative patient. What is the estimated HbCO?", "choices": ["About 8%", "About 48%", "About 4%", "About 24%"], "correct": 0, "explanation": "Quick screen: exhaled CO ppm ÷ 6 ≈ HbCO% → 48 ÷ 6 ≈ 8%.", "srcItem": "How CO Is Measured"},
    {"id": "q-f202-s04-017", "topic": "f202-s04", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the approximate COHb half-life on room air (Burn deck)?", "choices": ["About 4–5 hours", "About 60–90 minutes", "About 20–30 minutes", "About 24 hours"], "correct": 0, "explanation": "Room air ~4–5 h; 100% O₂ ~60–90 min; HBO ~20–30 min.", "srcItem": "COHb Half-Life and Treatment of CO Poisoning"},
    {"id": "q-f202-s04-018", "topic": "f202-s04", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the approximate COHb half-life on 100% O₂ (Burn deck)?", "choices": ["About 60–90 minutes", "About 4–5 hours", "About 5 minutes", "About 12 hours"], "correct": 0, "explanation": "Use the deck's 60–90 minutes; Hess gives about 74 minutes.", "srcItem": "COHb Half-Life and Treatment of CO Poisoning"},
    {"id": "q-f202-s04-019", "topic": "f202-s04", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A spontaneously breathing patient with CO poisoning arrives. What is the first treatment?", "choices": ["100% O₂ by tight-fitting non-rebreather", "Nasal cannula at 2 L/min", "Wait for the COHb result before starting O₂", "Hyperbaric oxygen before any other O₂"], "correct": 0, "explanation": "Give 100% O₂ immediately; don't delay O₂ while deciding about hyperbarics.", "srcItem": "COHb Half-Life and Treatment of CO Poisoning"},
    {"id": "q-f202-s04-020", "topic": "f202-s04", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is a typical HBO protocol for CO poisoning?", "choices": ["3 atm for the first treatment for 90 minutes, with two 10-minute air breaks", "1 atm for 6 hours with no breaks", "5 atm for 15 minutes", "2 atm continuously for 24 hours"], "correct": 0, "explanation": "3 atm first, then 2 or 3 atm for later treatments, 90 minutes, with two 10-minute air breaks to reduce O₂-toxicity seizures.", "srcItem": "COHb Half-Life and Treatment of CO Poisoning"},
    {"id": "q-f202-s04-021", "topic": "f202-s04", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why can an HbCO level rebound several hours after normobaric O₂?", "choices": ["Carboxymyoglobin dissociates more slowly than HbCO", "The pulse oximeter recalibrates", "CO is produced by the liver", "The O₂ was given too fast"], "correct": 0, "explanation": "Hess: MbCO dissociates more slowly than HbCO, causing a rebound of HbCO hours later.", "srcItem": "COHb Half-Life and Treatment of CO Poisoning"},
    {"id": "q-f202-s04-022", "topic": "f202-s04", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What causes decreased compliance in inhalation injury?", "choices": ["Increased alveolar-capillary permeability leading to pulmonary edema", "Increased surfactant production", "Bronchodilation", "Decreased capillary permeability"], "correct": 0, "explanation": "Inflammation → ↑ permeability → pulmonary edema → ↓ compliance, an ARDS-like picture.", "srcItem": "Why Compliance Falls in Burn and Inhalation Injury"},
    {"id": "q-f202-s04-023", "topic": "f202-s04", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A patient with circumferential chest burns needs high airway pressures. What procedure may be required?", "choices": ["Chest escharotomy", "Thoracentesis", "Tracheostomy", "Bronchoscopy"], "correct": 0, "explanation": "Rigid eschar restricts chest expansion; a chest escharotomy may be required.", "srcItem": "Why Compliance Falls in Burn and Inhalation Injury"},
    {"id": "q-f202-s04-024", "topic": "f202-s04", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which ventilator plan does the Burn deck give for burn patients with lung injury?", "choices": ["VT about 6 mL/kg PBW and Pplat ≤ 30 cm H₂O", "VT 12 mL/kg and Pplat ≤ 50 cm H₂O", "VT 3 mL/kg and no PEEP", "VT 10 mL/kg with PIP ≤ 60 cm H₂O"], "correct": 0, "explanation": "Deck: VT ≈ 6 mL/kg PBW, Pplat ≤ 30 cm H₂O, appropriate PEEP, avoid VILI.", "srcItem": "Why Compliance Falls in Burn and Inhalation Injury"},
    {"id": "q-f202-s04-025", "topic": "f202-s04", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does hydrogen cyanide harm the patient?", "choices": ["It blocks cytochrome oxidase so cells cannot use O₂", "It binds hemoglobin more tightly than CO", "It causes bronchodilation", "It raises the PaO₂"], "correct": 0, "explanation": "HCN binds the cytochrome oxidase system → cells can't use O₂ → tissue and systemic acidosis.", "srcItem": "CO vs Hydrogen Cyanide"},
    {"id": "q-f202-s04-026", "topic": "f202-s04", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the antidote for suspected severe cyanide poisoning in a burn victim?", "choices": ["Hydroxocobalamin (Cyanokit)", "Naloxone", "Atropine", "Flumazenil"], "correct": 0, "explanation": "Give 100% O₂ plus hydroxocobalamin, which binds cyanide to form cyanocobalamin (vitamin B12).", "srcItem": "CO vs Hydrogen Cyanide"},
    {"id": "q-f202-s05-001", "topic": "f202-s05", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the single structural difference between VV and VA ECMO?", "choices": ["Where the oxygenated blood is returned — a vein (VV) or an artery (VA)", "Where the blood is drained from", "The type of oxygenator used", "Whether sweep gas is used"], "correct": 0, "explanation": "Identical circuit; the return cannula is the entire difference. Follow the RETURN cannula.", "srcItem": "Access Points: where the cannulas go"},
    {"id": "q-f202-s05-002", "topic": "f202-s05", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In adult VA ECMO, which vessel is the most common arterial return site?", "choices": ["Femoral artery", "Carotid artery", "Radial artery", "Pulmonary artery"], "correct": 0, "explanation": "VA in adolescents/adults: femoral vein → femoral artery (most common); carotid artery is typical in neonates and young children.", "srcItem": "Access Points: where the cannulas go"},
    {"id": "q-f202-s05-003", "topic": "f202-s05", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Where is a single-site dual-lumen VV ECMO catheter usually placed?", "choices": ["Right internal jugular vein", "Femoral artery", "Left radial artery", "Carotid artery"], "correct": 0, "explanation": "The dual-lumen catheter drains the vena cavae and returns to the right atrium, usually via the right IJ.", "srcItem": "Access Points: where the cannulas go"},
    {"id": "q-f202-s05-004", "topic": "f202-s05", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "For which patient is single-site dual-lumen VV ECMO best suited?", "choices": ["A less hypoxemic patient who may mobilize, such as a bridge to lung transplant", "A septic patient needing the highest possible blood flow", "A neonate needing cardiac support", "A patient in cardiogenic shock"], "correct": 0, "explanation": "It cannot achieve high flows needed in some sepsis/severe hypoxemia, so it is reserved for less severe hypoxemia with mobility, such as a transplant bridge.", "srcItem": "Access Points: where the cannulas go"},
    {"id": "q-f202-s05-005", "topic": "f202-s05", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "On VV ECMO, the drainage blood becomes brighter red and the SpO₂ falls. What is the likely problem?", "choices": ["Recirculation", "Oxygenator failure", "Sweep gas set too low", "Pulmonary embolism"], "correct": 0, "explanation": "Recirculation = oxygenated blood going back through the circuit; signs are brighter venous drainage, ↑ SvO₂, and ↓ SpO₂.", "srcItem": "Access Points: where the cannulas go"},
    {"id": "q-f202-s05-006", "topic": "f202-s05", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is commonly done to correct recirculation on ECMO?", "choices": ["Decrease ECMO flow and confirm cannula position", "Increase the sweep gas to 10 L/min", "Increase the ventilator FiO₂ to 1.0", "Add a second oxygenator"], "correct": 0, "explanation": "Recirculation can often be fixed by decreasing ECMO flow and confirming cannula position.", "srcItem": "Access Points: where the cannulas go"},
    {"id": "q-f202-s05-007", "topic": "f202-s05", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "On the study guide, 'inclusion criteria' for ECMO means the same as what?", "choices": ["Indications", "Contraindications", "Complications", "Weaning criteria"], "correct": 0, "explanation": "Word play from the study guide: \"Inclusion criteria = Indication.\"", "srcItem": "Inclusion Criteria (= Indications)"},
    {"id": "q-f202-s05-008", "topic": "f202-s05", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the most common indication for VV ECMO?", "choices": ["Severe ARDS", "Status asthmaticus", "Pulmonary hemorrhage", "Meconium aspiration"], "correct": 0, "explanation": "Severe ARDS is the most common indication; others include status asthmaticus, PE, PPHN, CDH, MAS and bridge to transplant.", "srcItem": "Inclusion Criteria (= Indications)"},
    {"id": "q-f202-s05-009", "topic": "f202-s05", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which patient meets the basic gate for ECMO?", "choices": ["Severe, potentially reversible respiratory failure despite lung-protective ventilation", "Terminal malignancy with short life expectancy", "Irreversible coagulopathy", "Severe irreversible brain injury"], "correct": 0, "explanation": "ECMO is reserved for a reversible process (or bridge to transplant) that conventional lung-protective strategies cannot manage.", "srcItem": "Inclusion Criteria (= Indications)"},
    {"id": "q-f202-s05-010", "topic": "f202-s05", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "At what predicted mortality does the deck say to consider ECMO?", "choices": ["≥ 50%, more strongly as it approaches 80%", "≥ 10%", "≥ 95% only", "≥ 30%, more strongly at 40%"], "correct": 0, "explanation": "Deck slide 13: consider at ≥ 50%; more strongly as predicted mortality approaches 80%.", "srcItem": "Inclusion Criteria (= Indications)"},
    {"id": "q-f202-s05-011", "topic": "f202-s05", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How is the oxygenation index calculated?", "choices": ["(P̄aw × FiO₂ × 100) ÷ PaO₂", "PaO₂ ÷ FiO₂", "(PIP − PEEP) × FiO₂", "VT ÷ (Pplat − PEEP)"], "correct": 0, "explanation": "OI = (mean airway pressure × FiO₂ × 100) ÷ PaO₂; OI 0–10 normal; 25–40 may indicate ECMO.", "srcItem": "Inclusion Criteria (= Indications)"},
    {"id": "q-f202-s05-012", "topic": "f202-s05", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which P/F criteria did the EOLIA trial use for ECMO?", "choices": ["P/F < 80 for 6 hours or < 50 for 3 hours", "P/F < 300 for 24 hours", "P/F < 200 for 1 hour", "P/F < 150 for 12 hours"], "correct": 0, "explanation": "EOLIA: P/F < 80 for 6 h or < 50 for 3 h; respiratory acidosis pH < 7.20–7.25 also counted.", "srcItem": "Inclusion Criteria (= Indications)"},
    {"id": "q-f202-s05-013", "topic": "f202-s05", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Under current guidelines, which pre-ECMO course is a contraindication?", "choices": ["High ventilator settings (FiO₂ > 0.9, Pplat > 30) for 7 days or more", "Ventilation for 12 hours", "Prone positioning for 16 hours", "Neuromuscular blockade for 48 hours"], "correct": 0, "explanation": "High settings for ≥ 7 days is a contraindication; newer data suggest mortality rises after 10–14 days.", "srcItem": "Inclusion Criteria (= Indications)"},
    {"id": "q-f202-s05-014", "topic": "f202-s05", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which is an absolute contraindication to ECMO?", "choices": ["Irreversible coagulopathy", "Severe ARDS", "Status asthmaticus", "Pulmonary embolism"], "correct": 0, "explanation": "Absolute contraindications are rare: irreversible coagulopathy, inability to cannulate, and futility.", "srcItem": "Inclusion Criteria (= Indications)"},
    {"id": "q-f202-s05-015", "topic": "f202-s05", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which factors predict higher ECMO mortality?", "choices": ["Increasing age, multiorgan dysfunction and prolonged pre-ECMO ventilation", "Young age and a single organ failure", "Status asthmaticus", "Short pre-ECMO ventilation"], "correct": 0, "explanation": "Both sources: increasing age, multiorgan dysfunction, and prolonged mechanical ventilation before ECMO.", "srcItem": "Inclusion Criteria (= Indications)"},
    {"id": "q-f202-s05-016", "topic": "f202-s05", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which type of ECMO supports BOTH cardiac and respiratory failure?", "choices": ["VA ECMO", "VV ECMO", "Single-site VV ECMO", "ECCO₂R only"], "correct": 0, "explanation": "VV = respiratory support only; VA = cardiac AND respiratory support.", "srcItem": "Difference Between VV and VA ECMO"},
    {"id": "q-f202-s05-017", "topic": "f202-s05", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A patient with severe ARDS also has cardiogenic shock. Why is VV ECMO not enough?", "choices": ["VV does not pump oxygenated blood into the arterial circulation, so the heart must still provide output", "VV cannot remove CO₂", "VV cannot oxygenate blood", "VV requires a functioning kidney"], "correct": 0, "explanation": "VV \"requires an adequate cardiac function\"; the patient's own heart must distribute the blood.", "srcItem": "Difference Between VV and VA ECMO"},
    {"id": "q-f202-s05-018", "topic": "f202-s05", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which ECMO type is preferred for respiratory failure, and why?", "choices": ["VV, for simplicity and a more favorable safety profile", "VA, because it always gives better oxygenation", "VA, because it has fewer strokes", "VV, because it supports the heart"], "correct": 0, "explanation": "VV is preferred for respiratory failure; VA is a salvage technique due to ischemia, stroke and vascular complications.", "srcItem": "Difference Between VV and VA ECMO"},
    {"id": "q-f202-s05-019", "topic": "f202-s05", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which complication is much more common with VA than with VV ECMO?", "choices": ["Limb ischemia", "Catheter-associated DVT", "Recirculation", "Hypercapnia"], "correct": 0, "explanation": "VA: limb ischemia in 17% (5% need amputation); VV has much less limb-ischemia risk but frequent catheter-associated DVT.", "srcItem": "Difference Between VV and VA ECMO"},
    {"id": "q-f202-s05-020", "topic": "f202-s05", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What reported survival range does the deck give for severe respiratory failure treated with VV ECMO?", "choices": ["50–70%", "30–50%", "10–20%", "90–100%"], "correct": 0, "explanation": "VV for severe respiratory failure 50–70%; VA for severe cardiac failure 30–50%.", "srcItem": "Difference Between VV and VA ECMO"},
    {"id": "q-f202-s05-021", "topic": "f202-s05", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "On ECMO, which setting mainly controls oxygenation?", "choices": ["Blood flow (plus the sweep FiO₂)", "Sweep gas flow", "Ventilator rate", "Ventilator PEEP alone"], "correct": 0, "explanation": "Oxygenation → think BLOOD FLOW + FiO₂; CO₂ removal → think SWEEP FLOW.", "srcItem": "The Two Knobs: blood flow vs sweep gas"},
    {"id": "q-f202-s05-022", "topic": "f202-s05", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "The PaCO₂ on ECMO is rising. What adjustment lowers it?", "choices": ["Increase the sweep gas flow", "Decrease the blood flow", "Decrease the sweep gas flow", "Increase the ventilator FiO₂"], "correct": 0, "explanation": "↑ sweep flow → ↑ CO₂ removal → ↓ PaCO₂.", "srcItem": "The Two Knobs: blood flow vs sweep gas"},
    {"id": "q-f202-s05-023", "topic": "f202-s05", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why can the ventilator rate be set below 10 during ECMO?", "choices": ["The sweep gas removes much of the CO₂", "The patient no longer needs PEEP", "Blood flow controls the respiratory drive", "ECMO prevents atelectasis"], "correct": 0, "explanation": "Resting settings (VT < 6 mL/kg, FiO₂ < 60%, RR < 10, PIP < 35, PEEP 10–15) work because sweep gas removes CO₂.", "srcItem": "The Two Knobs: blood flow vs sweep gas"},
    {"id": "q-f202-s05-024", "topic": "f202-s05", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which ventilator settings fit the deck's 'resting' pattern on ECMO?", "choices": ["VT < 6 mL/kg, FiO₂ < 60%, RR < 10, Pplat < 30, PEEP 10–15", "VT 10 mL/kg, FiO₂ 100%, RR 30, PEEP 0", "VT 8 mL/kg, FiO₂ 80%, RR 20, PEEP 20", "VT 12 mL/kg, FiO₂ 21%, RR 4, PEEP 0"], "correct": 0, "explanation": "Pattern: low VT, ↓ FiO₂, ↓ RR, ↓ PIP/Pplat, ↓ driving pressure, enough PEEP to maintain recruitment.", "srcItem": "The Two Knobs: blood flow vs sweep gas"},
    {"id": "q-f202-s05-025", "topic": "f202-s05", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How should 'severe ARDS survival on ECMO' be answered, per the slide?", "choices": ["Greater than 54%", "Exactly 30%", "Below 20%", "100%"], "correct": 0, "explanation": "Slide 22: severe ARDS survival on ECMO > 54%; trials reported 56% (CESAR) and 60% (EOLIA).", "srcItem": "Where the Deck and Hess Disagree: the traps"},
    {"id": "q-f202-s05-026", "topic": "f202-s05", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the most common complication of ECMO?", "choices": ["Bleeding", "Infection", "Stroke", "Recirculation"], "correct": 0, "explanation": "Bleeding is the most common complication; others are neurologic injury, infection, and vascular injury/thrombosis.", "srcItem": "Where the Deck and Hess Disagree: the traps"},
    {"id": "q-f202-s05-027", "topic": "f202-s05", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "The increase in survival from 57% (1993) to 72% (2007) on the slide applies to which group?", "choices": ["Children without comorbidities", "All adults with ARDS", "Patients on VA ECMO for cardiac arrest", "Neonates with CDH"], "correct": 0, "explanation": "Hess: those numbers are for children without comorbidities.", "srcItem": "Where the Deck and Hess Disagree: the traps"},
    {"id": "q-f202-s05-028", "topic": "f202-s05", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What survival rate do both sources give for near-fatal asthma treated with ECMO?", "choices": ["84%", "34%", "54%", "24%"], "correct": 0, "explanation": "Shared outcome numbers: near-fatal asthma survival 84%; median ECMO duration in ARDS 9–15 days.", "srcItem": "Where the Deck and Hess Disagree: the traps"},
    {"id": "q-f202-s06-001", "topic": "f202-s06", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is normal daily urine output for an adult (Renal deck)?", "choices": ["1–2 L/day", "200 L/day", "5–6 L/day", "100–200 mL/day"], "correct": 0, "explanation": "The kidneys filter nearly 200 L/day but reabsorb most of it, so normal urine output is only 1–2 L/day.", "srcItem": "Urinary Output"},
    {"id": "q-f202-s06-002", "topic": "f202-s06", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Using the Diuretics deck ranges, what is normal hourly urine output?", "choices": ["30–60 mL/hr", "5–10 mL/hr", "100–150 mL/hr", "200–300 mL/hr"], "correct": 0, "explanation": "Normal 30–60 mL/hr; oliguria < 30 mL/hr; anuria < 50 mL/day; polyuria > 60 mL/hr.", "srcItem": "Urinary Output"},
    {"id": "q-f202-s06-003", "topic": "f202-s06", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A patient's urine output is 20 mL/hr. How is this classified using the Diuretics deck?", "choices": ["Oliguria", "Normal", "Polyuria", "Anuria"], "correct": 0, "explanation": "Oliguria is < 30 mL/hr; oliguria or anuria are signs of renal failure.", "srcItem": "Urinary Output"},
    {"id": "q-f202-s06-004", "topic": "f202-s06", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What urine output defines anuria in the Diuretics deck?", "choices": ["< 50 mL/day", "< 30 mL/hr", "< 400 mL/day", "< 1 L/day"], "correct": 0, "explanation": "Anuria < 50 mL/day — the more severe emergency (nearly complete kidney failure, dehydration or total obstruction).", "srcItem": "Urinary Output"},
    {"id": "q-f202-s06-005", "topic": "f202-s06", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why do patients on positive pressure ventilation make less urine?", "choices": ["↓ cardiac output and renal perfusion, ↑ ADH and ↓ atrial natriuretic factor", "↑ renal blood flow and ↓ ADH", "↑ ANF release from the atria", "Direct injury to the nephrons from PEEP"], "correct": 0, "explanation": "PPV → ↓ CO and renal perfusion, ↑ ADH, ↓ ANF → reduced urine output and fluid retention.", "srcItem": "Urinary Output"},
    {"id": "q-f202-s06-006", "topic": "f202-s06", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "While IV KCl is running, what urine output should be maintained?", "choices": ["> 40 to 50 mL/hour", "> 5 mL/hour", "> 200 mL/hour", "Any amount, as long as the patient is on dialysis"], "correct": 0, "explanation": "Management of MV deck: during IV KCl, UOP should be > 40 to 50 mL/hour.", "srcItem": "Urinary Output"},
    {"id": "q-f202-s06-007", "topic": "f202-s06", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why does DKA cause polyuria and polydipsia?", "choices": ["High blood glucose causes an osmotic diuresis and dehydration", "Ketones block ADH release", "Insulin causes excess urine production", "Acidosis increases thirst directly"], "correct": 0, "explanation": "Excess blood glucose → osmotic diuresis → dehydration → thirst (polydipsia) and frequent urination (polyuria).", "srcItem": "Diabetic Ketoacidosis"},
    {"id": "q-f202-s06-008", "topic": "f202-s06", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In DKA, why does the body produce ketone bodies?", "choices": ["Without insulin, cells cannot use glucose, so fat is broken down for energy", "Excess insulin forces fat breakdown", "The liver converts lactate into ketones", "Ketones are made by the kidney to buffer acid"], "correct": 0, "explanation": "No insulin → glucose cannot enter cells → fat breakdown → acidic ketone bodies → metabolic acidosis.", "srcItem": "Diabetic Ketoacidosis"},
    {"id": "q-f202-s06-009", "topic": "f202-s06", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the deck's treatment line for DKA?", "choices": ["Immediate fluid resuscitation and insulin, with electrolytes", "Bicarbonate and hyperventilation on the ventilator", "Glucose infusion and diuretics", "Oxygen therapy only"], "correct": 0, "explanation": "\"DKA is life-threatening and requires immediate fluid resuscitation and insulin therapy\" (plus electrolytes).", "srcItem": "Diabetic Ketoacidosis"},
    {"id": "q-f202-s06-010", "topic": "f202-s06", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why do ketone acids need the kidneys rather than the lungs to be removed?", "choices": ["They are fixed acids the lungs cannot exhale", "They are volatile acids exhaled as CO₂", "They are neutralized in the liver only", "They are removed by sweat"], "correct": 0, "explanation": "The lungs remove only carbonic acid (as CO₂); the kidneys remove fixed acids — phosphoric, uric, lactic and ketone acids.", "srcItem": "Diabetic Ketoacidosis"},
    {"id": "q-f202-s06-011", "topic": "f202-s06", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which class of diuretics has the strongest diabetogenic activity?", "choices": ["Thiazides", "Loop diuretics", "Potassium-sparing diuretics", "Carbonic anhydrase inhibitors"], "correct": 0, "explanation": "Thiazides raise serum glucose, and some cases of DKA have been reported.", "srcItem": "Diabetic Ketoacidosis"},
    {"id": "q-f202-s06-012", "topic": "f202-s06", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "ABG: pH 6.98, PaCO₂ 24, HCO₃⁻ 6, PaO₂ 98 on room air in a patient with DKA. What is the interpretation?", "choices": ["Severe metabolic acidosis with partial respiratory compensation", "Respiratory acidosis with hypoxemia", "Fully compensated metabolic acidosis", "Metabolic alkalosis"], "correct": 0, "explanation": "Low pH and HCO₃⁻ with a low PaCO₂ (Kussmaul compensation) that cannot normalize the pH = partial compensation; PaO₂ is normal.", "srcItem": "DKA on the ABG"},
    {"id": "q-f202-s06-013", "topic": "f202-s06", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How is the anion gap calculated?", "choices": ["Na⁺ − (Cl⁻ + HCO₃⁻)", "(Na⁺ + K⁺) − HCO₃⁻", "Cl⁻ − (Na⁺ + HCO₃⁻)", "HCO₃⁻ − Cl⁻"], "correct": 0, "explanation": "AG = [Na⁺] − (Cl⁻ + HCO₃⁻); normal 9–14 mEq/L (RCP 103 ABG deck).", "srcItem": "DKA on the ABG"},
    {"id": "q-f202-s06-014", "topic": "f202-s06", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Na⁺ 140, Cl⁻ 105, HCO₃⁻ 10. What is the anion gap and what does it suggest?", "choices": ["25 — high-gap metabolic acidosis such as ketoacidosis", "11 — normal", "35 — metabolic alkalosis", "5 — low-gap acidosis"], "correct": 0, "explanation": "140 − (105 + 10) = 25, above 14 → excess fixed acids (ketoacidosis).", "srcItem": "DKA on the ABG"},
    {"id": "q-f202-s06-015", "topic": "f202-s06", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which condition causes a NORMAL anion gap metabolic acidosis?", "choices": ["Severe diarrhea", "Diabetic ketoacidosis", "Lactic acidosis", "Alcoholic ketoacidosis"], "correct": 0, "explanation": "Diarrhea loses HCO₃⁻; Cl⁻ rises to replace it (hyperchloremic acidosis), so the gap stays normal.", "srcItem": "DKA on the ABG"},
    {"id": "q-f202-s06-016", "topic": "f202-s06", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What breathing pattern is typical of severe DKA?", "choices": ["Kussmaul: deep and rapid, regular, without apnea", "Cheyne-Stokes with periods of apnea", "Biot's irregular breathing", "Slow shallow breathing"], "correct": 0, "explanation": "Kussmaul = deep and rapid, \"air hungry,\" regular rhythm without apnea — compensation for metabolic acidosis.", "srcItem": "DKA on the ABG"},
    {"id": "q-f202-s06-017", "topic": "f202-s06", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A ventilated patient with DKA has a low PaCO₂ that is compensating for the acidosis. What should the therapist do?", "choices": ["Not reduce ventilation; treat the underlying cause", "Reduce the rate to bring PaCO₂ to 40", "Increase ventilation further to correct the acidosis", "Add dead space to raise the PaCO₂"], "correct": 0, "explanation": "Ventilator frequency must not be reduced when hyperventilation is compensating for metabolic acidosis; correct the cause.", "srcItem": "DKA on the ABG"},
    {"id": "q-f202-s06-018", "topic": "f202-s06", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "For every 1 mEq/L fall in HCO₃⁻, how much does PaCO₂ fall during respiratory compensation?", "choices": ["About 1.2 mm Hg", "About 10 mm Hg", "About 0.1 mm Hg", "About 5 mm Hg"], "correct": 0, "explanation": "PaCO₂ falls ~1.2 mm Hg per 1 mEq/L fall in HCO₃⁻; it starts within the first hour and is complete by 12–24 hours.", "srcItem": "DKA on the ABG"},
    {"id": "q-f202-s06-019", "topic": "f202-s06", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which summary describes the division of acid–base control?", "choices": ["Lungs control CO₂; kidneys control bicarbonate", "Kidneys control CO₂; lungs control bicarbonate", "The liver controls both", "Both are controlled only by buffers"], "correct": 0, "explanation": "\"Lungs control CO₂, kidneys control bicarbonate.\"", "srcItem": "The Kidney's Function in Acid–Base Balance"},
    {"id": "q-f202-s06-020", "topic": "f202-s06", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Where is most filtered bicarbonate reabsorbed?", "choices": ["Proximal tubule", "Distal tubule", "Loop of Henle", "Collecting duct"], "correct": 0, "explanation": "The proximal tubule is the primary site for HCO₃⁻ reabsorption (85–90% of filtered HCO₃⁻).", "srcItem": "The Kidney's Function in Acid–Base Balance"},
    {"id": "q-f202-s06-021", "topic": "f202-s06", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which nephron process 'clears waste' by moving H⁺, K⁺ and ammonium into the filtrate?", "choices": ["Tubular secretion", "Glomerular filtration", "Tubular reabsorption", "Micturition"], "correct": 0, "explanation": "Tubular secretion clears waste; the distal tubules secrete acids. Reabsorption \"reclaims plasma.\"", "srcItem": "The Kidney's Function in Acid–Base Balance"},
    {"id": "q-f202-s06-022", "topic": "f202-s06", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A patient's pH is 7.31. Which is a renal response?", "choices": ["Increased H⁺ secretion and HCO₃⁻ reabsorption", "Increased HCO₃⁻ excretion", "Decreased ammonium production", "Retention of H⁺ ions"], "correct": 0, "explanation": "Kidney: ↑ HCO₃⁻ reabsorption, ↑ H⁺ secretion, ammonium production and phosphate buffering.", "srcItem": "The Kidney's Function in Acid–Base Balance"},
    {"id": "q-f202-s06-023", "topic": "f202-s06", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How long does full renal compensation for a chronic PaCO₂ change take (RCP 103)?", "choices": ["3–5 days", "1–2 minutes", "1 hour", "12–24 hours"], "correct": 0, "explanation": "\"Renal compensation takes 3–5 days\"; the lungs produce rapid changes in pH.", "srcItem": "The Kidney's Function in Acid–Base Balance"},
    {"id": "q-f202-s06-024", "topic": "f202-s06", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Hypokalemia or hypochloremia forces the kidney to exchange Na⁺ for H⁺. What acid–base disturbance results?", "choices": ["Metabolic alkalosis", "Metabolic acidosis", "Respiratory acidosis", "Respiratory alkalosis"], "correct": 0, "explanation": "\"Lose H⁺ = Alkalosis; Lose HCO₃⁻ = Acidosis.\"", "srcItem": "The Kidney's Function in Acid–Base Balance"},
    {"id": "q-f202-s06-025", "topic": "f202-s06", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the normal adult GFR (Hess)?", "choices": ["About 120–125 mL/min", "About 12 mL/min", "About 1.2 L/min", "About 500 mL/min"], "correct": 0, "explanation": "Hess: approximately 120–125 mL/min; the deck gives ~90–120 mL/min/1.73 m² (average about 125).", "srcItem": "The Kidney's Function in Acid–Base Balance"},
    {"id": "q-f202-s06-026", "topic": "f202-s06", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which lab pattern fits kidney failure?", "choices": ["↓ urine output, ↑ BUN, ↑ creatinine, ↑ potassium", "↑ urine output, ↓ BUN, ↓ creatinine", "↓ potassium and ↓ BUN", "Normal BUN with ↑ urine output"], "correct": 0, "explanation": "\"Kidney Failure = Urine Output ↓; BUN ↑; Creatinine ↑; and Potassium ↑.\"", "srcItem": "Renal Failure and the Ventilated Patient"},
    {"id": "q-f202-s06-027", "topic": "f202-s06", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which electrolyte abnormality is the most immediately life-threatening in renal failure?", "choices": ["Hyperkalemia", "Hyponatremia", "Hypocalcemia", "Hypermagnesemia"], "correct": 0, "explanation": "Board pearl: hyperkalemia; decreased UOP retains K⁺.", "srcItem": "Renal Failure and the Ventilated Patient"},
    {"id": "q-f202-s06-028", "topic": "f202-s06", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In renal failure, where does excess retained fluid eventually end up, per the deck?", "choices": ["The lungs, causing crackles and pulmonary edema", "The brain only", "The stomach", "The bladder"], "correct": 0, "explanation": "Retention of fluid → pulmonary edema, crackles and hypoxemia; the patient may need CPAP, BiPAP or ventilation.", "srcItem": "Renal Failure and the Ventilated Patient"},
    {"id": "q-f202-s06-029", "topic": "f202-s06", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which is one of the 'Four R's' of renal failure?", "choices": ["Retention of drugs (toxicity)", "Rapid weight loss", "Reduced potassium", "Respiratory alkalosis"], "correct": 0, "explanation": "Retention of waste, fluid, potassium and drugs.", "srcItem": "Renal Failure and the Ventilated Patient"},
    {"id": "q-f202-s06-030", "topic": "f202-s06", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is azotemia?", "choices": ["Abnormally high nitrogen-containing wastes such as urea and creatinine in the blood", "Low blood oxygen from renal failure", "Excess bicarbonate in the urine", "Protein in the urine"], "correct": 0, "explanation": "Azotemia = abnormally high urea, creatinine and other nitrogen-rich wastes in the blood.", "srcItem": "Renal Failure and the Ventilated Patient"},
    {"id": "q-f202-s07-001", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which route of nutrition delivery is preferred?", "choices": ["Oral", "Enteral by feeding tube", "Parenteral through a central line", "Parenteral through a peripheral line"], "correct": 0, "explanation": "Hess: \"The preferred method of nutrient delivery is the oral route.\" Enteral is next whenever the GI tract works.", "srcItem": "The Three Routes"},
    {"id": "q-f202-s07-002", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What are the three routes of nutrition delivery named by Hess?", "choices": ["Oral, enteral, parenteral", "Oral, rectal, intravenous", "Enteral, intramuscular, inhaled", "Gastric, jejunal, rectal"], "correct": 0, "explanation": "Hess Ch 11's Respiratory Recap: oral, enteral, parenteral.", "srcItem": "The Three Routes"},
    {"id": "q-f202-s07-003", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does 'parenteral' mean in the pharmacology deck?", "choices": ["Beside the intestine — any route other than enteral, commonly injection", "Into the small intestine", "By mouth", "Through a feeding tube into the stomach"], "correct": 0, "explanation": "Parenteral = any route other than enteral; enteral refers to the GI tract (most commonly by mouth).", "srcItem": "The Three Routes"},
    {"id": "q-f202-s07-004", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which advice from Hess Box 11-1 helps a patient with chronic lung disease eat enough?", "choices": ["Eat small, frequent meals and drink liquids between meals", "Eat three large meals and drink with each meal", "Choose gas-forming foods such as beans", "Avoid all fats"], "correct": 0, "explanation": "Box 11-1: high-calorie dense foods, small frequent meals, liquids between meals, add fats, avoid gas-forming foods.", "srcItem": "The Three Routes"},
    {"id": "q-f202-s07-005", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which is the method of choice to feed patients requiring ventilatory support?", "choices": ["Enteral delivery by feeding tube", "Oral feeding around the ETT", "Peripheral parenteral nutrition", "IV dextrose only"], "correct": 0, "explanation": "Hess: enteral delivery should be the method of choice to feed patients requiring ventilatory support.", "srcItem": "The Three Routes"},
    {"id": "q-f202-s07-006", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How long are NG or OG feeding tubes generally used?", "choices": ["Short-term, less than 3–4 weeks", "Long-term, for years", "Only for 24 hours", "Only after a PEG fails"], "correct": 0, "explanation": "Nose/mouth tubes are short-term (< 3–4 weeks); percutaneous tubes are long-term.", "srcItem": "The Enteral Routes and How They Differ"},
    {"id": "q-f202-s07-007", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which tube is a small-bore, flexible NG feeding tube placed over a guidewire?", "choices": ["Dobhoff tube", "PEG tube", "Jejunostomy tube", "Salem sump tube"], "correct": 0, "explanation": "A Dobhoff is a small-bore (~4 mm ID) NG feeding tube with a weighted end, inserted over a stylet.", "srcItem": "The Enteral Routes and How They Differ"},
    {"id": "q-f202-s07-008", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A patient at high risk of aspiration with large gastric residuals needs tube feeding. Which tube is preferred?", "choices": ["Post-pyloric small-bowel tube past the ligament of Treitz", "Nasogastric tube into the stomach", "Orogastric tube into the stomach", "Oral feeding with thickened liquids"], "correct": 0, "explanation": "Post-pyloric feeding is chosen for high aspiration risk or poor gastric emptying; optimal placement is past the ligament of Treitz.", "srcItem": "The Enteral Routes and How They Differ"},
    {"id": "q-f202-s07-009", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which enteral access is suitable for long-term feeding in a patient with neurologic swallowing problems?", "choices": ["Percutaneous endoscopic gastrostomy (PEG)", "Nasogastric tube", "Orogastric tube", "Dobhoff tube"], "correct": 0, "explanation": "Percutaneous tubes (e.g. PEG) are long-term, more comfortable, and help avoid aspiration pneumonia.", "srcItem": "The Enteral Routes and How They Differ"},
    {"id": "q-f202-s07-010", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What must be done before using a newly placed NG feeding tube?", "choices": ["Confirm the position radiographically", "Inflate the cuff", "Flush it with 100 mL of air", "Start the feeding at full rate"], "correct": 0, "explanation": "An NG tube can be misplaced into the airway, so radiographic confirmation is essential before use.", "srcItem": "The Enteral Routes and How They Differ"},
    {"id": "q-f202-s07-011", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A colorimetric CO₂ detector is attached to a newly placed nasogastric tube and changes color. What does this mean?", "choices": ["The tube is incorrectly placed in the trachea", "The tube is correctly in the stomach", "The patient is hypercapnic", "The detector is expired"], "correct": 0, "explanation": "Here a color change means CO₂ was detected — the tube is in the trachea.", "srcItem": "The Enteral Routes and How They Differ"},
    {"id": "q-f202-s07-012", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "When is parenteral nutrition indicated?", "choices": ["When the GI tract is not functioning, e.g. severe pancreatitis or prolonged ileus", "Whenever a patient is on a ventilator", "For any patient who prefers not to eat", "When support is expected for less than 3 days"], "correct": 0, "explanation": "PN when the GI tract is not functioning or stimulation would worsen the condition; not if < 7 days expected.", "srcItem": "Parenteral Nutrition"},
    {"id": "q-f202-s07-013", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Parenteral nutrition should NOT be started if support is expected to last less than how long?", "choices": ["7 days", "24 hours", "3 months", "1 year"], "correct": 0, "explanation": "Hess: it should not be started if support is expected to last less than 7 days.", "srcItem": "Parenteral Nutrition"},
    {"id": "q-f202-s07-014", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which venous access is usually preferred for parenteral nutrition?", "choices": ["Central venous access", "Peripheral access in the hand", "Intraosseous access", "Arterial line"], "correct": 0, "explanation": "Hess: central or peripheral access is required; central venous access usually is preferred.", "srcItem": "Parenteral Nutrition"},
    {"id": "q-f202-s07-015", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What gut problem can result from bypassing the GI tract with TPN?", "choices": ["Gut atrophy and a weakened gut barrier", "Gut hypertrophy", "Increased secretory IgA", "Faster gastric emptying"], "correct": 0, "explanation": "An unstimulated gut can atrophy, compromising the mucosal barrier and raising infection risk.", "srcItem": "Parenteral Nutrition"},
    {"id": "q-f202-s07-016", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why is enteral nutrition preferred over parenteral nutrition (Hess Key Point)?", "choices": ["Fewer infection risks, possible GI mucosal protection, and lower cost", "It always provides more calories", "It requires no access device", "It prevents all aspiration"], "correct": 0, "explanation": "Hess Key Point: enteral is preferred — fewer infection risks, may protect the GI mucosa, and is less costly.", "srcItem": "Enteral vs Parenteral"},
    {"id": "q-f202-s07-017", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "When should early enteral nutrition be started in a critically ill patient who cannot eat?", "choices": ["Within 24–48 hours", "After 7 days", "Only after extubation", "Within 1 hour of admission"], "correct": 0, "explanation": "CPG 11-1: start early EN within 24–48 hours.", "srcItem": "Enteral vs Parenteral"},
    {"id": "q-f202-s07-018", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "When should enteral nutrition be withheld in the ICU?", "choices": ["During hemodynamic instability until the patient is resuscitated", "Whenever diarrhea occurs", "Before every test or procedure", "During mechanical ventilation"], "correct": 0, "explanation": "Withhold EN during hemodynamic compromise; do not automatically stop EN for diarrhea; minimize NPO orders.", "srcItem": "Enteral vs Parenteral"},
    {"id": "q-f202-s07-019", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What blood glucose range is targeted during nutrition support?", "choices": ["140–180 mg/dL", "80–100 mg/dL (tight control)", "200–250 mg/dL", "60–70 mg/dL"], "correct": 0, "explanation": "Keep 140–180 mg/dL and treat < 70 mg/dL as hypoglycemia; tight control is not supported.", "srcItem": "Enteral vs Parenteral"},
    {"id": "q-f202-s07-020", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What protein intake does CPG 11-1 recommend for critically ill adults?", "choices": ["1.2–2.0 g/kg actual body weight per day", "0.2–0.5 g/kg per day", "5–6 g/kg per day", "No protein in the first week"], "correct": 0, "explanation": "CPG 11-1: protein 1.2–2.0 g/kg/day; energy 25–30 kcal/kg/d if calorimetry is unavailable.", "srcItem": "Enteral vs Parenteral"},
    {"id": "q-f202-s07-021", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How high should the head of the bed be for intubated ICU patients receiving enteral nutrition?", "choices": ["30–45 degrees", "0 degrees (flat)", "10–15 degrees", "90 degrees"], "correct": 0, "explanation": "CPG 11-1 and the VAP bundle: elevate the head of the bed 30–45 degrees.", "srcItem": "Aspiration Precautions During Tube Feeding"},
    {"id": "q-f202-s07-022", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which is NOT recommended as a marker of aspiration in tube-fed patients?", "choices": ["Blue food coloring", "Clinical assessment of aspiration risk", "Switching to continuous infusion", "Considering prokinetic agents"], "correct": 0, "explanation": "Do not use blue food coloring (or any coloring) or glucose oxidase strips as markers of aspiration.", "srcItem": "Aspiration Precautions During Tube Feeding"},
    {"id": "q-f202-s07-023", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "For a tube-fed patient at high aspiration risk, which change helps?", "choices": ["Switch from bolus to continuous feeding", "Switch from continuous to bolus feeding", "Lower the head of the bed", "Stop all feeds permanently"], "correct": 0, "explanation": "Switch high-risk or intolerant patients from bolus to continuous infusion; consider post-pyloric feeding and prokinetics.", "srcItem": "Aspiration Precautions During Tube Feeding"},
    {"id": "q-f202-s07-024", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Before postural drainage, when should tube feedings be stopped?", "choices": ["1 hour before and during therapy", "5 minutes before", "Only after therapy", "They do not need to be stopped"], "correct": 0, "explanation": "Hess Ch 16: tube feedings should cease 1 hour before and during postural drainage.", "srcItem": "Aspiration Precautions During Tube Feeding"},
    {"id": "q-f202-s07-025", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which prokinetic agents may be considered when aspiration risk is high?", "choices": ["Metoclopramide or erythromycin", "Albuterol or ipratropium", "Furosemide or mannitol", "Midazolam or propofol"], "correct": 0, "explanation": "CPG 11-1: consider metoclopramide or erythromycin when aspiration risk is high.", "srcItem": "Aspiration Precautions During Tube Feeding"},
    {"id": "q-f202-s07-026", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why can overfeeding carbohydrates prolong mechanical ventilation?", "choices": ["Lipogenesis increases CO₂ production and ventilatory demand", "It lowers the RQ", "It reduces CO₂ production", "It causes hypoglycemia"], "correct": 0, "explanation": "Carbohydrate overfeeding → lipogenesis → excessive CO₂ → higher ventilatory needs → hypercapnia and prolonged ventilation.", "srcItem": "Overfeeding, CO₂ Production and the Respiratory Quotient"},
    {"id": "q-f202-s07-027", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How is the respiratory quotient calculated?", "choices": ["VCO₂ ÷ VO₂", "VO₂ ÷ VCO₂", "VT ÷ VD", "PaO₂ ÷ FiO₂"], "correct": 0, "explanation": "RQ = CO₂ produced ÷ O₂ consumed; critically ill patients run about 0.90.", "srcItem": "Overfeeding, CO₂ Production and the Respiratory Quotient"},
    {"id": "q-f202-s07-028", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which substrate has an RQ of about 1.0 and produces the most CO₂?", "choices": ["Carbohydrate", "Fat", "Protein", "Alcohol"], "correct": 0, "explanation": "Carbohydrate ≈ 1.0, protein ≈ 0.8, fat ≈ 0.7: higher RQ = more CO₂ produced.", "srcItem": "Overfeeding, CO₂ Production and the Respiratory Quotient"},
    {"id": "q-f202-s07-029", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which substrate has the lowest RQ, about 0.7?", "choices": ["Fat", "Carbohydrate", "Protein", "Mixed diet"], "correct": 0, "explanation": "Fat ≈ 0.7 (Hess 0.71), which is why the decks favor fat-based nutrition for CO₂ retainers.", "srcItem": "Overfeeding, CO₂ Production and the Respiratory Quotient"},
    {"id": "q-f202-s07-030", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does the current ICU guideline (CPG 11-1) say about high-fat/low-carbohydrate formulas in acute respiratory failure?", "choices": ["They should NOT be used; use fluid-restricted, energy-dense formulas instead", "They should always be used", "They should replace all enteral feeding", "They should be given only intravenously"], "correct": 0, "explanation": "CPG 11-1 suggests not using RQ-manipulating formulas in acute respiratory failure; the decks favor fat-based nutrition.", "srcItem": "Overfeeding, CO₂ Production and the Respiratory Quotient"},
    {"id": "q-f202-s07-031", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does malnutrition affect the respiratory muscles?", "choices": ["The diaphragm is used as fuel, so MIP, MEP and VC decline", "It strengthens fast-twitch fibers", "It increases surfactant production", "It has no effect on ventilation"], "correct": 0, "explanation": "In semistarvation the respiratory muscles are used as fuel; MIP, MEP, VC and voluntary ventilation decline.", "srcItem": "Undernutrition, Refeeding Syndrome and Phosphate"},
    {"id": "q-f202-s07-032", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is refeeding syndrome?", "choices": ["Metabolic and clinical disturbances after restarting nutrition in a starved patient", "Vomiting after a large meal", "Aspiration of tube feeds", "Overfeeding with fat emulsions"], "correct": 0, "explanation": "Refeeding syndrome: electrolyte imbalance, vitamin deficiency and hyperglycemia, which can prolong ventilation.", "srcItem": "Undernutrition, Refeeding Syndrome and Phosphate"},
    {"id": "q-f202-s07-033", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which electrolyte deficiency decreases ATP and causes muscle weakness and respiratory failure, and is common in sepsis and trauma?", "choices": ["Hypophosphatemia", "Hypernatremia", "Hyperkalemia", "Hypercalcemia"], "correct": 0, "explanation": "Hypophosphatemia occurs in 30% of ICU patients, 65–80% of sepsis and 75% of major trauma; it decreases ATP.", "srcItem": "Undernutrition, Refeeding Syndrome and Phosphate"},
    {"id": "q-f202-s07-034", "topic": "f202-s07", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "By how much can caloric needs rise during the hypercatabolic phase of critical illness?", "choices": ["As much as 100%", "About 5%", "About 10%", "They fall by half"], "correct": 0, "explanation": "The hypercatabolic phase can last 7–10 days, and caloric needs may rise by as much as 100%.", "srcItem": "Undernutrition, Refeeding Syndrome and Phosphate"},
    {"id": "q-f202-s08-001", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Under what arterial oxygenation should all pulmonary rehab exercise training be performed (Hess)?", "choices": ["PaO₂ > 55 mm Hg and SpO₂ > 88%", "PaO₂ > 80 mm Hg and SpO₂ > 95%", "PaO₂ > 40 mm Hg and SpO₂ > 75%", "PaO₂ > 100 mm Hg and SpO₂ 100%"], "correct": 0, "explanation": "Hess Ch 24: exercise under adequate oxygenation, PaO₂ > 55 mm Hg and SpO₂ > 88%.", "srcItem": "Adequate Arterial Oxygenation Limits"},
    {"id": "q-f202-s08-002", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "During rehab exercise, a patient's SpO₂ drops below 88% despite supplemental O₂. What should be done?", "choices": ["Reduce the intensity or stop until oxygenation recovers", "Continue at the same intensity", "Remove the oxygen", "Increase the intensity to build tolerance"], "correct": 0, "explanation": "When adequate oxygenation cannot be maintained, reduce intensity or stop until oxygenation returns.", "srcItem": "Adequate Arterial Oxygenation Limits"},
    {"id": "q-f202-s08-003", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "During an exercise O₂ titration, the SpO₂ falls to 85%. What is the next step per RCP 203?", "choices": ["Increase O₂ by 1 L/min until SpO₂ ≥ 88%", "Stop the test and send the patient home", "Decrease O₂ by 1 L/min", "Switch to a non-rebreather at 15 L/min"], "correct": 0, "explanation": "SpO₂ < 88% (PaO₂ < 55) or a drop ≥ 2% → ↑ O₂ by 1 L/min until SpO₂ ≥ 88%.", "srcItem": "Adequate Arterial Oxygenation Limits"},
    {"id": "q-f202-s08-004", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Is exercise hypoxemia a reason to exclude a patient from pulmonary rehab?", "choices": ["No — supplemental O₂ and monitoring let the patient participate", "Yes — it is an absolute exclusion", "Yes — unless the patient is under 40", "Only if the patient smokes"], "correct": 0, "explanation": "Hess: exercise hypoxemia is not a reason to exclude; O₂ and pulse oximetry allow full participation.", "srcItem": "Adequate Arterial Oxygenation Limits"},
    {"id": "q-f202-s08-005", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What happens to the abdomen during inhalation with diaphragmatic breathing?", "choices": ["It moves outward as the diaphragm contracts downward", "It pulls inward", "It stays completely still while the chest rises", "It moves outward only on exhalation"], "correct": 0, "explanation": "Belly breathing: the diaphragm moves down, the abdomen expands on inhalation, with minimal chest/shoulder movement.", "srcItem": "Diaphragmatic Breathing"},
    {"id": "q-f202-s08-006", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which nervous system does diaphragmatic breathing activate?", "choices": ["Parasympathetic (rest and digest)", "Sympathetic (fight or flight)", "Somatic motor only", "None"], "correct": 0, "explanation": "Diaphragmatic breathing activates the parasympathetic system, lowering heart rate and blood pressure.", "srcItem": "Diaphragmatic Breathing"},
    {"id": "q-f202-s08-007", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "When teaching diaphragmatic breathing, where does the therapist place a hand?", "choices": ["On the upper abdomen just below the xiphoid", "On the patient's forehead", "On the upper chest over the sternum", "On the patient's back"], "correct": 0, "explanation": "Semi-Fowler's position, knees bent; hand on the upper abdomen below the xiphoid; patient pushes out against it.", "srcItem": "Diaphragmatic Breathing"},
    {"id": "q-f202-s08-008", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What are the two parts of breathing retraining in pulmonary rehab?", "choices": ["Pursed-lip breathing and diaphragmatic breathing", "Huff coughing and postural drainage", "Incentive spirometry and IPPB", "Thoracic breathing and breath holding"], "correct": 0, "explanation": "Deck and Hess glossary: breathing retraining = pursed-lip breathing and diaphragmatic breathing.", "srcItem": "Diaphragmatic Breathing"},
    {"id": "q-f202-s08-009", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What timing does the Pulm Rehab deck teach for pursed-lip breathing?", "choices": ["Inhale through the nose about 2 s, exhale through pursed lips about 4 s", "Inhale 4 s, exhale 2 s", "Inhale and exhale for equal times", "Inhale through pursed lips, exhale through the nose"], "correct": 0, "explanation": "\"Smell the roses\" for about 2 s, then exhale slowly for about 4 s — twice as long as inhalation.", "srcItem": "Pursed-Lip Breathing"},
    {"id": "q-f202-s08-010", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does pursed-lip breathing help a patient with COPD?", "choices": ["Back-pressure keeps small airways open, reducing air trapping", "It increases airway resistance during inspiration", "It strengthens the diaphragm directly", "It shortens exhalation"], "correct": 0, "explanation": "Gentle back-pressure prevents premature small-airway collapse, reducing air trapping, dyspnea and WOB.", "srcItem": "Pursed-Lip Breathing"},
    {"id": "q-f202-s08-011", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which patient type classically adopts pursed-lip breathing on their own?", "choices": ["Emphysema ('Pink Puffer')", "Asthma during remission", "Pulmonary fibrosis", "Neuromuscular weakness"], "correct": 0, "explanation": "Emphysema patients adopt PLB to compensate for airway collapse during exhalation.", "srcItem": "Pursed-Lip Breathing"},
    {"id": "q-f202-s08-012", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which muscles primarily drive thoracic (chest) breathing?", "choices": ["The intercostal muscles", "The diaphragm", "The abdominal muscles", "The pharyngeal muscles"], "correct": 0, "explanation": "Chest breathing uses mainly the intercostals; the chest and shoulders rise and the diaphragm is less active.", "srcItem": "Thoracic Breathing"},
    {"id": "q-f202-s08-013", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which statement describes thoracic breathing compared with diaphragmatic breathing?", "choices": ["Shallower, less efficient and associated with stress", "Deeper and more efficient", "Activates the parasympathetic system", "Fills the lower lungs best"], "correct": 0, "explanation": "Deck: thoracic breathing is \"shallow, less efficient, and associated with stress and the use of chest muscles.\"", "srcItem": "Thoracic Breathing"},
    {"id": "q-f202-s08-014", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A patient recovering from abdominal surgery needs an inspiratory breathing exercise. Which is a good alternative to diaphragmatic breathing?", "choices": ["Lateral costal breathing", "Thoracic chest breathing", "Breath stacking with a mask", "Glossopharyngeal breathing"], "correct": 0, "explanation": "Lateral costal breathing (hands cupping the lower ribs) is a good alternative, especially after abdominal surgery.", "srcItem": "Thoracic Breathing"},
    {"id": "q-f202-s08-015", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which is an accessory muscle of inspiration?", "choices": ["Sternocleidomastoid", "Internal intercostal", "Rectus abdominis", "Transversus abdominis"], "correct": 0, "explanation": "Accessory inspiratory muscles: scalene, sternocleidomastoid, pectoralis major, trapezius, external intercostals.", "srcItem": "Thoracic Breathing"},
    {"id": "q-f202-s08-016", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What defines hyperventilation?", "choices": ["A PaCO₂ below 35 mm Hg from excess CO₂ removal", "A respiratory rate above 20/min", "Deep breathing of any kind", "A PaO₂ above 100 mm Hg"], "correct": 0, "explanation": "Hyper- and hypoventilation are defined by PaCO₂, not by how the breathing looks.", "srcItem": "Hyperventilation vs Hypoventilation"},
    {"id": "q-f202-s08-017", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the most common cause of hyperventilation?", "choices": ["Hypoxemia", "Narcotic overdose", "Neuromuscular weakness", "Severe COPD exacerbation with fatigue"], "correct": 0, "explanation": "When PaO₂ drops to around 60 mm Hg, peripheral chemoreceptors drive ventilation up.", "srcItem": "Hyperventilation vs Hypoventilation"},
    {"id": "q-f202-s08-018", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A patient breathes 34/min with shallow breaths. ABG: pH 7.28, PaCO₂ 58. What is happening?", "choices": ["Hypoventilation (acute respiratory acidosis) despite the fast rate", "Hyperventilation, because the rate is high", "Normal ventilation", "Metabolic alkalosis"], "correct": 0, "explanation": "Judge by PaCO₂, not rate: PaCO₂ > 45 with pH < 7.35 = acute ventilatory failure; rapid shallow breathing can hypoventilate.", "srcItem": "Hyperventilation vs Hypoventilation"},
    {"id": "q-f202-s08-019", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which ABG matches acute alveolar hyperventilation?", "choices": ["PaCO₂ 30 mm Hg, pH 7.50", "PaCO₂ 50 mm Hg, pH 7.30", "PaCO₂ 40 mm Hg, pH 7.40", "PaCO₂ 60 mm Hg, pH 7.40"], "correct": 0, "explanation": "Acute alveolar hyperventilation: PaCO₂ < 35 with pH > 7.45 → acute respiratory alkalosis.", "srcItem": "Hyperventilation vs Hypoventilation"},
    {"id": "q-f202-s08-020", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which is a cause of hypoventilation?", "choices": ["CNS depression from narcotics or sedatives", "Anxiety", "Pain", "Early hypoxemia"], "correct": 0, "explanation": "Hypoventilation causes include narcotic/sedative CNS depression, severe asthma/COPD, neuromuscular weakness, airway obstruction.", "srcItem": "Hyperventilation vs Hypoventilation"},
    {"id": "q-f202-s08-021", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which breathing pattern is linked with respiratory alkalosis?", "choices": ["Hyperventilation", "Hypoventilation", "Pursed-lip breathing", "Diaphragmatic breathing"], "correct": 0, "explanation": "Hyperventilation: PaCO₂ < 35 → ↑ pH → respiratory alkalosis; hypoventilation → respiratory acidosis.", "srcItem": "The Five Side by Side"},
    {"id": "q-f202-s08-022", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which pattern is a taught technique that acts mainly on EXPIRATION?", "choices": ["Pursed-lip breathing", "Diaphragmatic breathing", "Thoracic breathing", "Lateral costal breathing"], "correct": 0, "explanation": "Pursed-lip breathing works on expiration; diaphragmatic and lateral costal breathing are inspiratory exercises.", "srcItem": "The Five Side by Side"},
    {"id": "q-f202-s08-023", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does pulmonary rehab generally NOT significantly improve?", "choices": ["Pulmonary function tests such as FEV₁", "Walking distance", "Ability to perform daily activities", "Dyspnea during exercise"], "correct": 0, "explanation": "Rehab does not significantly improve PFTs; the patient may keep the same FEV₁ but walk farther.", "srcItem": "Exercise Prescription"},
    {"id": "q-f202-s08-024", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What minimum endurance exercise does Hess recommend in rehab?", "choices": ["At least 20 minutes, 3 times per week", "5 minutes once a week", "2 hours daily", "10 minutes once a month"], "correct": 0, "explanation": "Hess: no less than 20 minutes, 3 times per week.", "srcItem": "Exercise Prescription"},
    {"id": "q-f202-s08-025", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What Modified Borg effort level indicates an adequate exercise prescription?", "choices": ["4–6", "0–1", "9–10", "1–2"], "correct": 0, "explanation": "Borg 0 = nothing, 10 = maximal; a Borg effort of 4–6 means the prescription is adequate.", "srcItem": "Exercise Prescription"},
    {"id": "q-f202-s08-026", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which test is the method of choice to assess exercise capacity before and after rehab?", "choices": ["Six-minute walk test", "Spirometry", "Chest radiograph", "Arterial blood gas at rest"], "correct": 0, "explanation": "Walk tests, especially the 6MWT, are the method of choice; benefits are task-specific, so walking is emphasized.", "srcItem": "Exercise Prescription"},
    {"id": "q-f202-s08-027", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What are the three types of exercise in a balanced rehab program?", "choices": ["Stretching/flexibility, strengthening and endurance", "Sprinting, jumping and swimming", "Breath holding, coughing and huffing", "Weightlifting only"], "correct": 0, "explanation": "Exercise training balances stretching and flexibility, strengthening, and endurance.", "srcItem": "Exercise Prescription"},
    {"id": "q-f202-s08-028", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "For COPD with severe resting hypoxemia, how many hours per day of oxygen improve survival at minimum?", "choices": ["At least 15 hours", "At least 4 hours", "Only at night", "Only during exercise"], "correct": 0, "explanation": "LTOT improves survival when used at least 15 h/day; about 19 h/day gives the full benefit (\"19 to stay alive\").", "srcItem": "Home oxygen"},
    {"id": "q-f202-s08-029", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "For a COPD patient at risk of hypercapnia, what SpO₂ range is O₂ often titrated to?", "choices": ["88–92%", "95–100%", "80–84%", "70–75%"], "correct": 0, "explanation": "For COPD at risk of hypercapnia, O₂ is often titrated to SpO₂ 88–92%, as prescribed.", "srcItem": "Home oxygen"},
    {"id": "q-f202-s08-030", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does an oxygen concentrator produce oxygen?", "choices": ["Pressure swing adsorption with zeolite sieve beds that remove nitrogen", "Fractional distillation of liquid air", "Electrolysis of water", "Chemical oxygen generators"], "correct": 0, "explanation": "Concentrators separate nitrogen from room air with zeolite sieve beds, giving about 93% ± 3% O₂.", "srcItem": "Home oxygen"},
    {"id": "q-f202-s08-031", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which home O₂ system has the greatest storage capacity?", "choices": ["Liquid oxygen", "An E cylinder", "An oxygen concentrator", "A reservoir cannula"], "correct": 0, "explanation": "Liquid O₂: 1 L of liquid expands to 860 L of gas.", "srcItem": "Home oxygen"},
    {"id": "q-f202-s08-032", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "An ILD patient on 5 L/min drops from 92% to 80% while walking. What does the patient need?", "choices": ["A higher-flow continuous system, titrated during a supervised walk", "A pulse-dose concentrator at setting 2", "No change, since 80% is acceptable", "A lower flow to avoid CO₂ retention"], "correct": 0, "explanation": "A higher-flow continuous system (e.g. portable liquid O₂) titrated to about 90%; a pulse-dose unit may not keep up.", "srcItem": "Home oxygen"},
    {"id": "q-f202-s08-033", "topic": "f202-s08", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why should oxygenation be reassessed when switching to a pulse-dose device?", "choices": ["A pulse-dose setting of 2 is not the same as 2 L/min continuous", "Pulse-dose always delivers more O₂", "Pulse-dose devices need no assessment", "The FiO₂ is fixed at 21%"], "correct": 0, "explanation": "Conserving devices deliver O₂ mainly in inspiration; a setting of 2 ≠ 2 L/min continuous.", "srcItem": "Home oxygen"},
    {"id": "q-f202-s09-001", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is a pneumothorax?", "choices": ["Air in the pleural space that can cause the lung to collapse", "Blood in the pleural space", "Fluid in the alveoli", "Air in the mediastinum only"], "correct": 0, "explanation": "Trauma deck: the presence of air in the pleural space, which can cause the lung to collapse.", "srcItem": "Pneumothorax: what it is and how it is diagnosed"},
    {"id": "q-f202-s09-002", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which set of findings fits a large pneumothorax?", "choices": ["Hyperresonance, absent breath sounds, trachea shifted away from the affected side", "Dullness, bronchial breath sounds, trachea shifted toward the affected side", "Normal percussion with crackles", "Dullness with increased fremitus"], "correct": 0, "explanation": "Pneumothorax: hyperresonant, absent breath sounds, decreased fremitus, trachea away (a late, unreliable sign).", "srcItem": "Pneumothorax: what it is and how it is diagnosed"},
    {"id": "q-f202-s09-003", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why should the team NOT wait for tracheal deviation before treating a suspected tension pneumothorax?", "choices": ["Tracheal deviation is a late, unreliable finding", "Tracheal deviation happens only in simple pneumothorax", "It always appears first", "It is the only reliable sign"], "correct": 0, "explanation": "Recognize respiratory distress, unilateral diminished breath sounds and hemodynamic instability instead.", "srcItem": "Pneumothorax: what it is and how it is diagnosed"},
    {"id": "q-f202-s09-004", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "On the ventilator, how does a pneumothorax change the pressures?", "choices": ["Both PIP and plateau pressure rise", "Only PIP rises", "Both pressures fall", "Only PEEP rises"], "correct": 0, "explanation": "A pneumothorax is a compliance problem, so PIP and Pplat both rise.", "srcItem": "Pneumothorax: what it is and how it is diagnosed"},
    {"id": "q-f202-s09-005", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which imaging is more sensitive than a chest radiograph for pneumothorax, per Hess?", "choices": ["Ultrasound", "Plain lateral film", "Fluoroscopy", "Ventilation-perfusion scan"], "correct": 0, "explanation": "Hess: ultrasound is more sensitive (absent lung sliding and B lines); plain films are notorious for missing pneumothoraces.", "srcItem": "Pneumothorax: what it is and how it is diagnosed"},
    {"id": "q-f202-s09-006", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the immediate treatment for an open ('sucking') chest wound?", "choices": ["A sterile occlusive dressing, often taped on three sides", "Needle decompression at the 2nd ICS", "Leave it open to air", "Intubate before covering it"], "correct": 0, "explanation": "Immediately apply a sterile occlusive dressing (often three-sided); definitive care is a chest tube and surgical closure.", "srcItem": "Pneumothorax: treatment, by subtype"},
    {"id": "q-f202-s09-007", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why is a tension pneumothorax the most lethal type?", "choices": ["Trapped air builds pressure, reducing venous return and cardiac output", "Air leaks out with each breath", "It affects only the chest wall", "It always resolves on its own"], "correct": 0, "explanation": "One-way valve → pressure builds → ↓ venous return → ↓ CO → obstructive shock, possible arrest.", "srcItem": "Pneumothorax: treatment, by subtype"},
    {"id": "q-f202-s09-008", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A trauma patient has severe dyspnea, hypotension and absent breath sounds on one side. What is the first action?", "choices": ["Immediate needle decompression without waiting for a CXR", "Obtain a chest radiograph first", "Start positive pressure ventilation", "Observe and give oxygen"], "correct": 0, "explanation": "Tension pneumothorax with instability is a clinical diagnosis — decompress immediately, then place a chest tube.", "srcItem": "Pneumothorax: treatment, by subtype"},
    {"id": "q-f202-s09-009", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which is the traditional needle-decompression site?", "choices": ["2nd ICS, midclavicular line", "8th ICS, posterior axillary line", "5th ICS, midclavicular line", "1st ICS, sternal border"], "correct": 0, "explanation": "Traditional: 2nd ICS midclavicular; 4th–5th ICS anterior to the midaxillary line is often preferred in adult trauma.", "srcItem": "Pneumothorax: treatment, by subtype"},
    {"id": "q-f202-s09-010", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the only absolute contraindication to positive-pressure ventilation per the RCP 105 Initiation deck?", "choices": ["Untreated tension pneumothorax", "Severe ARDS", "COPD exacerbation", "Status asthmaticus"], "correct": 0, "explanation": "Untreated tension pneumothorax: ↑ intrathoracic pressure → ↓ venous return → severe hypotension → arrest.", "srcItem": "Pneumothorax: treatment, by subtype"},
    {"id": "q-f202-s09-011", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What treatment is used for a recurrent or persistent pneumothorax?", "choices": ["Surgery such as VATS or pleurodesis", "Observation only", "Repeated needle aspiration indefinitely", "Higher PEEP"], "correct": 0, "explanation": "Trauma deck ladder: recurrent or persistent → surgery (VATS or pleurodesis with talc, tetracycline or bleomycin).", "srcItem": "Pneumothorax: treatment, by subtype"},
    {"id": "q-f202-s09-012", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A patient opens eyes to voice, is confused, and localizes pain. What is the GCS?", "choices": ["12", "10", "14", "9"], "correct": 0, "explanation": "E3 (to voice) + V4 (confused) + M5 (localizes) = 12, moderate.", "srcItem": "Glasgow Coma Scale (GCS)"},
    {"id": "q-f202-s09-013", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why is a patient with a GCS ≤ 8 intubated?", "choices": ["To protect the airway, since they may not handle secretions or aspiration", "Because they always stop breathing", "To lower the ICP directly", "Because sedation is required"], "correct": 0, "explanation": "The ≤ 8 patient is intubated not necessarily because they can't breathe, but because they can't protect the airway.", "srcItem": "Glasgow Coma Scale (GCS)"},
    {"id": "q-f202-s09-014", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In which step of the primary survey is the GCS used?", "choices": ["D — Disability", "A — Airway", "B — Breathing", "E — Exposure"], "correct": 0, "explanation": "The Trauma deck uses the GCS, pupils and lateralizing signs in the D = Disability step.", "srcItem": "Glasgow Coma Scale (GCS)"},
    {"id": "q-f202-s09-015", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "BP is 110/70 mm Hg. What is the MAP?", "choices": ["About 83 mm Hg", "About 90 mm Hg", "About 70 mm Hg", "About 110 mm Hg"], "correct": 0, "explanation": "MAP = DBP + ⅓(SBP − DBP) = 70 + 13.3 ≈ 83 mm Hg.", "srcItem": "Difference between Mean Arterial Pressure"},
    {"id": "q-f202-s09-016", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does the Monro-Kellie doctrine state?", "choices": ["The total volume of brain, CSF and blood in the rigid skull must stay constant", "CPP equals MAP plus ICP", "Autoregulation fails at any MAP below 100", "The brain can expand freely after injury"], "correct": 0, "explanation": "If blood is added after injury, CSF and venous blood must leave or ICP rises.", "srcItem": "Difference between Mean Arterial Pressure"},
    {"id": "q-f202-s09-017", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "For a trauma question, what CPP goal should be maintained?", "choices": ["> 60 mm Hg", "> 120 mm Hg", "> 30 mm Hg", "Exactly 40 mm Hg"], "correct": 0, "explanation": "Trauma deck: CPP > 60 mm Hg by lowering ICP, raising MAP, or both (Hess agrees).", "srcItem": "Difference between Mean Arterial Pressure"},
    {"id": "q-f202-s09-018", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Above what ICP do all the decks agree treatment is needed?", "choices": ["> 20 mm Hg", "> 5 mm Hg", "> 60 mm Hg", "> 100 mm Hg"], "correct": 0, "explanation": "Every deck with a number agrees ICP > 20 mm Hg is abnormal and needs treatment.", "srcItem": "Difference between Mean Arterial Pressure"},
    {"id": "q-f202-s09-019", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which procedure can raise ICP?", "choices": ["Suctioning", "Elevating the head of the bed", "Draining CSF", "Hyperventilation"], "correct": 0, "explanation": "Raise ICP: Trendelenburg, neck flexion, intubation, suctioning/coughing, asynchrony, high PEEP. Head elevation lowers it.", "srcItem": "Difference between Mean Arterial Pressure"},
    {"id": "q-f202-s09-020", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the Cushing response to raised ICP?", "choices": ["Hypertension with bradycardia", "Hypotension with tachycardia", "Hypertension with tachycardia", "Hypotension with bradycardia"], "correct": 0, "explanation": "Hess Ch 53: the Cushing response is hypertension with bradycardia.", "srcItem": "Difference between Mean Arterial Pressure"},
    {"id": "q-f202-s09-021", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is a key difference between CT and MRI?", "choices": ["CT uses ionizing radiation; MRI uses no radiation", "MRI uses ionizing radiation; CT does not", "Both use radiation", "Neither can image soft tissue"], "correct": 0, "explanation": "Hess: \"MRI, unlike CT, uses no ionizing radiation.\"", "srcItem": "Difference between MRI and CT scans"},
    {"id": "q-f202-s09-022", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which oxygen cylinders may be used in the MRI suite?", "choices": ["Aluminum cylinders only", "Steel cylinders only", "Any cylinder if secured", "No oxygen is allowed"], "correct": 0, "explanation": "Only aluminum O₂ cylinders and MRI-compatible equipment; steel cylinders become projectiles.", "srcItem": "Difference between MRI and CT scans"},
    {"id": "q-f202-s09-023", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "For a hemodynamically stable patient with a chest injury, which imaging is the best modality per the Trauma deck?", "choices": ["Chest CT", "MRI of the chest", "Plain lateral radiograph", "Ultrasound only"], "correct": 0, "explanation": "Chest CT finds injuries a CXR misses; unstable patients should not have treatment delayed for CT.", "srcItem": "Difference between MRI and CT scans"},
    {"id": "q-f202-s09-024", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which injury is hard to see on head CT and may require MRI?", "choices": ["Diffuse axonal injury", "Epidural hematoma", "Skull fracture", "Acute hemorrhagic stroke"], "correct": 0, "explanation": "Diffuse axonal injury is hard to see on CT and may require MRI.", "srcItem": "Difference between MRI and CT scans"},
    {"id": "q-f202-s09-025", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which statement fits the 'Air = small tube, Blood/Pus = large tube' rule?", "choices": ["An adult pneumothorax may need 16–20 Fr; blood needs about 36 Fr", "Blood needs 12 Fr; air needs 40 Fr", "All chest tubes are 28 Fr", "Neonates need 36–40 Fr"], "correct": 0, "explanation": "Air: 16–20 Fr may suffice; blood/thick fluid: 36 Fr (28–40) to reduce clotting.", "srcItem": "Chest tubes, part 1"},
    {"id": "q-f202-s09-026", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Where are most chest tubes placed today?", "choices": ["The 'safe triangle': 4th–5th ICS at the anterior-to-mid-axillary line", "2nd ICS midclavicular line", "8th ICS posterior line", "Just below the clavicle"], "correct": 0, "explanation": "The safe triangle; the 2nd ICS is now mainly a needle-decompression landmark.", "srcItem": "Chest tubes, part 1"},
    {"id": "q-f202-s09-027", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why is a chest tube inserted over the TOP of the rib?", "choices": ["The intercostal vein, artery and nerve run along the inferior border", "The top of the rib has no pleura", "It makes the tube point upward", "The lower border is thicker"], "correct": 0, "explanation": "The neurovascular bundle runs in the costal groove along the inferior rib border.", "srcItem": "Chest tubes, part 1"},
    {"id": "q-f202-s09-028", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which direction should a chest tube be aimed to drain air?", "choices": ["Up toward the apex", "Down and posterior", "Straight across to the mediastinum", "Toward the diaphragm"], "correct": 0, "explanation": "Air rises → aim toward the apex; fluid falls → aim down and posterior.", "srcItem": "Chest tubes, part 1"},
    {"id": "q-f202-s09-029", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does the water-seal chamber of a chest drainage system do?", "choices": ["Acts as a one-way valve so air leaves but cannot return", "Sets the level of suction", "Collects and measures blood", "Humidifies the pleural space"], "correct": 0, "explanation": "The ~2 cm H₂O water seal is the one-way valve; the suction-control chamber's water depth sets suction.", "srcItem": "Chest tubes, part 2"},
    {"id": "q-f202-s09-030", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "The suction-control chamber is filled to 20 cm of water and bubbles vigorously. What does the vigorous bubbling mean?", "choices": ["The wall suction is too high, causing noise and evaporation — not more suction", "The suction is now −40 cm H₂O", "There is a large air leak from the patient", "The tube is blocked"], "correct": 0, "explanation": "\"Wall suction controls the bubbling. Water depth controls the suction.\"", "srcItem": "Chest tubes, part 2"},
    {"id": "q-f202-s09-031", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "The water-seal level suddenly stops tidaling. What is the likely cause?", "choices": ["A blocked or kinked tube", "A normal finding of a large leak", "Too much suction in the collection chamber", "The patient is breathing deeply"], "correct": 0, "explanation": "Unexpected loss of tidaling → check for kinks or dependent loops, milk the tubing, then assess for pneumothorax.", "srcItem": "Chest tubes, part 2"},
    {"id": "q-f202-s09-032", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Continuous bubbling appears in the water seal. Clamping near the chest wall stops it. Where is the leak?", "choices": ["From the patient, within the thorax", "In the drainage unit", "In the wall suction", "In the collection chamber"], "correct": 0, "explanation": "If bubbling stops when clamped near the chest, the leak is from the patient: CXR as ordered and notify the physician.", "srcItem": "Chest tubes, part 2"},
    {"id": "q-f202-s09-033", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A chest tube is accidentally pulled out of the patient. What should be done?", "choices": ["Cover the site with an occlusive dressing and call the physician", "Push the tube back in", "Clamp the tube and leave it on the bed", "Ignore it if the patient is stable"], "correct": 0, "explanation": "Cover with an occlusive (Vaseline) dressing, apply pressure, call the physician; never push a tube back in.", "srcItem": "Chest tubes, part 2"},
    {"id": "q-f202-s09-034", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which findings indicate a chest tube is usually ready for removal?", "choices": ["Drainage < 100 mL in 24 h, pneumothorax resolved, no air leak", "Drainage > 500 mL in 24 h", "Continuous bubbling in the water seal", "Tidaling has just stopped from a kink"], "correct": 0, "explanation": "Removal criteria: < 100 mL/24 h, resolved pneumothorax on CXR, no air leak.", "srcItem": "Chest tubes, part 2"},
    {"id": "q-f202-s09-035", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "During routine transport, how should a chest drainage unit be handled?", "choices": ["Keep it upright below chest level and do not clamp the tube", "Clamp the tube for the whole trip", "Lift it above the chest", "Disconnect it and reconnect on arrival"], "correct": 0, "explanation": "Never clamp during routine transport; keep the unit below chest level and upright, with the water seal intact.", "srcItem": "Chest tubes, part 2"},
    {"id": "q-f202-s09-036", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does blunt trauma differ from penetrating trauma?", "choices": ["Blunt injures internal structures without necessarily breaking the skin; penetrating enters the chest", "Blunt always breaks the skin", "Penetrating never damages the heart", "They cause entirely different injuries"], "correct": 0, "explanation": "Blunt: external force, skin may be intact (e.g. MVC contusions). Penetrating: an object enters the chest.", "srcItem": "Difference between Blunt Force Trauma and Penetrating Trauma"},
    {"id": "q-f202-s09-037", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the dominant cause of blunt chest injury?", "choices": ["Motor vehicle crashes", "Stab wounds", "Gunshot wounds", "Burns"], "correct": 0, "explanation": "Motor vehicle crashes dominate blunt chest injury; stab and gunshot wounds are penetrating.", "srcItem": "Difference between Blunt Force Trauma and Penetrating Trauma"},
    {"id": "q-f202-s09-038", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Where is aortic injury from rapid deceleration most common?", "choices": ["At the aortic isthmus, just distal to the left subclavian artery", "At the aortic root", "At the abdominal aortic bifurcation", "At the right subclavian artery"], "correct": 0, "explanation": "Blunt deceleration aortic injury commonly occurs at the isthmus, just distal to the left subclavian artery.", "srcItem": "Difference between Blunt Force Trauma and Penetrating Trauma"},
    {"id": "q-f202-s09-039", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which injury is most commonly from penetrating trauma?", "choices": ["Cardiac tamponade", "Pulmonary contusion from an MVC", "Rib fractures from a fall", "Flail chest"], "correct": 0, "explanation": "Cardiac tamponade, esophageal injury and massive hemothorax are most commonly penetrating.", "srcItem": "Difference between Blunt Force Trauma and Penetrating Trauma"},
    {"id": "q-f202-s09-040", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does AMPLE stand for in the secondary survey?", "choices": ["Allergies, Medications, Past illness/Pregnancy, Last meal, Events", "Airway, Monitoring, Pulse, Lungs, Exposure", "Alert, Motor, Pupils, Lesions, Extremities", "Ambulance, Mechanism, Pain, Location, Effort"], "correct": 0, "explanation": "AMPLE history: Allergies, Medications (especially anticoagulants), Past illnesses/Pregnancy, Last meal, Events/Environment.", "srcItem": "Primary and secondary surveys, and the other lethal chest injuries"},
    {"id": "q-f202-s09-041", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What volume defines a massive hemothorax?", "choices": ["> 1500 mL", "> 150 mL", "> 50 mL", "> 5000 mL"], "correct": 0, "explanation": "Massive hemothorax: > 1500 mL of blood in the pleural space.", "srcItem": "Primary and secondary surveys, and the other lethal chest injuries"},
    {"id": "q-f202-s09-042", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is Beck's triad for cardiac tamponade?", "choices": ["Hypotension, JVD and muffled heart sounds", "Hypertension, bradycardia and irregular breathing", "Fever, rash and joint pain", "Tachypnea, crackles and wheezing"], "correct": 0, "explanation": "Beck's triad: hypotension, jugular venous distension, muffled heart sounds (not always all three).", "srcItem": "Primary and secondary surveys, and the other lethal chest injuries"},
    {"id": "q-f202-s09-043", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What defines flail chest per the Trauma deck?", "choices": ["Three or more ribs fractured in two or more places with paradoxical motion", "One rib fractured in one place", "Two ribs bruised", "Any sternal bruise"], "correct": 0, "explanation": "Flail chest: ≥ 3 ribs fractured in ≥ 2 places; the segment moves in on inspiration and out on exhalation.", "srcItem": "Primary and secondary surveys, and the other lethal chest injuries"},
    {"id": "q-f202-s09-044", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the most common shock state in injured patients?", "choices": ["Hemorrhagic (hypovolemic) shock", "Cardiogenic shock", "Septic shock", "Neurogenic shock"], "correct": 0, "explanation": "Hemorrhagic shock is most common; hypotension is often a late finding.", "srcItem": "Primary and secondary surveys, and the other lethal chest injuries"},
    {"id": "q-f202-s09-045", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which hematoma lies between the dura and the skull and may show a lucid interval?", "choices": ["Epidural hematoma", "Subdural hematoma", "Subarachnoid hemorrhage", "Diffuse axonal injury"], "correct": 0, "explanation": "Epidural: between dura and skull, often arterial, may expand rapidly after a lucid interval.", "srcItem": "Head-injury priorities"},
    {"id": "q-f202-s09-046", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "When is hyperventilation used in severe TBI?", "choices": ["Only for impending brain herniation, as a temporary measure", "Routinely for all head injuries", "Never under any circumstances", "To raise the cerebral blood flow"], "correct": 0, "explanation": "Hyperventilation is reserved for impending herniation; otherwise aim for normocapnia (PaCO₂ ~35–45).", "srcItem": "Head-injury priorities"},
    {"id": "q-f202-s09-047", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why must hypotension be avoided after TBI?", "choices": ["It reduces cerebral perfusion; a single SBP < 90 is linked to doubled mortality", "It raises the ICP", "It causes hyperventilation", "It increases cerebral blood flow"], "correct": 0, "explanation": "Hypotension reduces cerebral perfusion; Hess links a single SBP < 90 mm Hg to doubled mortality.", "srcItem": "Head-injury priorities"},
    {"id": "q-f202-s09-048", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does mannitol lower ICP, and what is its risk?", "choices": ["It shifts water out of the brain but, as a potent diuretic, may worsen hypotension", "It constricts cerebral vessels and causes hypertension", "It removes CSF directly", "It raises the PaCO₂"], "correct": 0, "explanation": "Mannitol draws water out of the brain; hypertonic saline does the same while supporting circulating volume.", "srcItem": "Head-injury priorities"},
    {"id": "q-f202-s09-049", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the most common cause of pulmonary embolism?", "choices": ["Venous thromboembolism from the leg veins", "Air embolism", "Fat embolism", "Amniotic fluid embolism"], "correct": 0, "explanation": "The most common cause of PE is VTE — clots from the leg veins that travel to the lungs.", "srcItem": "Postoperative VTE and Pulmonary Embolism"},
    {"id": "q-f202-s09-050", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A clot is already lodged in the pulmonary artery. Which drug dissolves it?", "choices": ["A thrombolytic such as tPA", "Heparin", "Warfarin", "Apixaban"], "correct": 0, "explanation": "Anticoagulants stop new clot; thrombolytics (tPA) dissolve existing clot.", "srcItem": "Postoperative VTE and Pulmonary Embolism"},
    {"id": "q-f202-s09-051", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "When is anticoagulation considered therapeutic?", "choices": ["When the PTT is 2 to 2.5 times the control", "When the PTT is normal", "When the PTT is 10 times control", "When the platelet count doubles"], "correct": 0, "explanation": "Therapeutic when clotting time or PTT is 2–2.5 times the control.", "srcItem": "Postoperative VTE and Pulmonary Embolism"},
    {"id": "q-f202-s09-052", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does Virchow's triad include?", "choices": ["Venous stasis, vascular injury and increased coagulability", "Hypoxemia, hypercapnia and acidosis", "Fever, tachycardia and hypotension", "JVD, hypotension and muffled heart sounds"], "correct": 0, "explanation": "Revised deck: DVT develops from venous stasis, vascular injury and increased coagulability.", "srcItem": "Postoperative VTE and Pulmonary Embolism"},
    {"id": "q-f202-s09-053", "topic": "f202-s09", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which device prevents leg clots from reaching the lungs?", "choices": ["Inferior vena cava filter", "Swan-Ganz catheter", "Chest tube", "Arterial line"], "correct": 0, "explanation": "An IVC (\"bird's nest\") filter prevents lower-extremity clots from reaching the lungs.", "srcItem": "Postoperative VTE and Pulmonary Embolism"},
    {"id": "q-f202-s10-001", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the difference between diagnostic and therapeutic bronchoscopy?", "choices": ["Diagnostic finds out what's wrong; therapeutic fixes the problem", "Diagnostic uses a rigid scope; therapeutic uses a flexible one", "Diagnostic is done only on ventilated patients", "Therapeutic is used only for biopsies"], "correct": 0, "explanation": "RCP 105: Diagnostic = \"Find out what's wrong\" (Look); Therapeutic = \"Fix a problem\" (Treat).", "srcItem": "Difference Between Diagnostic and Therapeutic Bronchoscopy"},
    {"id": "q-f202-s10-002", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which bronchoscopy procedure is therapeutic?", "choices": ["Removing a mucus plug", "Bronchoalveolar lavage for culture", "Transbronchial biopsy", "Airway inspection"], "correct": 0, "explanation": "Therapeutic: remove mucus plugs or foreign bodies, control bleeding, relieve obstruction. Diagnostic: biopsy, BAL, washing, inspection.", "srcItem": "Difference Between Diagnostic and Therapeutic Bronchoscopy"},
    {"id": "q-f202-s10-003", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which procedure is described as both diagnostic and therapeutic?", "choices": ["Fiberoptic bronchoscopy", "Chest radiograph", "Pulse oximetry", "Arterial blood gas"], "correct": 0, "explanation": "RCP 105 pearl: fiberoptic bronchoscopy is \"an excellent answer\" for a procedure that is both.", "srcItem": "Difference Between Diagnostic and Therapeutic Bronchoscopy"},
    {"id": "q-f202-s10-004", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "During laser or other heat therapy in the airway, what should the FiO₂ be reduced to?", "choices": ["40% or less", "60% or more", "100%", "Exactly 21% always"], "correct": 0, "explanation": "Hess: reduce FiO₂ to ≤ 40% so flammable airway components do not ignite.", "srcItem": "Difference Between Diagnostic and Therapeutic Bronchoscopy"},
    {"id": "q-f202-s10-005", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A child has sudden paroxysmal coughing, wheezing and diminished breath sounds on one side. What is suspected, and which scope is preferred?", "choices": ["Foreign body aspiration; rigid bronchoscopy", "Asthma; flexible bronchoscopy", "Pneumonia; no bronchoscopy", "Croup; rigid bronchoscopy"], "correct": 0, "explanation": "Classic FBA triad; rigid bronchoscopy remains the instrument of choice in children and for large objects.", "srcItem": "Indications for Bronchoscopy"},
    {"id": "q-f202-s10-006", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Before bronchoscopy for atelectasis, what should be tried first?", "choices": ["Noninvasive airway clearance such as CPT, PEP and coughing", "Immediate rigid bronchoscopy", "Thoracentesis", "Chest tube placement"], "correct": 0, "explanation": "Not every atelectasis needs bronchoscopy; try conservative airway clearance first.", "srcItem": "Indications for Bronchoscopy"},
    {"id": "q-f202-s10-007", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In massive hemoptysis, which bronchoscope is often preferred?", "choices": ["Rigid, for superior suctioning and ventilation", "Flexible, without intubation", "Neither — bronchoscopy is contraindicated", "A pediatric flexible scope"], "correct": 0, "explanation": "Hess: rigid is often preferred in massive hemoptysis; if a flexible scope is used, intubate first.", "srcItem": "Indications for Bronchoscopy"},
    {"id": "q-f202-s10-008", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the gold standard for diagnosing acute lung transplant rejection?", "choices": ["Transbronchial biopsy", "Chest radiograph", "Bronchial washing", "Spirometry alone"], "correct": 0, "explanation": "Hess: transbronchial biopsy is the gold standard for diagnosing acute rejection.", "srcItem": "Indications for Bronchoscopy"},
    {"id": "q-f202-s10-009", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which patient should NOT have elective bronchoscopy per the AARC criteria?", "choices": ["One who cannot be adequately oxygenated during the procedure", "One with a suspected lung mass", "One with chronic cough", "One with lobar atelectasis"], "correct": 0, "explanation": "Recommend against it if the patient cannot be oxygenated, has an uncorrectable bleeding disorder, severe obstruction, refractory hypoxemia or instability.", "srcItem": "Contraindications to Bronchoscopy"},
    {"id": "q-f202-s10-010", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the only major contraindication to BAL per the RCP 203 deck?", "choices": ["A predisposition for bleeding", "Chronic cough", "Pneumonia", "Recent extubation"], "correct": 0, "explanation": "RCP 203: the only major contraindication to BAL is a predisposition for bleeding.", "srcItem": "Contraindications to Bronchoscopy"},
    {"id": "q-f202-s10-011", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What are the normal PT and INR values given in the deck notes?", "choices": ["PT 11–13.5 s; INR 0.8–1.1", "PT 25–35 s; INR 2.0–3.0", "PT 60–80 s; INR 4–5", "PT 5–8 s; INR 0.1–0.5"], "correct": 0, "explanation": "PT 11–13.5 s; INR 0.8–1.1 (warfarin therapeutic 2.0–3.0); PTT 25–35 s.", "srcItem": "Contraindications to Bronchoscopy"},
    {"id": "q-f202-s10-012", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How long should elective bronchoscopy be deferred after a myocardial infarction (BTS)?", "choices": ["At least 6 weeks", "24 hours", "6 months", "No delay is needed"], "correct": 0, "explanation": "The British Thoracic Society recommends deferring bronchoscopy at least 6 weeks after an MI.", "srcItem": "Contraindications to Bronchoscopy"},
    {"id": "q-f202-s10-013", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What minimum platelet count does Hess give for transbronchial biopsy?", "choices": ["> 50,000/mm³", "> 5,000/mm³", "> 500,000/mm³", "Any count is acceptable"], "correct": 0, "explanation": "Fiberoptic bronchoscopy needs 20,000–50,000/mm³ minimum; transbronchial biopsy > 50,000/mm³.", "srcItem": "Contraindications to Bronchoscopy"},
    {"id": "q-f202-s10-014", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which antiplatelet drug need NOT be held before bronchoscopy, even for transbronchial biopsy?", "choices": ["Aspirin", "Clopidogrel", "Prasugrel", "Ticlopidine"], "correct": 0, "explanation": "Aspirin need not be held; clopidogrel and ticagrelor ≥ 5 days, prasugrel 7 days, ticlopidine 10–14 days.", "srcItem": "Contraindications to Bronchoscopy"},
    {"id": "q-f202-s10-015", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which bronchoscope can reach smaller, more distal airways?", "choices": ["Flexible (fiberoptic)", "Rigid", "Both reach equally", "Neither reaches past the trachea"], "correct": 0, "explanation": "The flexible scope reaches distal airways (to fourth-order bronchi); the rigid scope views mainly the central airways.", "srcItem": "Difference Between Flexible and Rigid Bronchoscopes"},
    {"id": "q-f202-s10-016", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What type of anesthesia does rigid bronchoscopy usually require?", "choices": ["General anesthesia", "Topical anesthesia only", "No anesthesia", "Local anesthesia with no sedation"], "correct": 0, "explanation": "Rigid bronchoscopy: general anesthesia (size and design); flexible: usually local with sedation.", "srcItem": "Difference Between Flexible and Rigid Bronchoscopes"},
    {"id": "q-f202-s10-017", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How much larger than the scope must an ETT be for flexible bronchoscopy (Hess)?", "choices": ["At least 1.5 mm larger (typically ≥ 8 mm ID)", "The same size as the scope", "At least 5 mm larger", "Smaller than the scope"], "correct": 0, "explanation": "Hess: the ETT must be ≥ 1.5 mm larger than the scope, typically ≥ 8 mm ID; a trach must be ≥ 6 mm ID.", "srcItem": "Difference Between Flexible and Rigid Bronchoscopes"},
    {"id": "q-f202-s10-018", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which stent type requires rigid bronchoscopy for placement?", "choices": ["Silicone stents", "Self-expanding metallic stents only", "Nasal stents", "Biliary stents"], "correct": 0, "explanation": "Lssn 7a: silicone stents require rigid bronchoscopy.", "srcItem": "Difference Between Flexible and Rigid Bronchoscopes"},
    {"id": "q-f202-s10-019", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the most common route for flexible bronchoscopy, and why?", "choices": ["Transnasal — it anchors the scope for stability and comfort", "Oral without a bite block", "Through a chest tube", "Through the esophagus"], "correct": 0, "explanation": "Transnasal is most common; the oral route requires a bite block.", "srcItem": "Difference Between Flexible and Rigid Bronchoscopes"},
    {"id": "q-f202-s10-020", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the reversal agent for midazolam (Versed)?", "choices": ["Flumazenil (Romazicon)", "Naloxone (Narcan)", "Atropine", "Neostigmine"], "correct": 0, "explanation": "Versed = benzodiazepine = flumazenil; it can precipitate seizures, so it is not used routinely.", "srcItem": "Pharmacologic Agents"},
    {"id": "q-f202-s10-021", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the reversal agent for fentanyl (Sublimaze)?", "choices": ["Naloxone (Narcan)", "Flumazenil", "Propofol", "There is none"], "correct": 0, "explanation": "Fentanyl = pain = opioid = naloxone.", "srcItem": "Pharmacologic Agents"},
    {"id": "q-f202-s10-022", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which bronchoscopy sedative has NO reversal agent?", "choices": ["Propofol (Diprivan)", "Midazolam", "Fentanyl", "Morphine"], "correct": 0, "explanation": "Propofol is neither an opioid nor a benzodiazepine, so it has no reversal agent.", "srcItem": "Pharmacologic Agents"},
    {"id": "q-f202-s10-023", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why is lidocaine given before bronchoscopy?", "choices": ["Local anesthesia that reduces mucosal irritation and suppresses cough", "To dry secretions", "To reverse sedation", "To dilate the bronchi"], "correct": 0, "explanation": "Lidocaine (5–10 mL of 1–4% per RCP 105) is a local anesthetic that suppresses cough.", "srcItem": "Pharmacologic Agents"},
    {"id": "q-f202-s10-024", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why may atropine be given before bronchoscopy?", "choices": ["To reduce the vagal response and oral secretions", "To provide amnesia", "To relieve pain", "To prevent bleeding"], "correct": 0, "explanation": "Atropine reduces vagal response, secretions and bronchospasm (many centers have dropped it, per Hess).", "srcItem": "Pharmacologic Agents"},
    {"id": "q-f202-s10-025", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why does combining midazolam and fentanyl require close monitoring?", "choices": ["Together they potentiate respiratory depression", "Together they cause hypertension", "They cancel each other out", "They cause bronchodilation"], "correct": 0, "explanation": "Benzodiazepines plus opioids potentiate respiratory depression; keep naloxone and flumazenil ready.", "srcItem": "Pharmacologic Agents"},
    {"id": "q-f202-s10-026", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What complication are you most likely to see during bronchoscopy?", "choices": ["Hypoxemia", "Pneumothorax", "Massive hemorrhage", "Infection"], "correct": 0, "explanation": "RCP 105: hypoxemia is \"the complication you're most likely to see\"; transient hypoxemia occurs in up to 35%.", "srcItem": "Methods of Monitoring During the Procedure"},
    {"id": "q-f202-s10-027", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A flexible scope is passed through a ventilated patient's ETT. What ventilator changes are expected?", "choices": ["Delivered VT may fall and peak pressure may rise", "PIP falls and VT rises", "Nothing changes", "The PEEP drops to zero"], "correct": 0, "explanation": "The scope raises airway resistance: VT may fall, PIP rise; FiO₂ is often raised to 100% and the high-pressure limit adjusted.", "srcItem": "Methods of Monitoring During the Procedure"},
    {"id": "q-f202-s10-028", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How much supplemental O₂ may a spontaneously breathing patient without an artificial airway receive during bronchoscopy (RCP 105)?", "choices": ["Up to 6 L/min", "Exactly 15 L/min", "No oxygen", "Up to 1 L/min only"], "correct": 0, "explanation": "Use the RCP 105 deck's up to 6 L/min (Hess says 2–3 L/min for all patients).", "srcItem": "Methods of Monitoring During the Procedure"},
    {"id": "q-f202-s10-029", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "After bronchoscopy, how long should vital signs be monitored?", "choices": ["At least 2 hours or until stable", "15 minutes", "24 hours in the ICU", "Monitoring is not needed"], "correct": 0, "explanation": "RCP 105: monitor vitals for at least 2 hours or until stable; O₂ may usually stop 4 hours after.", "srcItem": "Methods of Monitoring During the Procedure"},
    {"id": "q-f202-s10-030", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How is COPD defined in the deck?", "choices": ["Preventable, treatable, progressive, irreversible airflow limitation", "Reversible airflow obstruction only", "Permanent enlargement of air spaces with wall destruction", "Regurgitation of stomach contents into the esophagus"], "correct": 0, "explanation": "COPD is the umbrella over chronic bronchitis and emphysema; diagnosis needs post-bronchodilator FEV₁/FVC < 0.70.", "srcItem": "Difference Between COPD, GERD, Emphysema, and Lung Cancer"},
    {"id": "q-f202-s10-031", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which definition describes emphysema?", "choices": ["Permanent enlargement of air spaces distal to terminal bronchioles with alveolar wall destruction", "Productive cough for 3 months in 2 consecutive years", "Uncontrolled multiplication of bronchial cells", "Backflow of stomach contents"], "correct": 0, "explanation": "Emphysema: permanent air-space enlargement with alveolar wall destruction; chronic bronchitis is the cough definition.", "srcItem": "Difference Between COPD, GERD, Emphysema, and Lung Cancer"},
    {"id": "q-f202-s10-032", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does GERD relate to bronchoscopy indications?", "choices": ["It is one of the most common causes of chronic cough", "It requires rigid bronchoscopy for treatment", "It is a contraindication to BAL", "It causes pneumothorax"], "correct": 0, "explanation": "GERD, asthma and postnasal drip are the most common causes of chronic cough; reflux is treated before bronchoscopy is considered.", "srcItem": "Difference Between COPD, GERD, Emphysema, and Lung Cancer"},
    {"id": "q-f202-s10-033", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What bronchoscopic treatment reduces hyperinflation in selected patients with advanced emphysema?", "choices": ["One-way endobronchial valves", "Airway stents", "Laser resection", "Thrombin instillation"], "correct": 0, "explanation": "One-way valves (e.g. Zephyr) let trapped air out but not in; the major complication is pneumothorax.", "srcItem": "Difference Between COPD, GERD, Emphysema, and Lung Cancer"},
    {"id": "q-f202-s10-034", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which bronchoscopic technique is valuable for lung cancer diagnosis and mediastinal lymph node staging?", "choices": ["EBUS-TBNA", "Bronchial washing alone", "Protected brush", "Airway inspection only"], "correct": 0, "explanation": "EBUS-guided TBNA samples lymph nodes beyond the airway wall for diagnosis and staging.", "srcItem": "Difference Between COPD, GERD, Emphysema, and Lung Cancer"},
    {"id": "q-f202-s10-035", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the key technical difference between BAL and bronchial washing?", "choices": ["BAL is done with the scope wedged; washing is done without wedging", "Washing reaches the alveoli; BAL does not", "BAL uses no saline", "Washing requires general anesthesia"], "correct": 0, "explanation": "BAL = scope wedged in a segmental bronchus → alveolar sampling; washing = no wedge → larger airways.", "srcItem": "Difference Between Lavage, Washing, Brushing, and Biopsy"},
    {"id": "q-f202-s10-036", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which rule matches the RCP 105 deck?", "choices": ["Biopsy = a piece of tissue; cytology = cells", "Biopsy = cells; cytology = tissue", "Brushing yields tissue sections", "Needle aspiration yields whole tissue"], "correct": 0, "explanation": "\"Biopsy = Piece of tissue; Cytology = Cells.\" Forceps = tissue, needle = cells, brush = surface cells.", "srcItem": "Difference Between Lavage, Washing, Brushing, and Biopsy"},
    {"id": "q-f202-s10-037", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why is a protected specimen brush used?", "choices": ["To sample lower-tract organisms with less upper-airway contamination", "To remove foreign bodies", "To dilate airway stenosis", "To stop bleeding"], "correct": 0, "explanation": "Protected brush = organisms (microbiology), with a double telescoping catheter and plug to limit contamination.", "srcItem": "Difference Between Lavage, Washing, Brushing, and Biopsy"},
    {"id": "q-f202-s10-038", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which sampling technique carries the main risk of pneumothorax?", "choices": ["Transbronchial lung biopsy", "Bronchial washing", "Airway inspection", "Standard brushing of a central lesion"], "correct": 0, "explanation": "Pneumothorax 1–6%, mainly after TBB, which samples lung beyond the airway wall.", "srcItem": "Difference Between Lavage, Washing, Brushing, and Biopsy"},
    {"id": "q-f202-s10-039", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which sample from the alveolar space is used to diagnose Pneumocystis pneumonia?", "choices": ["Bronchoalveolar lavage", "Endobronchial biopsy", "Bronchial washing", "Throat swab"], "correct": 0, "explanation": "BAL samples the alveolar space; RCP 103 notes it diagnoses PCP.", "srcItem": "Difference Between Lavage, Washing, Brushing, and Biopsy"},
    {"id": "q-f202-s10-040", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "According to Hess's Key Points, when is pleural fluid an exudate?", "choices": ["Pleural fluid:serum protein ≥ 0.5 or pleural fluid:serum LDH ≥ 0.6", "Protein ratio < 0.2", "LDH ratio < 0.1", "When the fluid is clear"], "correct": 0, "explanation": "Hess KP: exudate if protein ratio ≥ 0.5 or LDH ratio ≥ 0.6; transudate = pressure problem, exudate = inflammation/infection/malignancy.", "srcItem": "Hess Ch 9 \"Key Points\""},
    {"id": "q-f202-s10-041", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What are the indications for thoracentesis (Hess Key Points)?", "choices": ["Diagnosing a new effusion of unknown cause and relieving dyspnea from a large effusion", "Treating pneumothorax", "Removing mucus plugs", "Diagnosing asthma"], "correct": 0, "explanation": "Thoracentesis: diagnose a new effusion of unknown etiology; relieve dyspnea from a large effusion.", "srcItem": "Hess Ch 9 \"Key Points\""},
    {"id": "q-f202-s10-042", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the traditional treatment for recurrent pleural effusions?", "choices": ["Pleurodesis", "Repeated bronchoscopy", "Intubation", "High-flow nasal cannula"], "correct": 0, "explanation": "Pleurodesis by mechanical abrasion or a sclerosing agent; talc is most efficacious (80% at 30 days).", "srcItem": "Hess Ch 9 \"Key Points\""},
    {"id": "q-f202-s10-043", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the ideal patient for fiberoptic bronchoscopy per the Key Points?", "choices": ["Awake, able to understand and cooperate, without conditions that raise risk", "Deeply sedated and paralyzed", "Unconscious only", "In status asthmaticus"], "correct": 0, "explanation": "The ideal patient is awake and cooperative; the deck adds it can also be done on unconscious or ventilated patients.", "srcItem": "Hess Ch 9 \"Key Points\""},
    {"id": "q-f202-s10-044", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How much pleural fluid does Hess say is safe to remove at one time?", "choices": ["1500 mL", "150 mL", "5000 mL", "50 mL"], "correct": 0, "explanation": "Hess: removing 1500 mL of fluid at a time is safe.", "srcItem": "Hess Ch 9 \"Key Points\""},
    {"id": "q-f202-s10-045", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Significant bleeding occurs during bronchoscopy. What can be instilled through the working channel to control it?", "choices": ["Epinephrine, thrombin or iced saline", "Lidocaine 10%", "Acetylcysteine", "Albuterol"], "correct": 0, "explanation": "Stop bleeding with epinephrine or thrombin (pharmacologic) or iced saline; airway and oxygenation come first.", "srcItem": "Complications of Bronchoscopy and Their Management"},
    {"id": "q-f202-s10-046", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which two complications does RCP 105 call the most common during and after bronchoscopy?", "choices": ["Hypoxemia and arrhythmias", "Pneumothorax and infection", "Fever and bleeding", "Laryngospasm and stridor"], "correct": 0, "explanation": "\"Hypoxemia and arrhythmias are the most common complications during and after bronchoscopy.\"", "srcItem": "Complications of Bronchoscopy and Their Management"},
    {"id": "q-f202-s10-047", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A ventilated patient becomes cyanotic, tachycardic and diaphoretic after a transbronchial biopsy. What is suspected?", "choices": ["Tension pneumothorax", "Vasovagal reaction", "Hypoglycemia", "Bronchospasm from lidocaine"], "correct": 0, "explanation": "On MV, a lung puncture can become a tension pneumothorax; have a complete chest-tube setup available.", "srcItem": "Complications of Bronchoscopy and Their Management"},
    {"id": "q-f202-s10-048", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which organisms have outbreaks been traced to the flexible bronchoscope?", "choices": ["M. tuberculosis and Pseudomonas aeruginosa", "Influenza and RSV", "Streptococcus pyogenes only", "Candida albicans only"], "correct": 0, "explanation": "RCP 105: outbreaks of M. tuberculosis and P. aeruginosa have been traced to flexible bronchoscopes.", "srcItem": "Complications of Bronchoscopy and Their Management"},
    {"id": "q-f202-s10-049", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How long should a patient be NPO before bronchoscopy (Lssn 7a deck)?", "choices": ["6–8 hours", "30 minutes", "24 hours", "No fasting is needed"], "correct": 0, "explanation": "Use the deck's 6–8 hours to reduce aspiration risk.", "srcItem": "Preparation, Post-Bronchoscopy Care, and Scope Reprocessing"},
    {"id": "q-f202-s10-050", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "After bronchoscopy, a patient develops stridor. What should the RT give?", "choices": ["Racemic epinephrine", "An albuterol MDI", "Lidocaine", "Acetylcysteine"], "correct": 0, "explanation": "\"Stridor = upper airway → racemic epi; wheezing = lower airway → bronchodilator.\"", "srcItem": "Preparation, Post-Bronchoscopy Care, and Scope Reprocessing"},
    {"id": "q-f202-s10-051", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "When may a patient eat or drink after bronchoscopy?", "choices": ["After the gag reflex returns", "Immediately after the procedure", "After 72 hours", "Only after a swallow study"], "correct": 0, "explanation": "Lidocaine numbs the throat; withhold food and drink until the gag reflex returns.", "srcItem": "Preparation, Post-Bronchoscopy Care, and Scope Reprocessing"},
    {"id": "q-f202-s10-052", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What level of processing does a bronchoscope (semicritical) need per RCP 203?", "choices": ["Sterilization or high-level disinfection", "Low-level disinfection only", "Soap and water cleaning only", "No processing"], "correct": 0, "explanation": "Semicritical → sterilization or HLD; glutaraldehyde gives HLD in 20 min, sterilization in 10 h.", "srcItem": "Preparation, Post-Bronchoscopy Care, and Scope Reprocessing"},
    {"id": "q-f202-s10-053", "topic": "f202-s10", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Biopsy forceps passed through the bronchoscope into tissue require which processing?", "choices": ["Sterilization", "High-level disinfection", "Low-level disinfection", "Rinsing in tap water"], "correct": 0, "explanation": "Forceps entering tissue are critical items → sterilization.", "srcItem": "Preparation, Post-Bronchoscopy Care, and Scope Reprocessing"},
    {"id": "q-f202-s11-001", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which are the four major groups of lung transplant recipients (Hess)?", "choices": ["COPD/emphysema, CF/bronchiectasis, IPF and pulmonary arterial hypertension", "Asthma, pneumonia, ARDS and lung cancer", "TB, sarcoidosis, asthma and croup", "Pneumothorax, PE, pleural effusion and ARDS"], "correct": 0, "explanation": "Hess: COPD/emphysema, cystic fibrosis/bronchiectasis, IPF and PAH.", "srcItem": "Disease States Considered for Lung Transplant"},
    {"id": "q-f202-s11-002", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which drug cut idiopathic PAH transplants by nearly 75% by 1998?", "choices": ["IV epoprostenol", "Cyclosporine", "Albuterol", "Warfarin"], "correct": 0, "explanation": "IV epoprostenol (introduced 1995) cut IPAH transplants by nearly 75% by 1998.", "srcItem": "Disease States Considered for Lung Transplant"},
    {"id": "q-f202-s11-003", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A COPD patient also has bronchiectasis with purulent secretions. Which transplant is required?", "choices": ["Double-lung transplant", "Single-lung transplant", "Heart transplant only", "No transplant is possible"], "correct": 0, "explanation": "Hess Ch 33: coexisting bronchiectasis with purulent secretions requires double-lung transplantation.", "srcItem": "Disease States Considered for Lung Transplant"},
    {"id": "q-f202-s11-004", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which CF finding is an indication for transplant referral (Table 46-1)?", "choices": ["FEV₁ declining to 30% despite optimal therapy", "FEV₁ of 85% predicted", "A single mild exacerbation", "Normal PaCO₂ and PaO₂"], "correct": 0, "explanation": "CF referral: FEV₁ to 30% or rapid decline, PaCO₂ > 50 and/or PaO₂ < 55, 6MWT < 400 m, secondary PH, clinical decline.", "srcItem": "Disease States Considered for Lung Transplant"},
    {"id": "q-f202-s11-005", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the preferred transplant operation for cystic fibrosis?", "choices": ["Sequential bilateral lung transplantation", "Single-lung transplant", "Heart–lung transplant", "Lobar resection"], "correct": 0, "explanation": "Hess Ch 37: sequential bilateral transplantation rather than heart–lung.", "srcItem": "Disease States Considered for Lung Transplant"},
    {"id": "q-f202-s11-006", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In what year was the first successful lung transplant (Toronto, pulmonary fibrosis)?", "choices": ["1983", "1963", "1986", "1995"], "correct": 0, "explanation": "1983: the Toronto Lung Transplant Group; the patient survived 7 years on cyclosporine and azathioprine.", "srcItem": "Dates of the First Single- and Double-Lung Transplants"},
    {"id": "q-f202-s11-007", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In what year was the first successful double-lung transplant for emphysema?", "choices": ["1986", "1983", "1963", "1981"], "correct": 0, "explanation": "Hess: 1986 was the first successful double-lung transplant for emphysema.", "srcItem": "Dates of the First Single- and Double-Lung Transplants"},
    {"id": "q-f202-s11-008", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Who performed the first lung transplant ever, in 1963?", "choices": ["Dr. James Hardy", "Dr. Bruce Reitz", "Dr. Shigeto Ikeda", "Dr. Peter Safar"], "correct": 0, "explanation": "Hardy, 1963; the patient survived 18 days. Reitz did the first heart–lung transplant (1981).", "srcItem": "Dates of the First Single- and Double-Lung Transplants"},
    {"id": "q-f202-s11-009", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the average survival after lung transplant today, per Hess?", "choices": ["5 to 6 years", "About 18 days", "About 1 year", "About 20 years"], "correct": 0, "explanation": "Average survival rose from about 4 years (1980s–90s) to 5–6 years now.", "srcItem": "Dates of the First Single- and Double-Lung Transplants"},
    {"id": "q-f202-s11-010", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the goal of the Lung Allocation Score?", "choices": ["To maximize overall survival benefit by balancing waitlist mortality and post-transplant survival", "To give priority to patients waiting longest", "To match lungs by blood type only", "To select only young donors"], "correct": 0, "explanation": "The LAS balances waitlist mortality against post-transplant survival (OPTN, May 2005).", "srcItem": "Lung Allocation Score (LAS) Details"},
    {"id": "q-f202-s11-011", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What range of values does the LAS assign each patient?", "choices": ["0 to 100", "1 to 10", "3 to 15", "0 to 1000"], "correct": 0, "explanation": "Each patient is assigned a number from 0 to 100; it applies to recipients aged 12 and older.", "srcItem": "Lung Allocation Score (LAS) Details"},
    {"id": "q-f202-s11-012", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How were donor lungs allocated before the LAS (before 2005)?", "choices": ["By time on the waiting list", "By the patient's income", "By the LAS score", "By a lottery"], "correct": 0, "explanation": "Listing time favored slowly progressive diseases (COPD) over rapidly declining ones (IPF, severe PH).", "srcItem": "Lung Allocation Score (LAS) Details"},
    {"id": "q-f202-s11-013", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What change followed the LAS's introduction?", "choices": ["COPD transplants fell and IPF transplants rose", "COPD transplants doubled", "IPF transplants stopped", "Single-lung transplants became 90% of cases"], "correct": 0, "explanation": "After 2005, COPD transplants fell ~10% and IPF rose by about the same; single-lung is now 25% of transplants.", "srcItem": "Lung Allocation Score (LAS) Details"},
    {"id": "q-f202-s11-014", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Besides a high LAS, which factor affects whether a patient receives a particular donor lung?", "choices": ["Blood-type compatibility and chest size", "Hair color", "Home address only", "Previous employer"], "correct": 0, "explanation": "Also: blood type, HLA profile, chest cavity size, donor age and distance within the OPO region.", "srcItem": "Lung Allocation Score (LAS) Details"},
    {"id": "q-f202-s11-015", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What ventilator approach is used after lung transplant?", "choices": ["Lung-protective ventilation with VT about 6 mL/kg PBW and minimized PEEP and FiO₂", "High VT of 12 mL/kg to open the graft", "High PEEP of 20 cm H₂O routinely", "FiO₂ 1.0 for 72 hours"], "correct": 0, "explanation": "Key Point: lung-protective ventilation with minimization of PEEP and FiO₂ are the cornerstones (Pplat ≤ 30).", "srcItem": "Lung-Protective Strategies During Mechanical Ventilation for Lung Tran"},
    {"id": "q-f202-s11-016", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "During a single-lung transplant, how is the patient ventilated?", "choices": ["The contralateral lung gets single-lung ventilation while the PA to the removed lung is clamped", "Both lungs are ventilated normally", "No ventilation is given", "Jet ventilation through the new graft"], "correct": 0, "explanation": "Single-lung ventilation of the other lung; clamping the PA to the lung being removed prevents shunt.", "srcItem": "Lung-Protective Strategies During Mechanical Ventilation for Lung Tran"},
    {"id": "q-f202-s11-017", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In a bilateral transplant, which native lung is removed first?", "choices": ["The lung with the worst function on V/Q scan", "The right lung always", "The left lung always", "The larger lung"], "correct": 0, "explanation": "The worst-functioning native lung (by V/Q scan) is removed first while the other gets single-lung ventilation.", "srcItem": "Lung-Protective Strategies During Mechanical Ventilation for Lung Tran"},
    {"id": "q-f202-s11-018", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does 'awake ECMO' as a bridge to transplant allow?", "choices": ["The patient can be awake, eating and doing physical therapy while waiting", "The patient to skip transplant entirely", "Removal of all sedation and the ventilator before ECMO", "Faster lung recovery without a donor"], "correct": 0, "explanation": "Deck: a CF patient on bridging ECMO may be awake, eating and in PT; Hess says this improves outcomes.", "srcItem": "Lung-Protective Strategies During Mechanical Ventilation for Lung Tran"},
    {"id": "q-f202-s11-019", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which is an exclusion criterion for lung transplant in Table 46-3?", "choices": ["Active Mycobacterium tuberculosis infection", "A BMI within normal range", "Age 45", "Well-controlled hypertension"], "correct": 0, "explanation": "Exclusions include active TB, virulent resistant infection, recent malignancy, active addiction, uncorrectable bleeding.", "srcItem": "Recipient Candidacy and Exclusion Criteria"},
    {"id": "q-f202-s11-020", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which contraindication can be corrected so the patient may later qualify?", "choices": ["Obesity over 130% of ideal body weight", "Active tuberculosis", "Untreatable advanced kidney failure", "Uncorrectable bleeding diathesis"], "correct": 0, "explanation": "Lack of pulmonary rehab and obesity (> 130% IBW) can be corrected.", "srcItem": "Recipient Candidacy and Exclusion Criteria"},
    {"id": "q-f202-s11-021", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Unlike kidney transplant, what does lung transplant NOT routinely require?", "choices": ["A close HLA match", "Blood-type compatibility", "A donor", "Immunosuppression"], "correct": 0, "explanation": "Revised notes: lungs don't routinely need a close HLA match; preexisting donor-specific antibodies matter.", "srcItem": "Recipient Candidacy and Exclusion Criteria"},
    {"id": "q-f202-s11-022", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the 'lung transplant window'?", "choices": ["The time between activation on the waiting list and the transplant", "The surgical incision", "The ischemic time of the donor lung", "The time on ECMO after surgery"], "correct": 0, "explanation": "Glossary: the time between activation on the waiting list and the transplantation procedure.", "srcItem": "Recipient Candidacy and Exclusion Criteria"},
    {"id": "q-f202-s11-023", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is primary graft dysfunction?", "choices": ["A severe ischemia/reperfusion acute lung injury after transplant", "Chronic rejection years later", "An infection of the donor lung", "A failure of the bronchial anastomosis"], "correct": 0, "explanation": "PGD: severe ischemia/reperfusion injury, a major cause of early morbidity and mortality.", "srcItem": "Primary Graft Dysfunction and Postoperative Care"},
    {"id": "q-f202-s11-024", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How is PGD graded?", "choices": ["0 to 3 by P/F ratio and infiltrates", "1 to 10 by chest tube output", "By FEV₁ alone", "By the LAS"], "correct": 0, "explanation": "Grade 0–3 by PaO₂/FiO₂ (with infiltrates); measured on ICU arrival and daily for 72 hours.", "srcItem": "Primary Graft Dysfunction and Postoperative Care"},
    {"id": "q-f202-s11-025", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A transplant patient has a P/F of 180 with infiltrates. What PGD grade is this?", "choices": ["Grade 3", "Grade 0", "Grade 1", "Grade 2"], "correct": 0, "explanation": "Grade 3: P/F < 200 with infiltrates; grade 2 is 200–300.", "srcItem": "Primary Graft Dysfunction and Postoperative Care"},
    {"id": "q-f202-s11-026", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which drug is given within a week after transplant to prevent Pneumocystis jirovecii?", "choices": ["Trimethoprim–sulfamethoxazole", "Ganciclovir", "Amphotericin", "Heparin"], "correct": 0, "explanation": "TMP-SMX for PJP; ganciclovir → valganciclovir for CMV; antifungals such as inhaled amphotericin.", "srcItem": "Primary Graft Dysfunction and Postoperative Care"},
    {"id": "q-f202-s11-027", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the main treatment for primary graft dysfunction?", "choices": ["Supportive care: lung-protective ventilation, careful fluids, ECMO if severe", "Immediate retransplant", "High-dose antibiotics only", "Removal of all PEEP"], "correct": 0, "explanation": "Supportive care is the most common standard treatment; an inhaled vasodilator is often given.", "srcItem": "Primary Graft Dysfunction and Postoperative Care"},
    {"id": "q-f202-s11-028", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which is a precondition before brain-death testing of a potential donor?", "choices": ["Core temperature ≥ 36 °C and SBP ≥ 100 mm Hg", "Core temperature below 32 °C", "PaCO₂ above 60 mm Hg", "Ongoing sedation"], "correct": 0, "explanation": "Preconditions: core temp ≥ 36 °C, SBP ≥ 100, eucapnia, no hypoxia, euvolemia.", "srcItem": "Donor Evaluation and Management"},
    {"id": "q-f202-s11-029", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "When is the apnea test positive (consistent with brain death)?", "choices": ["PaCO₂ > 60 mm Hg or > 20 above baseline with no breathing activity", "PaCO₂ falls below 30 mm Hg", "The patient takes one breath", "SpO₂ stays above 95%"], "correct": 0, "explanation": "Disconnect up to 8 minutes; positive if PaCO₂ > 60 (or > 20 above baseline) with no breathing.", "srcItem": "Donor Evaluation and Management"},
    {"id": "q-f202-s11-030", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which PaO₂ is a typical donor criterion?", "choices": ["> 300 mm Hg on FiO₂ 1.0 and PEEP 5", "> 60 mm Hg on FiO₂ 0.21", "> 100 mm Hg on room air", "> 500 mm Hg on FiO₂ 0.4"], "correct": 0, "explanation": "Typical criteria: age < 55, ABO compatible, PaO₂ > 300 on FiO₂ 1.0/PEEP 5, no significant chest trauma or aspiration.", "srcItem": "Donor Evaluation and Management"},
    {"id": "q-f202-s11-031", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "At what temperature are donor lungs stored?", "choices": ["4–8 °C", "Body temperature only", "−20 °C (frozen)", "20–25 °C"], "correct": 0, "explanation": "Chilled Perfadex flush and storage at 4–8 °C; freezing must be avoided.", "srcItem": "Donor Evaluation and Management"},
    {"id": "q-f202-s11-032", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What ventilator limit is used in a potential lung donor?", "choices": ["Plateau (and ideally peak) pressure < 30 cm H₂O", "PIP > 40 cm H₂O to recruit", "PEEP of 20 cm H₂O", "VT of 15 mL/kg"], "correct": 0, "explanation": "Donor management: Pplat and ideally PIP < 30; prevent interstitial fluid overload.", "srcItem": "Donor Management and Procurement"},
    {"id": "q-f202-s11-033", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A brain-dead donor develops excessive dilute urine and hypernatremia. What is given?", "choices": ["Desmopressin (DDAVP) for central diabetes insipidus", "Furosemide", "Insulin", "Hypotonic fluids only"], "correct": 0, "explanation": "Brain death can cause central DI (low ADH); desmopressin is often used.", "srcItem": "Donor Management and Procurement"},
    {"id": "q-f202-s11-034", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does the Perfadex flush do during procurement?", "choices": ["Cools the lung tissue and clears blood from the vascular bed", "Inflates the alveoli", "Sterilizes the airway", "Dissolves blood clots in the bronchi"], "correct": 0, "explanation": "The chilled low-potassium dextran flush cools tissue and removes blood, preventing thrombosis and endothelial injury.", "srcItem": "Donor Management and Procurement"},
    {"id": "q-f202-s11-035", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In a single-lung transplant, in what order are the anastomoses done?", "choices": ["Bronchus → pulmonary artery → pulmonary veins to the left atrium", "Pulmonary veins → bronchus → pulmonary artery", "Pulmonary artery → bronchus → aorta", "Left atrium → bronchus → trachea"], "correct": 0, "explanation": "Posterior to anterior: bronchus, then pulmonary artery, then pulmonary veins to the left atrium.", "srcItem": "The Two Operations, Step by Step"},
    {"id": "q-f202-s11-036", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What incision is used for a bilateral (double-lung) transplant?", "choices": ["A transverse thoracosternotomy (clamshell)", "A posterolateral thoracotomy on one side", "A tracheostomy", "A laparotomy"], "correct": 0, "explanation": "Bilateral: clamshell incision with sequential implantation; single-lung: postero- or anterolateral thoracotomy.", "srcItem": "The Two Operations, Step by Step"},
    {"id": "q-f202-s11-037", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How did ECMO compare with cardiopulmonary bypass during lung transplant?", "choices": ["Fewer transfusions, less PGD and fewer complications, with similar survival", "More complications and lower survival", "No difference in any outcome", "ECMO cannot be used in transplant"], "correct": 0, "explanation": "\"Lower complications in ECMO patients vs. CPB\"; no difference in 30-day or 1-year survival.", "srcItem": "The Two Operations, Step by Step"},
    {"id": "q-f202-s11-038", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In a single-lung transplant for COPD, why can the new lung be at risk after surgery?", "choices": ["The more compliant native lung takes more of the VT, risking overdistension", "The new lung receives no blood flow", "The native lung is removed later", "The new lung cannot be ventilated"], "correct": 0, "explanation": "Revised deck: in single-lung transplant for COPD, the compliant native lung may take more of the VT.", "srcItem": "The Two Operations, Step by Step"},
    {"id": "q-f202-s11-039", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What replaced the LAS in March 2023?", "choices": ["The composite allocation score (CAS) under continuous distribution", "A waiting-time system", "A lottery system", "The MELD score"], "correct": 0, "explanation": "The CAS replaced the LAS on March 9, 2023; it still uses the LAS as a component plus factors like donor proximity.", "srcItem": "How Lungs Are Allocated Today"},
    {"id": "q-f202-s11-040", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "If an exam question asks about the 'Lung Allocation Score', how should it be answered?", "choices": ["Answer the LAS, which the study guide and Hess ask for", "Always answer with the CAS", "Answer with MELD", "Answer with BODE"], "correct": 0, "explanation": "The deck says to answer the LAS when the question names it; treat the CAS as current-practice context.", "srcItem": "How Lungs Are Allocated Today"},
    {"id": "q-f202-s11-041", "topic": "f202-s11", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which input feeds the LAS per the deck?", "choices": ["Serum creatinine as an indicator of kidney function", "Hair color", "Driving record", "Number of children"], "correct": 0, "explanation": "LAS inputs: age, BMI, diagnosis, pulmonary function, functional status, PA pressure/cardiac output, creatinine.", "srcItem": "How Lungs Are Allocated Today"},
    {"id": "q-f202-s12-001", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What are the primary functions of the respiratory system (Hess Key Points)?", "choices": ["Gas distribution and gas exchange", "Acid secretion and digestion", "Blood filtration and urine production", "Hormone storage"], "correct": 0, "explanation": "Key Point: the primary functions are gas distribution and gas exchange.", "srcItem": "What the respiratory system does"},
    {"id": "q-f202-s12-002", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which process is the movement of air from the atmosphere into the lungs?", "choices": ["Ventilation", "Perfusion", "Diffusion", "Internal respiration"], "correct": 0, "explanation": "Ventilation = air movement; perfusion = blood circulation; diffusion = gas movement across the A–C membrane.", "srcItem": "What the respiratory system does"},
    {"id": "q-f202-s12-003", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Gas exchange between the blood and the body's tissues is called what?", "choices": ["Internal respiration", "External respiration", "Ventilation", "Perfusion"], "correct": 0, "explanation": "External respiration = alveoli ↔ blood; internal respiration = blood ↔ tissues.", "srcItem": "What the respiratory system does"},
    {"id": "q-f202-s12-004", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Where does gas exchange occur exclusively?", "choices": ["At the acinus (alveolar level)", "In the trachea", "In the main stem bronchi", "In the nasopharynx"], "correct": 0, "explanation": "Hess: gas exchange occurs exclusively at the acinus or alveolar level.", "srcItem": "What the respiratory system does"},
    {"id": "q-f202-s12-005", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the correct order of the five stages of fetal lung development?", "choices": ["Embryonic → pseudoglandular → canalicular → saccular → alveolar", "Pseudoglandular → embryonic → saccular → canalicular → alveolar", "Alveolar → saccular → canalicular → pseudoglandular → embryonic", "Embryonic → canalicular → pseudoglandular → alveolar → saccular"], "correct": 0, "explanation": "Memorize: Embryonic, Pseudoglandular, Canalicular, Saccular, Alveolar.", "srcItem": "Growth and development"},
    {"id": "q-f202-s12-006", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "During which stage do type I and type II alveolar cells first appear, making limited gas exchange possible?", "choices": ["Canalicular (17–26 weeks)", "Pseudoglandular (6–16 weeks)", "Embryonic (4–6 weeks)", "Alveolar (36 weeks on)"], "correct": 0, "explanation": "Canalicular stage: capillary network and type I/II cells; a premature fetus can survive with intensive care.", "srcItem": "Growth and development"},
    {"id": "q-f202-s12-007", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A fetus delivered during the pseudoglandular stage has what chance of survival?", "choices": ["Highly unlikely to survive", "Excellent survival with no support", "Normal term-infant survival", "Survival only on room air"], "correct": 0, "explanation": "Pseudoglandular (6–16 weeks): conducting airways only; survival of premature delivery is highly unlikely.", "srcItem": "Growth and development"},
    {"id": "q-f202-s12-008", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "By what age does the number of alveoli peak at about 300 million?", "choices": ["About 8 years", "At birth", "About 1 month", "About 25 years"], "correct": 0, "explanation": "Birth: 20–150 million (average ≈ 50 million); peaks at ≈ 300 million by age 8.", "srcItem": "Growth and development"},
    {"id": "q-f202-s12-009", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the narrowest part of the upper airway in an infant, for boards?", "choices": ["The cricoid ring", "The glottis", "The nares", "The trachea at the carina"], "correct": 0, "explanation": "Adults = glottis; children = cricoid ring (newer imaging suggests the glottis may be as narrow).", "srcItem": "Birth transition and infant vs adult airway differences"},
    {"id": "q-f202-s12-010", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why can 1 mm of airway edema be dangerous in an infant?", "choices": ["It can reduce the airway diameter by more than 50%", "It only affects the nose", "Infant airways are larger than adult airways", "It increases the airway diameter"], "correct": 0, "explanation": "1 mm of circumferential edema can reduce an infant's airway diameter by > 50% (croup, epiglottitis).", "srcItem": "Birth transition and infant vs adult airway differences"},
    {"id": "q-f202-s12-011", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How much transpulmonary pressure may the newborn's first breath require?", "choices": ["About 40–80 cm H₂O", "About 2–4 cm H₂O", "About 10 cm H₂O", "Over 200 cm H₂O"], "correct": 0, "explanation": "The first breath needs about 40–80 cm H₂O and ~40 mL to overcome surface tension and fluid.", "srcItem": "Birth transition and infant vs adult airway differences"},
    {"id": "q-f202-s12-012", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the main job of the nose and nasal cavity?", "choices": ["Filter, warm and humidify inspired air", "Exchange O₂ and CO₂", "Produce surfactant", "Produce sound"], "correct": 0, "explanation": "The nasal cavity, lined by respiratory mucosa with turbinates, filters, warms and humidifies air.", "srcItem": "Upper respiratory tract"},
    {"id": "q-f202-s12-013", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which region of the pharynx carries air only?", "choices": ["Nasopharynx", "Oropharynx", "Laryngopharynx", "Esophagus"], "correct": 0, "explanation": "The nasopharynx carries air only; below it the pharynx carries both air and food.", "srcItem": "Upper respiratory tract"},
    {"id": "q-f202-s12-014", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What structure covers the opening to the trachea during swallowing?", "choices": ["Epiglottis", "Uvula", "Adenoids", "Turbinates"], "correct": 0, "explanation": "The epiglottis is a flap-like cartilage that covers the tracheal opening during swallowing, preventing aspiration.", "srcItem": "Upper respiratory tract"},
    {"id": "q-f202-s12-015", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Postnasal drip from infected sinuses is a common cause of what?", "choices": ["Chronic cough", "Pneumothorax", "Pulmonary embolism", "Pleural effusion"], "correct": 0, "explanation": "Postnasal drip irritates the larynx and is a common cause of chronic cough.", "srcItem": "Upper respiratory tract"},
    {"id": "q-f202-s12-016", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the only complete ring of cartilage around the airway?", "choices": ["Cricoid cartilage", "Thyroid cartilage", "Epiglottis", "Tracheal C-rings"], "correct": 0, "explanation": "The cricoid cartilage, below the thyroid cartilage, is the only complete ring.", "srcItem": "Larynx and glottis"},
    {"id": "q-f202-s12-017", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Where is an emergency cricothyrotomy made?", "choices": ["Through the cricothyroid membrane", "Through the thyroid cartilage", "Through the epiglottis", "Below the 6th tracheal ring"], "correct": 0, "explanation": "The cricothyroid membrane lies between the thyroid and cricoid cartilages.", "srcItem": "Larynx and glottis"},
    {"id": "q-f202-s12-018", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the glottis?", "choices": ["The opening between the vocal cords", "The flap over the larynx", "The largest laryngeal cartilage", "The lower border of the trachea"], "correct": 0, "explanation": "The glottis is the triangular opening between the vocal cords; it separates the upper and lower airways.", "srcItem": "Larynx and glottis"},
    {"id": "q-f202-s12-019", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which is the largest laryngeal cartilage, prominent in men as the Adam's apple?", "choices": ["Thyroid cartilage", "Cricoid cartilage", "Arytenoid cartilage", "Corniculate cartilage"], "correct": 0, "explanation": "The thyroid cartilage is the largest laryngeal cartilage.", "srcItem": "Larynx and glottis"},
    {"id": "q-f202-s12-020", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How long is the adult trachea?", "choices": ["10 to 13 cm", "2 to 3 cm", "25 to 30 cm", "5 to 6 mm"], "correct": 0, "explanation": "Hess: 10–13 cm long, 16–20 C-shaped cartilages, diameter ~2.0–2.5 cm.", "srcItem": "Trachea, carina and the main stem bronchi"},
    {"id": "q-f202-s12-021", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why are foreign bodies more often aspirated into the right main stem bronchus?", "choices": ["It branches at a smaller angle (20–30°) from vertical", "It is narrower than the left", "It is longer than the left", "It has no cartilage"], "correct": 0, "explanation": "Right main stem: 20–30° from vertical; left: 45–55°.", "srcItem": "Trachea, carina and the main stem bronchi"},
    {"id": "q-f202-s12-022", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "If an ETT is advanced too deep, where does it usually go?", "choices": ["Into the right mainstem bronchus", "Into the left mainstem bronchus", "Into the esophagus", "Into the pleural space"], "correct": 0, "explanation": "RCP 203: too deep usually enters the right mainstem; the tip should sit 4–6 cm above the carina.", "srcItem": "Trachea, carina and the main stem bronchi"},
    {"id": "q-f202-s12-023", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What lines the trachea and most of the tracheobronchial tree?", "choices": ["Pseudostratified ciliated columnar epithelium", "Stratified squamous epithelium", "Simple squamous epithelium", "Transitional epithelium"], "correct": 0, "explanation": "Pseudostratified ciliated columnar epithelium; smoking destroys the cilia.", "srcItem": "Trachea, carina and the main stem bronchi"},
    {"id": "q-f202-s12-024", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which structures make up the respiratory zone (acinus)?", "choices": ["Respiratory bronchioles, alveolar ducts, alveolar sacs and alveoli", "Trachea and main bronchi", "Lobar and segmental bronchi", "Terminal bronchioles only"], "correct": 0, "explanation": "The acinus/respiratory zone does gas exchange; the conducting zone (to the terminal bronchioles) only moves air.", "srcItem": "Bronchial tree branching, generations, and the conducting vs respirato"},
    {"id": "q-f202-s12-025", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the last component of the conducting zone?", "choices": ["Terminal bronchiole", "Respiratory bronchiole", "Alveolar duct", "Segmental bronchus"], "correct": 0, "explanation": "Terminal bronchioles (~0.65 mm, 30,000–40,000 of them) are the last conducting airway.", "srcItem": "Bronchial tree branching, generations, and the conducting vs respirato"},
    {"id": "q-f202-s12-026", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How do bronchioles stay open, since they contain no cartilage?", "choices": ["The elastic retractile forces of the lung parenchyma", "C-shaped cartilage rings", "Smooth muscle contraction", "Surfactant alone"], "correct": 0, "explanation": "Bronchioles (< 1 mm, no cartilage) stay open through the lung's elastic recoil forces.", "srcItem": "Bronchial tree branching, generations, and the conducting vs respirato"},
    {"id": "q-f202-s12-027", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Using the deck's rule of 1 mL per pound, what is the anatomic dead space of a 180-lb patient?", "choices": ["About 180 mL", "About 18 mL", "About 360 mL", "About 1,800 mL"], "correct": 0, "explanation": "Anatomic dead space ≈ 1 mL/lb of body weight → 180 mL.", "srcItem": "Bronchial tree branching, generations, and the conducting vs respirato"},
    {"id": "q-f202-s12-028", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How many lobes and segments do the lungs have in total?", "choices": ["5 lobes and 18 segments", "4 lobes and 20 segments", "6 lobes and 12 segments", "2 lobes and 10 segments"], "correct": 0, "explanation": "Right lung 3 lobes (10 segments); left lung 2 lobes (8 segments).", "srcItem": "The lungs"},
    {"id": "q-f202-s12-029", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which fissure separates the right upper and right middle lobes?", "choices": ["Horizontal fissure", "Oblique fissure", "Left oblique fissure", "Cardiac notch"], "correct": 0, "explanation": "Right: horizontal fissure (upper/middle) and oblique fissure (middle/lower). Left: one oblique fissure.", "srcItem": "The lungs"},
    {"id": "q-f202-s12-030", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why is the right lung larger and heavier than the left?", "choices": ["The left shares its hemithorax with the heart", "The right has more cartilage", "The right has fewer alveoli", "The left has no hilum"], "correct": 0, "explanation": "The left lung shares space with the heart, so the right lung is larger.", "srcItem": "The lungs"},
    {"id": "q-f202-s12-031", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which segments make up the right middle lobe?", "choices": ["Lateral and medial", "Apical and posterior", "Superior and inferior lingular", "Anterior basal and posterior basal"], "correct": 0, "explanation": "RML: lateral and medial segments; the lingula (superior/inferior) is in the left upper lobe.", "srcItem": "The lungs"},
    {"id": "q-f202-s12-032", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which alveolar cell covers about 90–95% of the alveolar surface and is the main site of gas exchange?", "choices": ["Type I (squamous) pneumocyte", "Type II (granular) pneumocyte", "Alveolar macrophage", "Goblet cell"], "correct": 0, "explanation": "Type I cells are flat, cover 90–95% of the surface, and are very sensitive to injury.", "srcItem": "Alveoli, the alveolar-capillary membrane, and alveolar cell types"},
    {"id": "q-f202-s12-033", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the primary role of the type II pneumocyte?", "choices": ["Producing surfactant", "Gas exchange only", "Phagocytosis of bacteria", "Producing mucus"], "correct": 0, "explanation": "Type II cells produce surfactant and can differentiate into type I cells after injury.", "srcItem": "Alveoli, the alveolar-capillary membrane, and alveolar cell types"},
    {"id": "q-f202-s12-034", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the main surface-tension-lowering component of surfactant?", "choices": ["Dipalmitoyl phosphatidylcholine (DPPC)", "Albumin", "Mucin", "Elastin"], "correct": 0, "explanation": "Surfactant is 90% phospholipid and 10% protein; DPPC is the main surface-tension-lowering agent.", "srcItem": "Alveoli, the alveolar-capillary membrane, and alveolar cell types"},
    {"id": "q-f202-s12-035", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What allows collateral ventilation between adjacent alveoli?", "choices": ["Pores of Kohn and channels of Lambert", "Ciliated mesothelium", "Tight junctions", "The hilum"], "correct": 0, "explanation": "Adjacent alveoli communicate through the pores of Kohn; channels of Lambert connect alveoli and terminal bronchioles.", "srcItem": "Alveoli, the alveolar-capillary membrane, and alveolar cell types"},
    {"id": "q-f202-s12-036", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What happens without surfactant?", "choices": ["Alveoli collapse (atelectasis)", "Alveoli overinflate", "Gas exchange improves", "Mucus clearance stops"], "correct": 0, "explanation": "Surfactant lowers surface tension at end-expiration; its absence → atelectasis (e.g. neonatal RDS).", "srcItem": "Alveoli, the alveolar-capillary membrane, and alveolar cell types"},
    {"id": "q-f202-s12-037", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Where is the interstitium located?", "choices": ["Between the alveolar epithelium and the vascular endothelium", "Between the two pleural layers", "Inside the bronchial lumen", "In the mediastinum only"], "correct": 0, "explanation": "Key Point: the interstitial space lies between the alveolar epithelia and the vascular endothelia.", "srcItem": "Interstitium and pulmonary lymphatics"},
    {"id": "q-f202-s12-038", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What happens to the interstitium in interstitial lung disease?", "choices": ["It thickens and holds more cells, reducing diffusion", "It thins and disappears", "It fills with air", "It becomes the pleural space"], "correct": 0, "explanation": "ILD = more cells and a thicker interstitium → reduced diffusing capacity and hypoxemia.", "srcItem": "Interstitium and pulmonary lymphatics"},
    {"id": "q-f202-s12-039", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What do the pulmonary lymphatics mainly remove?", "choices": ["Excess fluid and protein leaking from capillaries", "Surfactant", "Oxygen", "Carbon dioxide"], "correct": 0, "explanation": "Lymphatics beneath the visceral pleura remove excess fluid, protein, bacteria and foreign products.", "srcItem": "Interstitium and pulmonary lymphatics"},
    {"id": "q-f202-s12-040", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which pleura is pain-sensitive?", "choices": ["Parietal pleura, innervated by intercostal and phrenic nerves", "Visceral pleura, innervated by the vagus", "Both equally", "Neither"], "correct": 0, "explanation": "Visceral pleura (vagus) has no pain sensation; parietal pleura is extremely sensitive.", "srcItem": "Pleurae, pleural space and mediastinum"},
    {"id": "q-f202-s12-041", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How much fluid normally lies in the pleural space?", "choices": ["Less than 20 mL, with low protein", "About 700 mL", "About 1–2 L", "None at all"], "correct": 0, "explanation": "< 20 mL of thin, low-protein fluid; the pleural lymphatics can handle about 700 mL/day.", "srcItem": "Pleurae, pleural space and mediastinum"},
    {"id": "q-f202-s12-042", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why is pleural pressure normally negative?", "choices": ["The lungs tend to collapse while the chest wall tends to expand", "The diaphragm pushes up constantly", "Air leaks into the pleural space", "The heart pulls the lungs inward"], "correct": 0, "explanation": "Opposing recoil of lungs and chest wall keeps pleural pressure below atmospheric.", "srcItem": "Pleurae, pleural space and mediastinum"},
    {"id": "q-f202-s12-043", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the mediastinum?", "choices": ["The area between the two pleural sacs holding everything in the thorax except the lungs and pleurae", "The space between the visceral and parietal pleura", "The lower lobe of the left lung", "The diaphragm's central tendon"], "correct": 0, "explanation": "The mediastinum contains the heart, great vessels, trachea, esophagus, thymus and nerves.", "srcItem": "Pleurae, pleural space and mediastinum"},
    {"id": "q-f202-s12-044", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which bones make up the bony thorax?", "choices": ["Sternum, ribs, thoracic vertebrae, clavicles and scapulae", "Skull, mandible and hyoid", "Pelvis and femur", "Lumbar vertebrae and sacrum"], "correct": 0, "explanation": "Key Point: sternum, ribs, thoracic vertebrae, clavicles and scapulae.", "srcItem": "Bony thorax and chest-wall mechanics"},
    {"id": "q-f202-s12-045", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What causes a 'barrel chest' in COPD?", "choices": ["Air trapping increases the AP diameter", "Rib fractures", "Loss of the diaphragm", "A narrowed trachea"], "correct": 0, "explanation": "Normally AP diameter is about half the chest width; air trapping in obstructive disease increases it.", "srcItem": "Bony thorax and chest-wall mechanics"},
    {"id": "q-f202-s12-046", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which three parts make up the sternum?", "choices": ["Manubrium, body and xiphoid process", "Clavicle, scapula and humerus", "Atlas, axis and body", "Cricoid, thyroid and hyoid"], "correct": 0, "explanation": "The manubrium connects to ribs 1–2, the body to ribs 3–7, and the xiphoid is the tip.", "srcItem": "Bony thorax and chest-wall mechanics"},
    {"id": "q-f202-s12-047", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which nerve supplies the diaphragm, and from which levels?", "choices": ["Phrenic nerve, C3–C5", "Vagus nerve, T1–T4", "Intercostal nerves, T6–T12", "Hypoglossal nerve, C1"], "correct": 0, "explanation": "The phrenic nerve exits at C3–C5; injury at or above this level → diaphragmatic paralysis.", "srcItem": "Muscles of ventilation"},
    {"id": "q-f202-s12-048", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What happens to the diaphragm during inspiration?", "choices": ["It contracts and flattens, lowering intrathoracic pressure", "It relaxes and rises", "It stays still", "It pushes the lungs upward"], "correct": 0, "explanation": "The diaphragm contracts and flattens; exhalation is elastic recoil plus diaphragm relaxation.", "srcItem": "Muscles of ventilation"},
    {"id": "q-f202-s12-049", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which is an accessory muscle of EXPIRATION?", "choices": ["Rectus abdominis", "Sternocleidomastoid", "Scalene", "External intercostal"], "correct": 0, "explanation": "Expiratory accessories: internal intercostals and abdominal muscles; inspiratory: scalene, SCM, pectoralis major, trapezius, external intercostals.", "srcItem": "Muscles of ventilation"},
    {"id": "q-f202-s12-050", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How far does the diaphragm move in normal tidal breathing?", "choices": ["About 1.5 cm", "About 10 cm", "About 0.1 mm", "About 20 cm"], "correct": 0, "explanation": "≈ 1.5 cm at rest; up to 6–10 cm with high work of breathing.", "srcItem": "Muscles of ventilation"},
    {"id": "q-f202-s12-051", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which nerve innervates the visceral pleura?", "choices": ["Vagus nerve", "Phrenic nerve", "Intercostal nerves", "Olfactory nerve"], "correct": 0, "explanation": "Visceral pleura: vagus (no pain); parietal pleura: intercostal and phrenic nerves.", "srcItem": "Innervation of the respiratory system (summary)"},
    {"id": "q-f202-s12-052", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What control are the airway submucosal glands under, increasing mucus with cholinergic stimulation?", "choices": ["Parasympathetic", "Sympathetic only", "Somatic", "None — they are not controlled"], "correct": 0, "explanation": "Submucosal glands are under parasympathetic control; surface goblet cells do not seem directly innervated.", "srcItem": "Innervation of the respiratory system (summary)"},
    {"id": "q-f202-s12-053", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the primary defense of the conducting airways?", "choices": ["The pseudostratified ciliated columnar epithelium (mucus escalator)", "The alveolar macrophage only", "Type I pneumocytes", "The pleura"], "correct": 0, "explanation": "The ciliated epithelium works as a mucus escalator; goblet cells secrete mucus that catches debris.", "srcItem": "Mucociliary apparatus (mucociliary clearance)"},
    {"id": "q-f202-s12-054", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Per the RCP 104 deck, what is the ratio of ciliated cells to goblet cells?", "choices": ["About 5:1", "About 1:5", "About 1:1", "About 50:1"], "correct": 0, "explanation": "Use the deck's 5:1 (Hess says about 4:1).", "srcItem": "Mucociliary apparatus (mucociliary clearance)"},
    {"id": "q-f202-s12-055", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which drug impairs mucociliary transport?", "choices": ["Atropine", "Albuterol", "Normal saline", "Oxygen at 2 L/min"], "correct": 0, "explanation": "Impair transport: smoking, CF, COPD, asthma, narcotics, alcohol, atropine, aspirin, β-blockers, anesthetics.", "srcItem": "Mucociliary apparatus (mucociliary clearance)"},
    {"id": "q-f202-s12-056", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In which mucus layer do the cilia beat?", "choices": ["The watery sol (periciliary) layer", "The thick gel layer", "The surfactant layer only", "The basement membrane"], "correct": 0, "explanation": "Cilia beat in the watery sol layer; the mucous gel layer sits on top and is propelled toward the larynx.", "srcItem": "Mucociliary apparatus (mucociliary clearance)"},
    {"id": "q-f202-s12-057", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does hypoxia do to the pulmonary vasculature?", "choices": ["Causes vasoconstriction to match ventilation and perfusion", "Causes vasodilation", "Has no effect", "Causes the vessels to rupture"], "correct": 0, "explanation": "Hypercapnia, low pH and especially hypoxia cause pulmonary vasoconstriction, matching V and Q.", "srcItem": "Airway and vascular smooth muscle; the pulmonary circulation's tone"},
    {"id": "q-f202-s12-058", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does pulmonary vascular resistance compare with systemic resistance?", "choices": ["Lower, with less smooth muscle", "Higher, with more smooth muscle", "Exactly equal", "Pulmonary vessels have no resistance"], "correct": 0, "explanation": "The pulmonary vasculature has less smooth muscle; its tone, pressure and resistance are low.", "srcItem": "Airway and vascular smooth muscle; the pulmonary circulation's tone"},
    {"id": "q-f202-s12-059", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What are the three functions of the alveolar macrophage?", "choices": ["Phagocytosis, antigen presentation and cytokine production", "Surfactant production, gas exchange and mucus secretion", "Clotting, filtering and buffering", "Vasoconstriction, bronchodilation and cough"], "correct": 0, "explanation": "Macrophages (\"type III cells\"): phagocytosis, antigen presentation, cytokines (IL-1, TNF).", "srcItem": "Mast cells, macrophages and dendritic cells"},
    {"id": "q-f202-s12-060", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which cell releases histamine and leukotrienes and is elevated in asthma?", "choices": ["Mast cell", "Dendritic cell", "Type I pneumocyte", "Goblet cell"], "correct": 0, "explanation": "Mast cells release granule mediators (histamine), lipid mediators (leukotrienes) and cytokines.", "srcItem": "Mast cells, macrophages and dendritic cells"},
    {"id": "q-f202-s12-061", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the main role of the dendritic cell?", "choices": ["Antigen presentation to T lymphocytes", "Surfactant production", "Mucus secretion", "Gas exchange"], "correct": 0, "explanation": "Dendritic cells take up antigen, migrate to lymph nodes, and present it to T cells; steroids reduce them.", "srcItem": "Mast cells, macrophages and dendritic cells"},
    {"id": "q-f202-s12-062", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "According to the Key Points, the alveolus is composed of which cells?", "choices": ["Type I and type II cells", "Goblet and ciliated cells", "Mast cells only", "Mesothelial cells"], "correct": 0, "explanation": "Key Point: the alveolus is composed of type I and type II cells.", "srcItem": "Hess Ch 49 Key Points (reproduced;"},
    {"id": "q-f202-s12-063", "topic": "f202-s12", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "According to the Key Points, what are the respiratory muscles?", "choices": ["The diaphragm, accessory muscles of inspiration and accessory muscles of expiration", "The heart and diaphragm", "Only the intercostals", "The tongue and pharynx"], "correct": 0, "explanation": "Key Point: the diaphragm and the accessory muscles of inspiration and expiration.", "srcItem": "Hess Ch 49 Key Points (reproduced;"},
    {"id": "q-f202-s13-001", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Where should a pulse be checked in an unresponsive adult?", "choices": ["Carotid artery", "Brachial artery", "Radial artery", "Dorsalis pedis artery"], "correct": 0, "explanation": "Adult: carotid on the near side, no more than 10 seconds; infant: brachial.", "srcItem": "Check pulses where"},
    {"id": "q-f202-s13-002", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Where should the pulse be checked in an infant?", "choices": ["Brachial artery", "Carotid artery", "Radial artery", "Temporal artery"], "correct": 0, "explanation": "Infant: brachial artery — the short neck makes the carotid hard to palpate.", "srcItem": "Check pulses where"},
    {"id": "q-f202-s13-003", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A child has a pulse of 50/min with poor perfusion despite oxygenation and ventilation. What should be done?", "choices": ["Start chest compressions", "Continue rescue breathing only", "Give atropine and wait", "Check the pulse again in 5 minutes"], "correct": 0, "explanation": "Start CPR in a child or infant when the pulse is < 60/min with poor perfusion.", "srcItem": "Check pulses where"},
    {"id": "q-f202-s13-004", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How long should a pulse check take during BLS?", "choices": ["No more than 10 seconds", "At least 30 seconds", "At least 1 minute", "As long as needed to be certain"], "correct": 0, "explanation": "Check breathing and pulse simultaneously for no more than 10 seconds; if unsure, start compressions.", "srcItem": "Check pulses where"},
    {"id": "q-f202-s13-005", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "According to Hess, what is the most important determinant of survival after cardiopulmonary arrest?", "choices": ["A trained rescuer ready, willing and able to do BLS", "The patient's age", "The brand of defibrillator", "The drugs given"], "correct": 0, "explanation": "Hess: the presence of a trained rescuer who is ready, willing and able to do basic life support.", "srcItem": "What ensures the best chance of survival"},
    {"id": "q-f202-s13-006", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How much does survival fall for each minute of untreated VF?", "choices": ["7–10%", "1%", "30–40%", "50%"], "correct": 0, "explanation": "Survival decreases 7–10% per minute without defibrillation (only 3–4% per minute with CPR).", "srcItem": "What ensures the best chance of survival"},
    {"id": "q-f202-s13-007", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "When are hospital discharge rates highest after arrest?", "choices": ["CPR within 4 minutes and ALS within 8 minutes", "CPR within 15 minutes and ALS within 30 minutes", "ALS first, then CPR", "Defibrillation after 10 minutes of CPR"], "correct": 0, "explanation": "Highest discharge rates: CPR started within 4 minutes and ALS within 8 minutes.", "srcItem": "What ensures the best chance of survival"},
    {"id": "q-f202-s13-008", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the most important treatment for VF and pulseless VT?", "choices": ["Early defibrillation", "Epinephrine", "Amiodarone", "Sodium bicarbonate"], "correct": 0, "explanation": "Rapid defibrillation is the cornerstone; \"drugs don't fix dead — CPR and shock do.\"", "srcItem": "What ensures the best chance of survival"},
    {"id": "q-f202-s13-009", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which airway maneuver is used when a cervical spine injury is suspected?", "choices": ["Jaw thrust", "Head-tilt–chin-lift", "Neck hyperextension", "Sniffing position with head tilt"], "correct": 0, "explanation": "NBRC pearl: suspected C-spine injury → jaw thrust, which opens the airway without extending the neck.", "srcItem": "Head-tilt–chin-lift vs jaw-thrust maneuver"},
    {"id": "q-f202-s13-010", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the most common cause of airway obstruction in an unconscious person?", "choices": ["Posterior displacement of the tongue", "Vomitus", "Foreign body", "Laryngospasm"], "correct": 0, "explanation": "Hess: the tongue falls back against the posterior pharynx; moving the jaw forward lifts it.", "srcItem": "Head-tilt–chin-lift vs jaw-thrust maneuver"},
    {"id": "q-f202-s13-011", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "When opening an infant's airway, what should be avoided?", "choices": ["Tilting the head back beyond the neutral or sniffing position", "Lifting the chin", "Looking in the mouth", "Using a properly sized mask"], "correct": 0, "explanation": "Overextending an infant's head may block the airway; improper opening is the most common cause of inadequate infant ventilation.", "srcItem": "Head-tilt–chin-lift vs jaw-thrust maneuver"},
    {"id": "q-f202-s13-012", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Should a blind finger sweep be done to clear the airway?", "choices": ["No — only remove visible objects", "Yes, always", "Only in infants", "Only after the first breath fails"], "correct": 0, "explanation": "Remove visible objects with a finger sweep or suction; never perform a blind finger sweep.", "srcItem": "Head-tilt–chin-lift vs jaw-thrust maneuver"},
    {"id": "q-f202-s13-013", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does the MOANS mnemonic predict?", "choices": ["Difficult bag-mask ventilation", "Difficult intubation", "Difficult extubation", "Risk of aspiration"], "correct": 0, "explanation": "MOANS → difficulty with mask ventilation; Mallampati and LEMON → difficulty with intubation.", "srcItem": "MOANS"},
    {"id": "q-f202-s13-014", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In MOANS, what does the 'N' stand for, and why does it matter?", "choices": ["No teeth — the cheeks collapse and the mask seal is poor", "Neck injury — the head can't be tilted", "Nasal obstruction — air can't enter", "Neonate — the mask is too large"], "correct": 0, "explanation": "No teeth makes a tight mask seal hard; keeping dentures in and placing an OPA helps.", "srcItem": "MOANS"},
    {"id": "q-f202-s13-015", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In MOANS, what does the 'S' (deck) stand for?", "choices": ["Stiff lungs needing higher pressures", "Short neck", "Sedation", "Sinus disease"], "correct": 0, "explanation": "Stiff lungs (ARDS, pulmonary edema, severe bronchospasm) need higher pressures for adequate VT.", "srcItem": "MOANS"},
    {"id": "q-f202-s13-016", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does Hess define difficult mask ventilation?", "choices": ["Unable to keep SpO₂ > 90% with 100% O₂ and positive-pressure ventilation", "Unable to see the vocal cords", "Needing more than one person", "Any mask leak"], "correct": 0, "explanation": "Difficult mask ventilation = inability to maintain SpO₂ > 90% with 100% O₂ and PPV.", "srcItem": "MOANS"},
    {"id": "q-f202-s13-017", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Since 2015, how many chains of survival are there?", "choices": ["Two — in-hospital and out-of-hospital", "One universal chain", "Three — adult, child and infant", "Five, one per link"], "correct": 0, "explanation": "The 2015 Guidelines replaced the single chain with in-hospital (IHCA) and out-of-hospital (OHCA) chains.", "srcItem": "Chain of survival"},
    {"id": "q-f202-s13-018", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the first link of the in-hospital chain of survival?", "choices": ["Surveillance and prevention", "Rapid defibrillation", "Immediate CPR", "Post-arrest care"], "correct": 0, "explanation": "IHCA links: surveillance and prevention, recognition/activation, high-quality CPR, rapid defibrillation, ALS/post-arrest care.", "srcItem": "Chain of survival"},
    {"id": "q-f202-s13-019", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What compression rate defines high-quality CPR?", "choices": ["100–120/min", "60–80/min", "140–160/min", "At least 150/min"], "correct": 0, "explanation": "Rate 100–120/min, adequate depth, complete recoil, minimal interruptions, no excessive ventilation.", "srcItem": "Chain of survival"},
    {"id": "q-f202-s13-020", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In 2010, the CPR sequence changed from ABCD to what?", "choices": ["CABD — circulation first", "DABC — defibrillation first", "BACD — breathing first", "It did not change"], "correct": 0, "explanation": "Compressions come first because early in VF arrest compressions matter more than airway and ventilation.", "srcItem": "C-A-B (CABD) sequence and how it evolved"},
    {"id": "q-f202-s13-021", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What do untrained lay rescuers perform?", "choices": ["Hands-only (compression-only) CPR", "Full CPR with rescue breaths at 15:2", "Rescue breathing only", "Defibrillation only"], "correct": 0, "explanation": "Untrained rescuers do hands-only CPR; healthcare providers add breaths, AED and teamwork.", "srcItem": "C-A-B (CABD) sequence and how it evolved"},
    {"id": "q-f202-s13-022", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How should advanced airway placement be confirmed during ACLS?", "choices": ["Physical exam plus qualitative or quantitative ETCO₂", "Chest radiograph only", "Listening to the stomach only", "Patient report"], "correct": 0, "explanation": "Box 18-2: confirm tube placement with two methods — physical exam plus ETCO₂.", "srcItem": "C-A-B (CABD) sequence and how it evolved"},
    {"id": "q-f202-s13-023", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How deep should adult chest compressions be?", "choices": ["At least 2 inches (5 cm)", "About 1 inch", "At least 4 inches", "One-tenth of the chest diameter"], "correct": 0, "explanation": "Adults ≥ 2 in (5 cm); children and infants one-third of the AP diameter (≈ 2 in and ≈ 1½ in).", "srcItem": "High-quality chest compressions"},
    {"id": "q-f202-s13-024", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How often should the compressor rotate?", "choices": ["Every 2 minutes or sooner if fatigued", "Every 30 seconds", "Every 10 minutes", "Never during a code"], "correct": 0, "explanation": "Rotate every 2 minutes; keep interruptions < 10 seconds.", "srcItem": "High-quality chest compressions"},
    {"id": "q-f202-s13-025", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What compression technique is used for an infant?", "choices": ["Two fingertips or the two-thumb encircling technique", "Heel of both hands", "Heel of one hand only", "Fist on the sternum"], "correct": 0, "explanation": "Infant: two fingertips between the nipple line, or the two-thumb technique.", "srcItem": "High-quality chest compressions"},
    {"id": "q-f202-s13-026", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Compressing over the xiphoid process can cause what complication?", "choices": ["Liver laceration with severe bleeding", "Pneumothorax only", "Tracheal injury", "Skull fracture"], "correct": 0, "explanation": "Pressure on the xiphoid can lacerate the liver; off-midline hands cause rib fractures.", "srcItem": "High-quality chest compressions"},
    {"id": "q-f202-s13-027", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What compression-to-ventilation ratio do two rescuers use for a child?", "choices": ["15:2", "30:2", "5:1", "30:1"], "correct": 0, "explanation": "Child and infant: 30:2 with one rescuer, 15:2 with two rescuers.", "srcItem": "Compression-to-ventilation ratios"},
    {"id": "q-f202-s13-028", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What ratio does a single rescuer use for an adult?", "choices": ["30:2", "15:2", "5:1", "3:1"], "correct": 0, "explanation": "Adults 30:2 with one or two rescuers (five cycles ≈ 2 minutes).", "srcItem": "Compression-to-ventilation ratios"},
    {"id": "q-f202-s13-029", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "An adult has a pulse but is not breathing normally. How often should rescue breaths be given?", "choices": ["1 breath every 5–6 seconds", "1 breath every 3 seconds", "1 breath every 15 seconds", "2 breaths every minute"], "correct": 0, "explanation": "Adult rescue breathing: 1 breath every 5–6 s (10–12/min); child: 1 every 3 s.", "srcItem": "Compression-to-ventilation ratios"},
    {"id": "q-f202-s13-030", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "With an advanced airway in place during adult CPR, how are breaths given?", "choices": ["1 breath every 6 seconds with continuous compressions", "2 breaths after every 30 compressions with a pause", "1 breath every 2 seconds", "No breaths are needed"], "correct": 0, "explanation": "Advanced airway: 1 breath every 6 s (10/min) without pausing compressions.", "srcItem": "Compression-to-ventilation ratios"},
    {"id": "q-f202-s13-031", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What tidal volume is sufficient for rescue breaths?", "choices": ["6–7 mL/kg, just enough for visible chest rise", "12–15 mL/kg", "2–3 mL/kg", "As much as the bag can deliver"], "correct": 0, "explanation": "Give 1-second breaths of 6–7 mL/kg (≈ 500–600 mL), enough for visible chest rise.", "srcItem": "Ventilation during CPR"},
    {"id": "q-f202-s13-032", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why is excessive ventilation during CPR harmful?", "choices": ["It causes gastric inflation and reduces blood flow to vital organs", "It raises the blood pressure too much", "It improves coronary perfusion too quickly", "It prevents defibrillation"], "correct": 0, "explanation": "Over-ventilation causes gastric inflation, vomiting, aspiration and lower vital-organ flow.", "srcItem": "Ventilation during CPR"},
    {"id": "q-f202-s13-033", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "While bagging a COPD patient during CPR, hypotension develops. What should be done?", "choices": ["Pause ventilation for 20–30 seconds; if BP returns, resume at 6–8 breaths/min", "Increase the rate to 30/min", "Give larger tidal volumes", "Stop CPR entirely"], "correct": 0, "explanation": "Hypotension during bagging suggests air trapping; pause, then ventilate more slowly.", "srcItem": "Ventilation during CPR"},
    {"id": "q-f202-s13-034", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Is cricoid pressure (Sellick maneuver) routinely recommended during CPR?", "choices": ["No", "Yes, always", "Only for children", "Only with an LMA"], "correct": 0, "explanation": "Cricoid pressure is no longer recommended routinely.", "srcItem": "Ventilation during CPR"},
    {"id": "q-f202-s13-035", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What O₂ flow does Hess give for a bag-valve-mask?", "choices": ["10–12 L/min", "2 L/min", "4 L/min", "1 L/min"], "correct": 0, "explanation": "Hess: 10–12 L/min; the deck says set to the maximum the manufacturer allows, but never delay ventilation.", "srcItem": "Bag-valve-mask (manual resuscitator) technique"},
    {"id": "q-f202-s13-036", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why is two-person bag-mask ventilation preferred?", "choices": ["It improves tidal volume — one holds the mask, one squeezes the bag", "It uses less oxygen", "It avoids the need for a mask seal", "It eliminates gastric inflation completely"], "correct": 0, "explanation": "One-person BVM may not give adequate VT; two-person ventilation improves it.", "srcItem": "Bag-valve-mask (manual resuscitator) technique"},
    {"id": "q-f202-s13-037", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the EC grip?", "choices": ["Thumb and index finger form a 'C' on the mask, the other fingers form an 'E' along the mandible", "Both hands squeeze the bag", "The palm covers the patient's mouth", "Fingers press the cricoid"], "correct": 0, "explanation": "EC grip: C on the mask, E along the mandible.", "srcItem": "Bag-valve-mask (manual resuscitator) technique"},
    {"id": "q-f202-s13-038", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "During a BVM check, the patient connector is occluded and the bag is squeezed. What should happen?", "choices": ["The pop-off opens, or the bag cannot be compressed", "The bag empties freely", "The reservoir inflates", "The O₂ flow stops"], "correct": 0, "explanation": "If the bag compresses easily with the outlet blocked, a valve is missing or leaking.", "srcItem": "Bag-valve-mask (manual resuscitator) technique"},
    {"id": "q-f202-s13-039", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which rhythms are shockable?", "choices": ["Ventricular fibrillation and pulseless ventricular tachycardia", "Asystole and PEA", "Sinus bradycardia", "Atrial fibrillation with a pulse only"], "correct": 0, "explanation": "Shockable: VF and pVT. Asystole and PEA are pulseless but non-shockable.", "srcItem": "AED and defibrillation"},
    {"id": "q-f202-s13-040", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does the AED mnemonic P-A-I-D stand for?", "choices": ["Power on, Attach leads, Interpret, Defibrillate", "Pulse, Airway, Intubate, Drugs", "Position, Assess, Inspect, Deliver", "Pads, Analyze, Inflate, Drain"], "correct": 0, "explanation": "Power on, attach pads, analyze with no one touching, then clear and defibrillate.", "srcItem": "AED and defibrillation"},
    {"id": "q-f202-s13-041", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What should rescuers do immediately after an AED delivers a shock?", "choices": ["Resume compressions for about 2 minutes", "Check the pulse for 1 minute", "Wait for the AED to reanalyze", "Give 2 breaths and stop"], "correct": 0, "explanation": "Give 1 shock, then immediately resume CPR for about 2 minutes before reanalysis.", "srcItem": "AED and defibrillation"},
    {"id": "q-f202-s13-042", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "For a child under 8 years, which AED pads and dose should be used?", "choices": ["Child pads and the child dose; adult pads if child pads are unavailable", "Adult pads always", "No AED for children under 8", "Only manual defibrillation"], "correct": 0, "explanation": "< 8 years: child pads/child dose; adult pads may be used if child pads are unavailable (not overlapping).", "srcItem": "AED and defibrillation"},
    {"id": "q-f202-s13-043", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the IV/IO epinephrine dose during cardiac arrest?", "choices": ["1 mg every 3–5 minutes", "10 mg once", "0.1 mg every 30 minutes", "300 mg once"], "correct": 0, "explanation": "Epinephrine 1 mg IV/IO (10 mL of 1:10,000) every 3–5 minutes.", "srcItem": "Drugs during CPR"},
    {"id": "q-f202-s13-044", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the first dose of amiodarone for refractory VF/pulseless VT?", "choices": ["300 mg IV/IO", "150 mg IV/IO", "1 mg IV/IO", "40 units IV"], "correct": 0, "explanation": "Amiodarone 300 mg first, then 150 mg.", "srcItem": "Drugs during CPR"},
    {"id": "q-f202-s13-045", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which drugs can be given through the ETT (NAVEL)?", "choices": ["Naloxone, atropine, vasopressin, epinephrine, lidocaine", "Nitroglycerin, amiodarone, verapamil, enalapril, labetalol", "Norepinephrine, adenosine, vecuronium, etomidate, lorazepam", "Sodium bicarbonate and calcium only"], "correct": 0, "explanation": "NAVEL; give 2–2.5× the IV dose diluted in 10 mL; IO is preferred today.", "srcItem": "Drugs during CPR"},
    {"id": "q-f202-s13-046", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "When is magnesium sulfate given during cardiac arrest?", "choices": ["For torsades de pointes or suspected low magnesium", "For every VF arrest", "For asystole", "For hyperkalemia"], "correct": 0, "explanation": "Magnesium 1–2 g only if torsades or suspected hypomagnesemia.", "srcItem": "Drugs during CPR"},
    {"id": "q-f202-s13-047", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the most common IO site?", "choices": ["Proximal tibia", "Sternum", "Radius", "Skull"], "correct": 0, "explanation": "Deck: proximal tibia (also humerus); IO when IV access is too difficult.", "srcItem": "Drugs during CPR"},
    {"id": "q-f202-s13-048", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "During CPR, the PETCO₂ is 8 mm Hg. What does this indicate?", "choices": ["Poor pulmonary blood flow — improve CPR quality", "Return of spontaneous circulation", "Excellent compressions", "Hyperventilation"], "correct": 0, "explanation": "PETCO₂ < 10 mm Hg = poor or absent pulmonary blood flow → improve CPR.", "srcItem": "Capnography"},
    {"id": "q-f202-s13-049", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What PETCO₂ change suggests ROSC?", "choices": ["An abrupt, sustained increase, typically to about 40 mm Hg", "A gradual fall to zero", "A value below 10 mm Hg", "No change"], "correct": 0, "explanation": "An abrupt, sustained rise (often ≥ 40 mm Hg) indicates ROSC.", "srcItem": "Capnography"},
    {"id": "q-f202-s13-050", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "After ROSC, what PETCO₂ target guides ventilation?", "choices": ["35–40 mm Hg", "10–15 mm Hg", "50–60 mm Hg", "Above 70 mm Hg"], "correct": 0, "explanation": "Post-arrest: start at 10 breaths/min and titrate to PETCO₂ 35–40 mm Hg.", "srcItem": "Capnography"},
    {"id": "q-f202-s13-051", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does the impedance threshold valve improve CPR?", "choices": ["It makes intrathoracic pressure more negative during recoil, increasing venous return", "It delivers extra oxygen", "It removes CO₂ directly", "It raises intrathoracic pressure during recoil"], "correct": 0, "explanation": "The ITV limits air entry on recoil, lowering intrathoracic pressure 6–8 mm Hg and raising venous return.", "srcItem": "Advanced airways during CPR, and the impedance threshold valve"},
    {"id": "q-f202-s13-052", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why is early intubation usually not necessary during in-hospital adult CPR?", "choices": ["Intubation in the first 15 minutes is associated with decreased survival", "Intubation is impossible during CPR", "BVM ventilation is always contraindicated", "Compressions must stop for 2 minutes"], "correct": 0, "explanation": "BVM allows uninterrupted compressions; early IHCA intubation is linked to lower survival.", "srcItem": "Advanced airways during CPR, and the impedance threshold valve"},
    {"id": "q-f202-s13-053", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which advanced airway can be used with a possible unstable neck injury and needs no view of the cords?", "choices": ["Laryngeal mask airway", "Endotracheal tube by direct laryngoscopy", "Tracheostomy", "Nasal cannula"], "correct": 0, "explanation": "The LMA is easy to insert without seeing the cords and can be used with possible neck injury.", "srcItem": "Advanced airways during CPR, and the impedance threshold valve"},
    {"id": "q-f202-s13-054", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What SpO₂ target does Hess give after ROSC?", "choices": ["94%", "100%", "85%", "80%"], "correct": 0, "explanation": "Titrate FiO₂ to the minimum needed for SpO₂ 94%; avoid hyperoxia and hyperventilation.", "srcItem": "Post–cardiac arrest care"},
    {"id": "q-f202-s13-055", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "After ROSC, the patient does not follow commands. What should be started?", "choices": ["Targeted temperature management", "Immediate extubation", "Hyperventilation to PaCO₂ 25", "Discharge planning"], "correct": 0, "explanation": "Algorithm 18-8: if the patient does not follow commands after ROSC, initiate TTM.", "srcItem": "Post–cardiac arrest care"},
    {"id": "q-f202-s13-056", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which is one of the 'T's' among the reversible causes of arrest?", "choices": ["Tension pneumothorax", "Tachypnea", "Tracheitis", "Tonsillitis"], "correct": 0, "explanation": "T's: tension pneumothorax, tamponade, toxins, pulmonary thrombosis, coronary thrombosis.", "srcItem": "Post–cardiac arrest care"},
    {"id": "q-f202-s13-057", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "When do most post-resuscitation deaths occur?", "choices": ["In the first 24 hours", "After 1 month", "After 1 year", "In the first 5 minutes only"], "correct": 0, "explanation": "Most post-resuscitation deaths occur in the first 24 hours.", "srcItem": "Post–cardiac arrest care"},
    {"id": "q-f202-s13-058", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "An adult who is choking can't speak and nods when asked. What should be done?", "choices": ["Give abdominal thrusts", "Encourage coughing only", "Give back blows and chest thrusts", "Do a blind finger sweep"], "correct": 0, "explanation": "Severe obstruction in adults/children: abdominal thrusts (chest thrusts if pregnant or obese).", "srcItem": "Choking (foreign body airway obstruction) by age"},
    {"id": "q-f202-s13-059", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How is severe choking relieved in an infant?", "choices": ["5 back blows then 5 chest thrusts, repeated", "Abdominal thrusts", "Blind finger sweep", "Chest compressions only at 30:2"], "correct": 0, "explanation": "Infants: no abdominal thrusts — 5 back blows and 5 chest thrusts.", "srcItem": "Choking (foreign body airway obstruction) by age"},
    {"id": "q-f202-s13-060", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A choking adult becomes unresponsive. What is the next step?", "choices": ["Lower them to the ground, activate EMS and start CPR without a pulse check", "Continue abdominal thrusts while standing", "Wait for EMS without touching them", "Give back blows"], "correct": 0, "explanation": "Start compressions (no pulse check), and look in the mouth each time the airway is opened.", "srcItem": "Choking (foreign body airway obstruction) by age"},
    {"id": "q-f202-s13-061", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Who can start CPR, and who can order it withheld?", "choices": ["Anyone may start CPR without an order; withholding requires a physician's order", "Only a physician may start CPR", "Nurses may order CPR withheld", "Family members decide both"], "correct": 0, "explanation": "CPR is started without an order (implied consent); withholding requires a physician's order.", "srcItem": "Definitions, risk factors, newborns and ethics"},
    {"id": "q-f202-s13-062", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Infants and children usually arrest because of what?", "choices": ["Pulmonary disease or respiratory arrest", "Ventricular fibrillation", "Coronary artery disease", "Hypertension"], "correct": 0, "explanation": "Pediatric arrests are usually secondary to respiratory causes; adult arrests usually follow VF.", "srcItem": "Definitions, risk factors, newborns and ethics"},
    {"id": "q-f202-s13-063", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which is the most important modifiable risk factor for coronary heart disease (Box 18-1)?", "choices": ["Cigarette smoking", "Heredity", "Gender", "Increasing age"], "correct": 0, "explanation": "Smoking is the most important; CHD death rate is 70% greater in smokers.", "srcItem": "Definitions, risk factors, newborns and ethics"},
    {"id": "q-f202-s13-064", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In newborn resuscitation, when are chest compressions started?", "choices": ["HR < 60 despite ventilation", "HR < 100", "HR < 140", "Only if apneic for 10 minutes"], "correct": 0, "explanation": "Algorithm 18-4: PPV if HR < 100, gasping or apnea; compressions if HR < 60 despite ventilation.", "srcItem": "Definitions, risk factors, newborns and ethics"},
    {"id": "q-f202-s13-065", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "The Heuer Ch 15 deck says CPR quality should be improved if the intra-arterial diastolic pressure is below what?", "choices": ["20 mm Hg", "60 mm Hg", "90 mm Hg", "5 mm Hg"], "correct": 0, "explanation": "PetCO₂ < 10 mm Hg and/or arterial diastolic pressure < 20 mm Hg → improve CPR.", "srcItem": "What Heuer Ch 15 adds or words differently"},
    {"id": "q-f202-s13-066", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "With an ETT in place, how often does the Heuer deck give breaths during CPR?", "choices": ["One every 6–8 seconds without pausing compressions", "One every 2 seconds", "Two after every 30 compressions", "One every 20 seconds"], "correct": 0, "explanation": "Heuer: 1 breath every 6–8 s; Hess: every 6 s (10/min).", "srcItem": "What Heuer Ch 15 adds or words differently"},
    {"id": "q-f202-s13-067", "topic": "f202-s13", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which drugs does the Heuer deck list as L-E-A-N for ETT instillation?", "choices": ["Lidocaine, epinephrine, atropine, naloxone", "Labetalol, enalapril, adenosine, nitroglycerin", "Lorazepam, etomidate, amiodarone, norepinephrine", "Lidocaine, esmolol, aminophylline, nifedipine"], "correct": 0, "explanation": "L-E-A-N; some add vasopressin to make N-A-V-E-L.", "srcItem": "What Heuer Ch 15 adds or words differently"},
    {"id": "q-f202-s14-001", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why do the decks say to 'learn how the mode works — not just the name'?", "choices": ["Mode names are not standardized between manufacturers", "Every ventilator uses the same mode names", "Mode names determine the FiO₂", "Only Servo ventilators have modes"], "correct": 0, "explanation": "Names are manufacturer-dependent (e.g. PRVC on Servo = VC+ on PB840 = AutoFlow on Dräger).", "srcItem": "How to Tell Any Two Modes Apart"},
    {"id": "q-f202-s14-002", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "According to the golden rule, how many variables can a ventilator control at once?", "choices": ["Only one — pressure or volume", "Both pressure and volume", "Pressure, volume and flow together", "None — the patient controls all"], "correct": 0, "explanation": "Control volume and pressure varies; control pressure and volume varies.", "srcItem": "How to Tell Any Two Modes Apart"},
    {"id": "q-f202-s14-003", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A breath is triggered by the patient but cycled by the ventilator. How is it classified?", "choices": ["Mandatory", "Spontaneous", "Assisted spontaneous", "Apneic"], "correct": 0, "explanation": "\"If the patient controls both = Spontaneous. If the ventilator controls either one = it's Mandatory.\"", "srcItem": "How to Tell Any Two Modes Apart"},
    {"id": "q-f202-s14-004", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which breath sequence consists of all spontaneous breaths, such as CPAP or PS?", "choices": ["CSV", "CMV", "IMV", "SIMV"], "correct": 0, "explanation": "CMV = all mandatory; IMV = mandatory plus spontaneous; CSV = all spontaneous.", "srcItem": "How to Tell Any Two Modes Apart"},
    {"id": "q-f202-s14-005", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which ventilatory pattern is NOT valid, according to Hess?", "choices": ["VC-CSV", "PC-CSV", "VC-IMV", "PC-CMV"], "correct": 0, "explanation": "Presetting VT implies machine cycling, so volume control can't be continuous spontaneous ventilation.", "srcItem": "How to Tell Any Two Modes Apart"},
    {"id": "q-f202-s14-006", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is an open-loop ventilator?", "choices": ["One that delivers what you set and doesn't adjust, such as VC", "One that adjusts automatically to the patient", "One with no exhalation valve", "One used only for neonates"], "correct": 0, "explanation": "Open-loop delivers what is set (VC); closed-loop watches and adjusts (PSV, MMV, PRVC, PAV, NAVA).", "srcItem": "How to Tell Any Two Modes Apart"},
    {"id": "q-f202-s14-007", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In volume control, a patient develops ARDS. What happens?", "choices": ["VT stays the same and pressure increases", "VT falls and pressure stays the same", "Both VT and pressure fall", "Nothing changes"], "correct": 0, "explanation": "VC guarantees VT; pressure is the dependent variable and rises as compliance falls.", "srcItem": "VC vs PC: the Difference and When to Use Each"},
    {"id": "q-f202-s14-008", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In pressure control, a patient develops ARDS. What happens?", "choices": ["Pressure stays the same and VT decreases", "VT stays the same and pressure rises", "Both rise", "PEEP rises automatically"], "correct": 0, "explanation": "PC guarantees pressure; VT falls with decreased compliance.", "srcItem": "VC vs PC: the Difference and When to Use Each"},
    {"id": "q-f202-s14-009", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "PC is set at 20 cm H₂O with PEEP 10 cm H₂O. What is the PIP?", "choices": ["30 cm H₂O", "20 cm H₂O", "10 cm H₂O", "40 cm H₂O"], "correct": 0, "explanation": "PIP = pressure control + PEEP = 20 + 10 = 30 cm H₂O.", "srcItem": "VC vs PC: the Difference and When to Use Each"},
    {"id": "q-f202-s14-010", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which pressure waveform 'looks like a table' with a plateau?", "choices": ["Pressure control", "Volume control with constant flow", "SIMV with no PS", "HFOV"], "correct": 0, "explanation": "PC: square pressure waveform with a plateau and descending flow; VC: \"mountain\" pressure with square flow.", "srcItem": "VC vs PC: the Difference and When to Use Each"},
    {"id": "q-f202-s14-011", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "When does Hess say volume control should be used?", "choices": ["Whenever a constant VT is important to maintain a desired PaCO₂", "Only in apneic neonates", "Only for weaning", "When the patient has a large leak"], "correct": 0, "explanation": "Hess: VC whenever a constant tidal volume is important for the desired PaCO₂.", "srcItem": "VC vs PC: the Difference and When to Use Each"},
    {"id": "q-f202-s14-012", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A patient on VC needs a Pplat above 30 cm H₂O. What does the RCP 203 deck suggest?", "choices": ["Switch to pressure control at ≤ 30", "Increase the VT", "Add more PEEP", "Switch to SIMV with no PS"], "correct": 0, "explanation": "RCP 203: a patient needing Pplat > 30 in VC should probably be switched to PC at ≤ 30.", "srcItem": "VC vs PC: the Difference and When to Use Each"},
    {"id": "q-f202-s14-013", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the key difference between the control mode (CMV) and assist/control?", "choices": ["A/C allows patient-triggered breaths; CMV (control) does not", "CMV allows spontaneous breaths between mandatory breaths", "A/C has no set rate", "CMV always uses pressure support"], "correct": 0, "explanation": "The slide's one-line difference: A/C allows patient-triggered breaths; control mode does not.", "srcItem": "CMV (and How It Differs from Assist/Control)"},
    {"id": "q-f202-s14-014", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A/C is set at 12 breaths/min and the patient triggers 24. How many full breaths are delivered?", "choices": ["24", "12", "36", "6"], "correct": 0, "explanation": "In A/C every triggered breath gets the full preset support; the set rate is a minimum.", "srcItem": "CMV (and How It Differs from Assist/Control)"},
    {"id": "q-f202-s14-015", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How is a patient-triggered (assisted) breath identified on the pressure waveform?", "choices": ["A negative deflection below baseline before inspiration", "A positive spike after exhalation", "A flat line", "A sudden drop in PEEP to zero"], "correct": 0, "explanation": "Assist = negative deflection before inspiration; time-triggered control breaths have none.", "srcItem": "CMV (and How It Differs from Assist/Control)"},
    {"id": "q-f202-s14-016", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is a complication of A/C when the patient triggers at a high rate?", "choices": ["Respiratory alkalosis from alveolar hyperventilation", "Respiratory acidosis", "Hypoxemia from low FiO₂", "Low mean airway pressure"], "correct": 0, "explanation": "High frequency in A/C → alveolar hyperventilation (respiratory alkalosis) and possibly auto-PEEP.", "srcItem": "CMV (and How It Differs from Assist/Control)"},
    {"id": "q-f202-s14-017", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which alarms are most important in the control mode?", "choices": ["Low exhaled volume and low inspiratory pressure", "High FiO₂ and high temperature", "Apnea and low battery only", "High PEEP and high rate"], "correct": 0, "explanation": "In control mode, the most important alarms are low exhaled volume and low inspiratory pressure.", "srcItem": "CMV (and How It Differs from Assist/Control)"},
    {"id": "q-f202-s14-018", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What problem does IMV (unsynchronized) cause that SIMV avoids?", "choices": ["Breath stacking", "Low FiO₂", "Excess PS", "Hypercapnia only"], "correct": 0, "explanation": "IMV can deliver a mandatory breath before a spontaneous one is exhaled → breath stacking, auto-PEEP.", "srcItem": "IMV vs SIMV"},
    {"id": "q-f202-s14-019", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "SIMV is set at a rate of 10 and the patient breathes at 20. What does the patient receive?", "choices": ["10 mandatory and 10 spontaneous breaths", "20 mandatory breaths", "20 spontaneous breaths", "10 mandatory breaths only"], "correct": 0, "explanation": "SIMV gives the set mandatory breaths; extra breaths are spontaneous (A/C would give 20 mandatory).", "srcItem": "IMV vs SIMV"},
    {"id": "q-f202-s14-020", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In SIMV with PS 8, which breaths receive the pressure support?", "choices": ["Only the spontaneous breaths between mandatory breaths", "Only the mandatory breaths", "All breaths equally", "No breaths — PS is inactive in SIMV"], "correct": 0, "explanation": "PS applies only to spontaneous breaths; mandatory breaths deliver the preset VT.", "srcItem": "IMV vs SIMV"},
    {"id": "q-f202-s14-021", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why is SIMV usually combined with pressure support?", "choices": ["To prevent muscle fatigue and high WOB on spontaneous breaths", "To increase the mandatory rate", "To guarantee VT on every breath", "To lower the FiO₂"], "correct": 0, "explanation": "Without PS, SIMV can cause muscle fatigue and weaning failure; PS helps the spontaneous breaths.", "srcItem": "IMV vs SIMV"},
    {"id": "q-f202-s14-022", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does the instructor's word-play list treat SIMV?", "choices": ["SIMV = IMV", "SIMV = A/C", "SIMV = CPAP", "SIMV = PRVC"], "correct": 0, "explanation": "Word-play: \"SIMV = IMV\" — treat them as the same breath sequence unless the stem is about breath stacking.", "srcItem": "IMV vs SIMV"},
    {"id": "q-f202-s14-023", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How is pressure support classified?", "choices": ["Patient-triggered, pressure-limited, flow-cycled", "Time-triggered, volume-limited, time-cycled", "Patient-triggered, volume-limited, volume-cycled", "Time-triggered, pressure-limited, time-cycled"], "correct": 0, "explanation": "PSV = patient-triggered, pressure-limited, flow-cycled — a phrase on NBRC-style exams repeatedly.", "srcItem": "Pressure Support"},
    {"id": "q-f202-s14-024", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "When does a pressure-supported breath end?", "choices": ["When inspiratory flow falls to a preset percentage of peak flow, often ~25%", "After a fixed inspiratory time", "When the preset VT is reached", "When the patient coughs"], "correct": 0, "explanation": "PS breaths flow-cycle, often at about 25% of peak flow.", "srcItem": "Pressure Support"},
    {"id": "q-f202-s14-025", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why can PSV not be used alone in an apneic patient?", "choices": ["Every PS breath must be patient-triggered", "PS gives too much volume", "PS has no FiO₂ setting", "PS requires paralysis"], "correct": 0, "explanation": "PS is active only on spontaneous breaths, so it needs an intact respiratory drive.", "srcItem": "Pressure Support"},
    {"id": "q-f202-s14-026", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "PS is set too high. What may Hess say happens?", "choices": ["Activation of the expiratory muscles", "Tachypnea and fatigue", "Apnea alarms only", "Decreased VT"], "correct": 0, "explanation": "Too low → fatigue and tachypnea; too high → expiratory muscle activation.", "srcItem": "Pressure Support"},
    {"id": "q-f202-s14-027", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does MMV ensure adequate ventilation?", "choices": ["It increases mandatory breaths when spontaneous V̇E falls below a preset minimum", "It guarantees VT on every breath", "It raises PEEP automatically", "It increases the FiO₂ to 1.0"], "correct": 0, "explanation": "MMV is a \"minimum ventilation safety net\": low V̇E → more volume-cycled mandatory breaths.", "srcItem": "MMV (Mandatory, or Minimum, Minute Ventilation)"},
    {"id": "q-f202-s14-028", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "On MMV with a target of 8 L/min, the patient breathes 9 L/min alone. What does the ventilator do?", "choices": ["Adds no extra mandatory ventilation", "Adds 1 L/min of mandatory breaths", "Switches to A/C", "Lowers the patient's rate"], "correct": 0, "explanation": "If the patient breathes enough, MMV stays out of the way.", "srcItem": "MMV (Mandatory, or Minimum, Minute Ventilation)"},
    {"id": "q-f202-s14-029", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does MMV NOT guarantee?", "choices": ["That every breath has an adequate VT", "A minimum total minute ventilation", "Backup mandatory breaths", "Volume-cycled mandatory breaths"], "correct": 0, "explanation": "MMV guarantees minimum total V̇E, not an adequate VT on every breath.", "srcItem": "MMV (Mandatory, or Minimum, Minute Ventilation)"},
    {"id": "q-f202-s14-030", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which mode automatically adjusts inspiratory pressure to maintain a target VT while minimizing airway pressure?", "choices": ["PRVC", "APRV", "PAV", "HFOV"], "correct": 0, "explanation": "Board pearl: PRVC delivers the target VT at the lowest PIP possible.", "srcItem": "PRVC"},
    {"id": "q-f202-s14-031", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "On PRVC, the patient's compliance worsens. What does the ventilator do?", "choices": ["Raises the inspiratory pressure to deliver the target VT", "Lowers the inspiratory pressure", "Drops the VT", "Switches to CPAP"], "correct": 0, "explanation": "Compliance worsens → PRVC raises pressure; compliance improves → it lowers pressure.", "srcItem": "PRVC"},
    {"id": "q-f202-s14-032", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "On Automode, the patient makes two consecutive patient-triggered breaths. What happens?", "choices": ["It switches from PRVC to Volume Support", "It switches to apnea ventilation", "It switches to CPAP with no support", "It stops ventilating"], "correct": 0, "explanation": "Automode: sleeping patient → PRVC; awake patient (two triggered breaths) → Volume Support.", "srcItem": "PRVC"},
    {"id": "q-f202-s14-033", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is a caution about PRVC if a patient's demand rises inappropriately, e.g. from pain?", "choices": ["As VT rises, the ventilator lowers pressure support, which may be wrong for that patient", "It raises pressure to dangerous levels", "It stops all mandatory breaths", "It increases the FiO₂"], "correct": 0, "explanation": "Hess: higher VT from pain makes PRVC lower its pressure, which may be inappropriate in respiratory failure.", "srcItem": "PRVC"},
    {"id": "q-f202-s14-034", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is Volume Control Plus (VC+) on the PB 840?", "choices": ["Puritan Bennett's version of PRVC", "A form of APRV", "A type of HFOV", "A CPAP mode"], "correct": 0, "explanation": "VC+ = PB's PRVC: preset VT and I-time with variable pressure and flow.", "srcItem": "VV+"},
    {"id": "q-f202-s14-035", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does Volume Support differ from pressure support?", "choices": ["VS guarantees volume and lets pressure vary; PS guarantees pressure and lets volume vary", "VS is time-cycled; PS is flow-cycled", "VS needs a set rate; PS does not", "They are identical"], "correct": 0, "explanation": "Both are patient-triggered, pressure-limited, flow-cycled; VS targets volume.", "srcItem": "VV+"},
    {"id": "q-f202-s14-036", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "On Volume Support, the patient makes more effort. What happens to the support pressure?", "choices": ["It decreases", "It increases", "It stays fixed", "It drops to zero immediately"], "correct": 0, "explanation": "Less effort → higher PS; more effort → lower PS, to hold the target VT.", "srcItem": "VV+"},
    {"id": "q-f202-s14-037", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does PAV target?", "choices": ["No set flow, volume or pressure — support is proportional to the patient's effort", "A fixed tidal volume", "A fixed inspiratory pressure", "A fixed minute ventilation"], "correct": 0, "explanation": "\"With PAV there is no target flow, volume, or pressure\"; pull harder → more assist.", "srcItem": "PAV (Proportional Assist Ventilation)"},
    {"id": "q-f202-s14-038", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What happens if the PAV % assist is set too high?", "choices": ["'Runaway' with excessive volume and pressure", "Excessive patient work of breathing", "Apnea", "Hypoxemia from low FiO₂"], "correct": 0, "explanation": "Too high → runaway; too low → excessive patient WOB.", "srcItem": "PAV (Proportional Assist Ventilation)"},
    {"id": "q-f202-s14-039", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which patient is NOT suitable for PAV?", "choices": ["An apneic patient with no respiratory drive", "A COPD patient being weaned", "A patient coming off sedation", "A patient with variable drive"], "correct": 0, "explanation": "PAV requires intact drive and a functional neuromuscular system.", "srcItem": "PAV (Proportional Assist Ventilation)"},
    {"id": "q-f202-s14-040", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In PAV, what does 'flow assist' overcome?", "choices": ["Airflow resistance", "Elastic (restrictive) load", "Dead space", "Hypoxemia"], "correct": 0, "explanation": "Flow assist overcomes resistance; volume assist overcomes elastance.", "srcItem": "PAV (Proportional Assist Ventilation)"},
    {"id": "q-f202-s14-041", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does the RCP 202 deck define APRV?", "choices": ["Inverse ratio, pressure-controlled IMV with unrestricted spontaneous breathing", "Volume-controlled CMV with high rates", "High-frequency oscillation", "Pressure support with backup rate"], "correct": 0, "explanation": "APRV: inverse ratio, pressure-controlled, intermittent mandatory ventilation with unrestricted spontaneous breathing.", "srcItem": "APRV (Airway Pressure Release Ventilation)"},
    {"id": "q-f202-s14-042", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which settings are used in APRV?", "choices": ["FiO₂, Phigh, Plow, Thigh and Tlow", "VT, rate, PEEP and flow", "Amplitude, Hz and mean airway pressure", "Target V̇E only"], "correct": 0, "explanation": "APRV has no VT or rate setting; Thigh and Tlow set the release frequency.", "srcItem": "APRV (Airway Pressure Release Ventilation)"},
    {"id": "q-f202-s14-043", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How long does an adult spend at Plow during APRV (Hess)?", "choices": ["About 0.2–0.8 seconds", "About 5 seconds", "About 30 seconds", "Half of each cycle"], "correct": 0, "explanation": "Tlow 0.2–0.8 s; 80–95% of the cycle is at Phigh, producing intrinsic PEEP.", "srcItem": "APRV (Airway Pressure Release Ventilation)"},
    {"id": "q-f202-s14-044", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How is APRV weaned in the Chang weaning deck?", "choices": ["Decrease the release frequency until the patient is essentially on CPAP", "Increase Plow to Phigh", "Increase the release rate", "Switch to HFOV"], "correct": 0, "explanation": "Decrease release frequency; at zero the patient is essentially on CPAP.", "srcItem": "APRV (Airway Pressure Release Ventilation)"},
    {"id": "q-f202-s14-045", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which patient best fits APRV?", "choices": ["Hypoxemic failure/ARDS with an intact respiratory drive", "An apneic, paralyzed patient", "A patient needing a guaranteed VT", "A patient with severe air trapping"], "correct": 0, "explanation": "Classic APRV patient: significant hypoxemic failure with intact drive (not deeply paralyzed).", "srcItem": "APRV (Airway Pressure Release Ventilation)"},
    {"id": "q-f202-s14-046", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "On HFOV, how is CO₂ removal improved?", "choices": ["Increase the amplitude or decrease the frequency (Hz)", "Increase the frequency", "Increase the mean airway pressure", "Increase the FiO₂"], "correct": 0, "explanation": "↓ Hz → larger oscillatory VT → ↑ CO₂ removal — \"backwards from conventional ventilation.\"", "srcItem": "HFOV (High-Frequency Oscillatory Ventilation)"},
    {"id": "q-f202-s14-047", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "On HFOV, how is oxygenation improved?", "choices": ["Increase the mean airway pressure or FiO₂", "Decrease the amplitude", "Increase the frequency", "Decrease the bias flow"], "correct": 0, "explanation": "Oxygenation: ↑ mean airway pressure or ↑ FiO₂.", "srcItem": "HFOV (High-Frequency Oscillatory Ventilation)"},
    {"id": "q-f202-s14-048", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does HFOV exhalation differ from conventional ventilation?", "choices": ["Exhalation is active — the oscillator pulls gas out", "Exhalation is passive", "There is no exhalation", "Exhalation is time-cycled at 1 Hz"], "correct": 0, "explanation": "HFOV actively pushes gas in and pulls it out; conventional exhalation is passive.", "srcItem": "HFOV (High-Frequency Oscillatory Ventilation)"},
    {"id": "q-f202-s14-049", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Is HFOV recommended routinely for adults with ARDS?", "choices": ["No — it has not shown benefit and may cause harm", "Yes — it is first-line", "Only for mild ARDS", "Only with PEEP above 20"], "correct": 0, "explanation": "Trauma deck and Hess: not routinely recommended in adult ARDS; strong recommendation against routine use.", "srcItem": "HFOV (High-Frequency Oscillatory Ventilation)"},
    {"id": "q-f202-s14-050", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which mode is described as 'tiny VT + very fast RR', with VT near or below dead space?", "choices": ["HFOV", "APRV", "PRVC", "MMV"], "correct": 0, "explanation": "HFOV: extremely small volumes at 3–15 Hz (180–900 breaths/min).", "srcItem": "HFOV (High-Frequency Oscillatory Ventilation)"},
    {"id": "q-f202-s14-051", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which mode gives a target VT at the lowest PIP with pressure auto-adjusted breath to breath?", "choices": ["PRVC", "PAV", "MMV", "APRV"], "correct": 0, "explanation": "Side-by-side table: PRVC = target VT at lowest PIP, pressure auto-adjusted.", "srcItem": "All the Listed Modes Side by Side"},
    {"id": "q-f202-s14-052", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which mode is listed as historical and not offered on new adult ventilators?", "choices": ["IMV (unsynchronized)", "SIMV", "PRVC", "Pressure support"], "correct": 0, "explanation": "IMV causes breath stacking; all current ventilators offer SIMV instead.", "srcItem": "All the Listed Modes Side by Side"},
    {"id": "q-f202-s14-053", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is patient–ventilator asynchrony?", "choices": ["The ventilator's breath delivery is out of phase with the patient's effort", "The patient's heart rate is irregular", "The ventilator alarms are silenced", "The FiO₂ is set incorrectly"], "correct": 0, "explanation": "Hess: synchrony = breath delivery in phase with patient effort; asynchrony = out of phase.", "srcItem": "What Causes Patient–Ventilator Asynchrony"},
    {"id": "q-f202-s14-054", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which is a consequence of patient–ventilator asynchrony?", "choices": ["Increased WOB and sedation needs, and longer ventilation", "Lower oxygen cost of breathing", "Shorter weaning", "Improved comfort"], "correct": 0, "explanation": "Asynchrony decreases comfort, increases WOB and sedation needs, and prolongs ventilation.", "srcItem": "What Causes Patient–Ventilator Asynchrony"},
    {"id": "q-f202-s14-055", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A COPD patient's respiratory rate is higher than the ventilator's measured rate. What is the likely cause?", "choices": ["Auto-PEEP preventing some efforts from triggering", "An overly sensitive trigger", "A circuit leak", "Cardiac oscillations"], "correct": 0, "explanation": "Patient rate > ventilator rate means efforts are missed, commonly from auto-PEEP raising the trigger threshold.", "srcItem": "What Causes Patient–Ventilator Asynchrony"},
    {"id": "q-f202-s14-056", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the usual pressure-trigger setting?", "choices": ["1 to 2 cm H₂O below PEEP/CPAP", "10 cm H₂O below PEEP", "Equal to PEEP", "5 cm H₂O above PEEP"], "correct": 0, "explanation": "Hess: set so trigger effort is minimal but auto-triggering unlikely — 1–2 cm H₂O below PEEP.", "srcItem": "What Causes Patient–Ventilator Asynchrony"},
    {"id": "q-f202-s14-057", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "The ventilator delivers breaths although the patient is making no visible effort. What should you think of first?", "choices": ["Auto-triggering from a circuit leak", "Patient anxiety", "Auto-PEEP", "Flow starvation"], "correct": 0, "explanation": "\"Think leak\" when breaths appear in a patient making no obvious efforts; water and cardiac oscillations also auto-trigger.", "srcItem": "What Causes Patient–Ventilator Asynchrony"},
    {"id": "q-f202-s14-058", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A trigger is changed from −3 to −1 cm H₂O. What has happened?", "choices": ["It became more sensitive", "It became less sensitive", "Nothing — it is the same", "It switched to flow triggering"], "correct": 0, "explanation": "Closer to zero = more sensitive; farther from zero (−5) = less sensitive.", "srcItem": "What Causes Patient–Ventilator Asynchrony"},
    {"id": "q-f202-s14-059", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "During VC, a vigorous patient effort pulls the pressure waveform downward and PIP varies breath to breath. What is the problem?", "choices": ["Flow starvation (flow asynchrony)", "Auto-triggering", "Delayed cycling", "Excess PEEP"], "correct": 0, "explanation": "The ventilator isn't meeting inspiratory flow demand; fix by raising flow or switching to PC/PS.", "srcItem": "Flow Asynchrony"},
    {"id": "q-f202-s14-060", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A pressure dip early in inspiration on the waveform suggests what?", "choices": ["Inadequate peak flow — 'I need more flow'", "Too much volume", "Delayed cycling", "A leak"], "correct": 0, "explanation": "Early dip = \"I need more flow\"; late dip = \"I want more volume.\"", "srcItem": "Flow Asynchrony"},
    {"id": "q-f202-s14-061", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A patient receives a second breath almost immediately after the first, nearly doubling the set VT. What is this?", "choices": ["Double triggering from premature cycling", "Auto-PEEP", "Delayed cycling", "Flow starvation only"], "correct": 0, "explanation": "Premature cycling: the patient's effort continues after the breath ends and double-triggers.", "srcItem": "Flow Asynchrony"},
    {"id": "q-f202-s14-062", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "On PS in a COPD patient, a pressure spike appears at end-inspiration and the abdomen tightens. What is happening?", "choices": ["Delayed cycling — the patient is actively exhaling against the breath", "Premature cycling", "Flow starvation", "Auto-triggering"], "correct": 0, "explanation": "In obstruction, flow decays slowly and never reaches the cycle threshold; the patient fights to exhale.", "srcItem": "Flow Asynchrony"},
    {"id": "q-f202-s14-063", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How can delayed cycling on PS be fixed?", "choices": ["Lower the PS level or raise the termination-flow (cycle) setting", "Increase the PS level", "Lower the trigger sensitivity", "Increase the PEEP"], "correct": 0, "explanation": "Hess: lower PS, raise the cycle percentage, or switch to time-cycled PC.", "srcItem": "Flow Asynchrony"},
    {"id": "q-f202-s14-064", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the recommended order for fixing asynchrony?", "choices": ["Adjust settings → reconsider the mode → sedation/analgesia → neuromuscular blockade last", "Paralyze first, then adjust settings", "Change the mode first, then sedate", "Sedate heavily, then never paralyze"], "correct": 0, "explanation": "Troubleshoot and adjust settings first; \"Paralytics don't fix problems — they hide them.\"", "srcItem": "Mode Asynchrony and the Fix Sequence"},
    {"id": "q-f202-s14-065", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does Hess call a common cause of failure to breathe in synchrony with the ventilator?", "choices": ["Anxiety", "Low FiO₂", "High PEEP", "A cuff leak"], "correct": 0, "explanation": "\"Anxiety is a common cause of failure to breathe in synchrony with the ventilator.\"", "srcItem": "Mode Asynchrony and the Fix Sequence"},
    {"id": "q-f202-s14-066", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why can SIMV itself cause mode asynchrony?", "choices": ["The respiratory center cannot adapt to the varying breath types", "SIMV has no mandatory breaths", "SIMV always uses HFOV", "SIMV gives identical breaths"], "correct": 0, "explanation": "Mode asynchrony occurs when the ventilator delivers different breath types, as in SIMV.", "srcItem": "Mode Asynchrony and the Fix Sequence"},
    {"id": "q-f202-s14-067", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Before using a paralytic for asynchrony, what must be done?", "choices": ["Troubleshoot: kinked tube, secretions, wrong settings, circuit issues", "Remove all sedation", "Disconnect the ventilator", "Switch to CPAP"], "correct": 0, "explanation": "NMBA deck: \"DO NOT jump to paralytics\"; paralysis always requires ventilation plus sedation.", "srcItem": "Mode Asynchrony and the Fix Sequence"},
    {"id": "q-f202-s14-068", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does Automatic Tube Compensation (ATC) do?", "choices": ["Offsets the artificial airway's resistance so the patient breathes as if the tube weren't there", "Guarantees a minimum V̇E", "Raises PEEP automatically", "Removes secretions"], "correct": 0, "explanation": "ATC compensates during inspiration and expiration; a smaller ETT needs more compensation.", "srcItem": "ASV, ATC, and IRV"},
    {"id": "q-f202-s14-069", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What I:E ratio does inverse ratio ventilation use?", "choices": ["2:1 to 4:1", "1:2 to 1:3", "1:4 to 1:6", "1:1 only"], "correct": 0, "explanation": "Normal I:E is 1:1.5 to 1:3; IRV uses 2:1 to 4:1 to raise mean airway pressure.", "srcItem": "ASV, ATC, and IRV"},
    {"id": "q-f202-s14-070", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which is an adverse effect of inverse ratio ventilation?", "choices": ["Auto-PEEP from the short expiratory time", "Lower mean airway pressure", "Improved venous return", "Less need for sedation"], "correct": 0, "explanation": "IRV: ↓ venous return, auto-PEEP, barotrauma, dyssynchrony needing more sedation.", "srcItem": "ASV, ATC, and IRV"},
    {"id": "q-f202-s14-071", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does ASV (Adaptive Support Ventilation) target?", "choices": ["A minute ventilation, choosing rate and VT for the lowest WOB", "A fixed PIP", "A fixed VT only", "A fixed I:E of 4:1"], "correct": 0, "explanation": "ASV targets V̇E (via IBW) and uses the Otis equation to pick the rate with the lowest WOB.", "srcItem": "ASV, ATC, and IRV"},
    {"id": "q-f202-s14-072", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is normal adult inspiratory flow per the Principles deck?", "choices": ["40–60 L/min", "5–10 L/min", "100–150 L/min", "200 L/min"], "correct": 0, "explanation": "Principles deck: normal adult inspiratory flow = 40–60 L/min.", "srcItem": "Ventilator Variables"},
    {"id": "q-f202-s14-073", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "With constant flow of 60 L/min for 1 second, what tidal volume is delivered?", "choices": ["1 L", "60 mL", "6 L", "0.5 L"], "correct": 0, "explanation": "60 L/min = 1 L/s; VT = flow × TI = 1 L.", "srcItem": "Ventilator Variables"},
    {"id": "q-f202-s14-074", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What are the three control variables per the Principles deck?", "choices": ["Volume, pressure and time", "Trigger, limit and cycle", "Flow, FiO₂ and PEEP", "Rate, VT and I:E"], "correct": 0, "explanation": "Control variables: volume, pressure and time; trigger/limit/cycle are phase variables.", "srcItem": "Ventilator Variables"},
    {"id": "q-f202-s14-075", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "PEEP is 5 cm H₂O and PIP is 25 cm H₂O. What pressure drives inspiration above baseline?", "choices": ["20 cm H₂O", "25 cm H₂O", "30 cm H₂O", "5 cm H₂O"], "correct": 0, "explanation": "Measured from baseline: 25 − 5 = 20 cm H₂O.", "srcItem": "Ventilator Variables"},
    {"id": "q-f202-s14-076", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the 'independent variable' on a ventilator?", "choices": ["Whatever the ventilator guarantees", "Whatever changes with the patient", "The alarm limit", "The FiO₂ only"], "correct": 0, "explanation": "\"Whatever the ventilator guarantees is called the independent variable\"; the other floats.", "srcItem": "Independent vs Dependent Variables"},
    {"id": "q-f202-s14-077", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In PC, which change increases the delivered VT?", "choices": ["A higher driving pressure (PIP − PEEP)", "More auto-PEEP", "Lower compliance", "Higher resistance"], "correct": 0, "explanation": "Box 20-5: VT rises with ↑ driving pressure, longer TI (while flow present) and more effort.", "srcItem": "Independent vs Dependent Variables"},
    {"id": "q-f202-s14-078", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In VC, which change raises PIP?", "choices": ["Increased airway resistance", "Switching to descending-ramp flow", "Lower VT", "Improved compliance"], "correct": 0, "explanation": "Box 20-4: PIP rises with ↑ flow, constant flow, ↑ PEEP, auto-PEEP, ↑ VT, ↑ Raw, ↓ compliance.", "srcItem": "Independent vs Dependent Variables"},
    {"id": "q-f202-s14-079", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In VC, airway resistance increases. What happens to PIP − Pplat?", "choices": ["It increases, while Pplat is unchanged", "It decreases", "It stays the same while Pplat rises", "Both fall"], "correct": 0, "explanation": "↑ Raw in VC: ↑ PIP, ↑ PIP − Pplat, no change in Pplat.", "srcItem": "Independent vs Dependent Variables"},
    {"id": "q-f202-s14-080", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What starts a time-triggered breath?", "choices": ["A clinician-set rate or timer", "A patient's negative deflection", "A drop in circuit flow", "A cough"], "correct": 0, "explanation": "Rate 12 → a breath every 5 s; time-triggered breaths show no negative deflection.", "srcItem": "Trigger: What Starts the Breath"},
    {"id": "q-f202-s14-081", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Base flow is 10 L/min and flow sensitivity is 3 L/min. When does the ventilator trigger?", "choices": ["When expiratory-circuit flow drops to 7 L/min", "When flow rises to 13 L/min", "When flow drops to 3 L/min", "When flow drops to zero"], "correct": 0, "explanation": "Hess's example: it triggers at 7 L/min, assuming the patient inhaled 3 L/min.", "srcItem": "Trigger: What Starts the Breath"},
    {"id": "q-f202-s14-082", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A trigger set at −5 cm H₂O is too insensitive. What results?", "choices": ["The patient may not be able to trigger and fatigues", "Auto-triggering", "Double triggering", "Excess VT"], "correct": 0, "explanation": "Too high (not sensitive enough) → can't trigger; too sensitive (−0.5) → auto-trigger.", "srcItem": "Trigger: What Starts the Breath"},
    {"id": "q-f202-s14-083", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why can auto-PEEP make triggering difficult?", "choices": ["It acts as a threshold pressure that must be overcome before the trigger is reached", "It lowers the baseline pressure", "It increases flow sensitivity", "It turns off the trigger"], "correct": 0, "explanation": "Neither pressure nor flow triggering may be effective with significant auto-PEEP.", "srcItem": "Trigger: What Starts the Breath"},
    {"id": "q-f202-s14-084", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "According to the deck's memory line, how is pressure control cycled?", "choices": ["Time-cycled", "Volume-cycled", "Flow-cycled", "Pressure-cycled"], "correct": 0, "explanation": "\"Volume Control is volume-cycled. Pressure Control is time-cycled. PSV is flow-cycled.\"", "srcItem": "Cycle"},
    {"id": "q-f202-s14-085", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "When does pressure cycling most often occur?", "choices": ["As an alarm condition when the high-pressure limit is reached", "In every PS breath", "In every VC breath", "Only in HFOV"], "correct": 0, "explanation": "Pressure cycling most often occurs as a high-pressure alarm condition (e.g. a cough during VC).", "srcItem": "Cycle"},
    {"id": "q-f202-s14-086", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How is Volume Support classified (trigger/limit/cycle)?", "choices": ["Patient / pressure / flow", "Time / volume / time", "Patient / volume / volume", "Time / pressure / time"], "correct": 0, "explanation": "VS: patient-triggered, pressure-limited, flow-cycled — like PS but volume-targeted.", "srcItem": "Cycle"},
    {"id": "q-f202-s14-087", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the number one ventilator adjustment for improving oxygenation?", "choices": ["PEEP", "Respiratory rate", "Tidal volume", "Inspiratory flow"], "correct": 0, "explanation": "Pearl: PEEP is primarily an oxygenation intervention, not a ventilation intervention.", "srcItem": "PEEP"},
    {"id": "q-f202-s14-088", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does PEEP improve oxygenation?", "choices": ["It keeps alveoli open at end-expiration, increasing FRC and reducing shunt", "It increases the respiratory rate", "It removes CO₂ directly", "It decreases FRC"], "correct": 0, "explanation": "PEEP prevents end-expiratory collapse → ↑ FRC → ↑ V/Q → better oxygenation.", "srcItem": "PEEP"},
    {"id": "q-f202-s14-089", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is CPAP?", "choices": ["PEEP applied to a patient breathing entirely on their own", "A mandatory mode", "Pressure support with backup rate", "A high-frequency mode"], "correct": 0, "explanation": "CPAP = PEEP with all spontaneous breaths; on BiPAP, EPAP = PEEP.", "srcItem": "PEEP"},
    {"id": "q-f202-s14-090", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What initial PEEP does the Initiation deck give for refractory hypoxemia?", "choices": ["5 cm H₂O", "20 cm H₂O", "0 cm H₂O", "15 cm H₂O"], "correct": 0, "explanation": "Start at 5 cm H₂O (\"NBRC range 2–6\"), then adjust by FiO₂ need and cardiovascular response.", "srcItem": "PEEP"},
    {"id": "q-f202-s14-091", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How is 'optimal PEEP' defined in the Management of MV deck?", "choices": ["The lowest pressure that offers the most benefit with the least side effects", "The highest PEEP the patient tolerates", "Always 10 cm H₂O", "The PEEP that gives a PaO₂ above 150"], "correct": 0, "explanation": "Titrate with PaO₂, compliance, saturation and waveforms; e.g. 10 is optimal if 12 lowers PaO₂ and compliance.", "srcItem": "PEEP"},
    {"id": "q-f202-s14-092", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Where should PEEP be set on a pressure–volume loop?", "choices": ["Just above the lower inflection point", "At the upper inflection point", "Below the lower inflection point", "At zero"], "correct": 0, "explanation": "Answer \"just above the LIP\" (deck: at/slightly above; RCP 203: 2–3 cm H₂O above).", "srcItem": "PEEP"},
    {"id": "q-f202-s14-093", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What PEEP level does the RCP 202 slide associate with an increased incidence of barotrauma?", "choices": ["> 10 cm H₂O", "> 3 cm H₂O", "> 5 cm H₂O", "> 30 cm H₂O"], "correct": 0, "explanation": "\"PEEP > 10 (or P̄aw > 30, or PIP > 50) is associated with increased alveolar rupture or barotrauma.\"", "srcItem": "PEEP Complications and the \"Dangerous Level\""},
    {"id": "q-f202-s14-094", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the major downside of PEEP?", "choices": ["Decreased venous return, cardiac output and blood pressure", "Increased venous return", "Hypercapnia", "Increased FRC"], "correct": 0, "explanation": "↑ PEEP → ↑ intrathoracic pressure → ↓ venous return → ↓ CO → ↓ BP.", "srcItem": "PEEP Complications and the \"Dangerous Level\""},
    {"id": "q-f202-s14-095", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How can PEEP raise ICP?", "choices": ["Higher intrathoracic pressure impedes venous drainage from the brain", "It dilates cerebral arteries", "It lowers PaCO₂", "It increases CSF production"], "correct": 0, "explanation": "PEEP raises intrathoracic pressure, impeding cerebral venous drainage.", "srcItem": "PEEP Complications and the \"Dangerous Level\""},
    {"id": "q-f202-s14-096", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "With PPV and PEEP, why can CVP rise while preload actually falls?", "choices": ["Intrathoracic pressure raises the measured CVP even as venous return decreases", "CVP always equals preload", "PEEP increases blood volume", "The catheter migrates"], "correct": 0, "explanation": "\"High CVP does not always mean lots of preload.\"", "srcItem": "PEEP Complications and the \"Dangerous Level\""},
    {"id": "q-f202-s14-097", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is auto-PEEP?", "choices": ["Unintentional PEEP from gas trapped because exhalation did not finish before the next breath", "PEEP set by the clinician", "PEEP produced by a leak", "PEEP used only in neonates"], "correct": 0, "explanation": "Auto-PEEP (intrinsic, inadvertent, occult PEEP) = trapped gas; total PEEP = set PEEP + auto-PEEP.", "srcItem": "Auto-PEEP (Intrinsic, Inadvertent, Occult PEEP)"},
    {"id": "q-f202-s14-098", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How is auto-PEEP detected on the flow–time waveform?", "choices": ["Expiratory flow does not return to zero before the next breath", "Inspiratory flow is square", "Pressure returns to baseline", "There is a negative deflection before every breath"], "correct": 0, "explanation": "Expiratory flow failing to reach baseline before the next breath = air trapping.", "srcItem": "Auto-PEEP (Intrinsic, Inadvertent, Occult PEEP)"},
    {"id": "q-f202-s14-099", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How is auto-PEEP measured?", "choices": ["An end-expiratory pause; pause pressure minus set PEEP", "An end-inspiratory pause; Pplat minus PEEP", "PIP minus Pplat", "Exhaled VT minus set VT"], "correct": 0, "explanation": "Occlude just before the next breath; e.g. 12 − 5 = 7 cm H₂O auto-PEEP. The patient must be relaxed.", "srcItem": "Auto-PEEP (Intrinsic, Inadvertent, Occult PEEP)"},
    {"id": "q-f202-s14-100", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which ventilator change reduces auto-PEEP?", "choices": ["Decrease the respiratory rate to lengthen expiratory time", "Increase the rate", "Decrease the inspiratory flow", "Increase the VT"], "correct": 0, "explanation": "Give the lungs more time to empty: ↓ rate, ↑ flow, ↓ VT, bronchodilators.", "srcItem": "Auto-PEEP (Intrinsic, Inadvertent, Occult PEEP)"},
    {"id": "q-f202-s14-101", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A COPD patient on RR 20, VT 700, flow 40 L/min develops rising PIP, auto-PEEP and hypotension. What should be done?", "choices": ["Lower VT and rate, increase flow, and lengthen expiratory time", "Increase the VT to 900 mL", "Increase the rate to 30", "Decrease flow to 20 L/min"], "correct": 0, "explanation": "Principles deck vignette: lower VT, lower RR, increase flow, increase expiratory time.", "srcItem": "Auto-PEEP (Intrinsic, Inadvertent, Occult PEEP)"},
    {"id": "q-f202-s14-102", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In volume control, how does auto-PEEP affect PIP?", "choices": ["It raises PIP", "It lowers PIP", "It has no effect", "It turns PIP negative"], "correct": 0, "explanation": "In VC auto-PEEP raises PIP; in PC it reduces VT.", "srcItem": "Auto-PEEP (Intrinsic, Inadvertent, Occult PEEP)"},
    {"id": "q-f202-s14-103", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "When should applied (therapeutic) PEEP be used to counter auto-PEEP?", "choices": ["After ventilator adjustments, mainly to help triggering in obstructive disease", "Before any other adjustment", "Only in paralyzed patients", "Never"], "correct": 0, "explanation": "\"Therapeutic PEEP should be used after making ventilator adjustments\"; Hess: up to 75–85% of auto-PEEP.", "srcItem": "Auto-PEEP (Intrinsic, Inadvertent, Occult PEEP)"},
    {"id": "q-f202-s14-104", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does PIP overcome, compared with plateau pressure?", "choices": ["PIP overcomes resistance and compliance; Pplat overcomes compliance only", "PIP overcomes compliance only; Pplat overcomes resistance", "Both overcome only resistance", "Both overcome only compliance"], "correct": 0, "explanation": "Pplat is measured with no flow, so it excludes airway resistance; PIP − Pplat = flow × resistance.", "srcItem": "High Pressures and Their Causes (PIP vs Plateau)"},
    {"id": "q-f202-s14-105", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "PIP rises from 25 to 40 cm H₂O while Pplat stays at 20. What is the likely cause?", "choices": ["Increased airway resistance, such as secretions or bronchospasm", "Decreased compliance, such as ARDS", "Pneumothorax", "Atelectasis"], "correct": 0, "explanation": "\"When only PIP moves, think airways.\"", "srcItem": "High Pressures and Their Causes (PIP vs Plateau)"},
    {"id": "q-f202-s14-106", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "PIP and Pplat both rise by 10 cm H₂O. What is the likely cause?", "choices": ["Decreased compliance, such as pulmonary edema or pneumothorax", "Mucus plug in the ETT", "Patient biting the tube", "Water in the circuit"], "correct": 0, "explanation": "\"When PIP and Plateau move together, think lungs.\"", "srcItem": "High Pressures and Their Causes (PIP vs Plateau)"},
    {"id": "q-f202-s14-107", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Where should the high-pressure alarm be set (Initiation deck)?", "choices": ["10 to 15 cm H₂O above the observed PIP", "Equal to the observed PIP", "5 cm H₂O below PEEP", "60 cm H₂O always"], "correct": 0, "explanation": "High-pressure alarm: 10–15 cm H₂O above observed PIP; don't raise it without justification.", "srcItem": "High Pressures and Their Causes (PIP vs Plateau)"},
    {"id": "q-f202-s14-108", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What plateau pressure target should be used on this exam?", "choices": ["< 30 cm H₂O", "< 50 cm H₂O", "< 15 cm H₂O", "< 60 cm H₂O"], "correct": 0, "explanation": "\"Today, the accepted goal is a Pplat below 30 cm H₂O whenever possible.\"", "srcItem": "High Pressures and Their Causes (PIP vs Plateau)"},
    {"id": "q-f202-s14-109", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How is driving pressure correctly calculated for the exam?", "choices": ["Pplat − PEEP, with a target < 15 cm H₂O", "PIP − Pplat", "PIP + PEEP", "Mean airway pressure − PEEP"], "correct": 0, "explanation": "True driving pressure = Pplat − PEEP (< 15); PIP − PEEP is total pressure including resistance.", "srcItem": "High Pressures and Their Causes (PIP vs Plateau)"},
    {"id": "q-f202-s14-110", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "PIP 43, Pplat 40, flow 0.33 L/s. What is the airway resistance?", "choices": ["About 9 cm H₂O/L/s", "About 130 cm H₂O/L/s", "About 0.3 cm H₂O/L/s", "About 40 cm H₂O/L/s"], "correct": 0, "explanation": "Raw = (PIP − Pplat) ÷ flow = 3 ÷ 0.33 ≈ 9.", "srcItem": "High Pressures and Their Causes (PIP vs Plateau)"},
    {"id": "q-f202-s14-111", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which alarm in pressure control or pressure support detects changes in resistance and compliance (Hess)?", "choices": ["Low exhaled volume alarm", "High-pressure alarm", "High FiO₂ alarm", "Apnea alarm"], "correct": 0, "explanation": "In VC the peak-pressure alarm detects changes; in PC or PS it is the low exhaled volume alarm.", "srcItem": "High Pressures and Their Causes (PIP vs Plateau)"},
    {"id": "q-f202-s14-112", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Where is the low inspiratory pressure alarm set?", "choices": ["10 to 15 cm H₂O below the observed PIP", "At the PEEP level", "Above the observed PIP", "At 0 cm H₂O"], "correct": 0, "explanation": "Low-pressure alarm: 10–15 below PIP, to detect leaks or disconnection.", "srcItem": "Low Pressures and Their Causes"},
    {"id": "q-f202-s14-113", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "According to Hess, what is the most important ventilator alarm?", "choices": ["The patient-disconnect alarm", "The high FiO₂ alarm", "The low battery alarm", "The high rate alarm"], "correct": 0, "explanation": "Hess: the patient-disconnect alarm — a low-pressure and/or low exhaled volume alarm.", "srcItem": "Low Pressures and Their Causes"},
    {"id": "q-f202-s14-114", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Expired VT is lower than set VT on every breath and PIP is lower than before. What is the problem?", "choices": ["A leak", "Air trapping", "Bronchospasm", "Pneumothorax"], "correct": 0, "explanation": "A leak is low on every breath; with air trapping, expired VT is low for 2–3 breaths, then high.", "srcItem": "Low Pressures and Their Causes"},
    {"id": "q-f202-s14-115", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "The low PEEP alarm sounds. What is the usual cause?", "choices": ["A leak in the circuit or ETT cuff", "Auto-PEEP", "Bronchospasm", "An overly sensitive trigger"], "correct": 0, "explanation": "\"Failure of the circuit to hold PEEP is usually due to leakage in the circuit or ETT cuff.\"", "srcItem": "Low Pressures and Their Causes"},
    {"id": "q-f202-s14-116", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "An end-inspiratory squeak is heard over the trachea. What does it usually mean?", "choices": ["Insufficient air in the artificial airway cuff", "Bronchospasm", "Normal breath sounds", "A kinked circuit"], "correct": 0, "explanation": "Hess: an end-inspiratory squeak usually means insufficient cuff air.", "srcItem": "Low Pressures and Their Causes"},
    {"id": "q-f202-s14-117", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What delay is used for the apnea alarm?", "choices": ["15 to 20 seconds", "2 seconds", "2 minutes", "5 minutes"], "correct": 0, "explanation": "Apnea alarm: 15–20 s delay; causes include disconnection, oversedation, neuromuscular block.", "srcItem": "Low Pressures and Their Causes"},
    {"id": "q-f202-s14-118", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the correct response to a ventilator alarm?", "choices": ["Look at the patient, then the ventilator, find the cause and fix it", "Silence it and walk away", "Raise the alarm limit", "Turn off the ventilator"], "correct": 0, "explanation": "Alarm → patient → ventilator → cause → fix. Never silence an alarm and walk away.", "srcItem": "Low Pressures and Their Causes"},
    {"id": "q-f202-s14-119", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which circuit type is used on noninvasive ventilators?", "choices": ["Single-limb without an exhalation valve (a leak port)", "Double-limb with a wye", "Single-limb with a mushroom valve only", "No circuit"], "correct": 0, "explanation": "NIV uses a known leak port; the ventilator calculates and subtracts the leak.", "srcItem": "Ventilator Circuits"},
    {"id": "q-f202-s14-120", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Where is the exhalation valve in a double-limb (wye) ICU circuit?", "choices": ["Built into the ventilator", "At the patient end", "In the humidifier", "There is none"], "correct": 0, "explanation": "Double-limb circuits carry exhaled gas back to the ventilator's expiratory/PEEP valve.", "srcItem": "Ventilator Circuits"},
    {"id": "q-f202-s14-121", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Circuit compliance is 3 mL/cm H₂O, PIP 60 and PEEP 10. How much volume is compressed in the circuit?", "choices": ["150 mL", "30 mL", "180 mL", "600 mL"], "correct": 0, "explanation": "3 mL/cm H₂O × (60 − 10) = 150 mL; corrected VT = expired VT − 150 mL.", "srcItem": "Ventilator Circuits"},
    {"id": "q-f202-s14-122", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the most common threat to ventilator circuit patency?", "choices": ["Condensation", "Crystallized drugs", "Bacterial filters", "Swivel adapters"], "correct": 0, "explanation": "Condensation from temperature drop increases resistance; manage with heated wires, water traps or an HME.", "srcItem": "Ventilator Circuits"},
    {"id": "q-f202-s14-123", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How often should ventilator circuits be changed for infection control?", "choices": ["Not routinely; change when visibly soiled", "Every 8 hours", "Every 24 hours", "Every hour"], "correct": 0, "explanation": "Don't change routinely; weekly has been shown optimal; change when visibly soiled.", "srcItem": "Ventilator Circuits"},
    {"id": "q-f202-s14-124", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Adding an HME between the wye and the patient does what in a dual-limb circuit?", "choices": ["Increases mechanical dead space", "Decreases dead space", "Has no effect on dead space", "Eliminates rebreathing"], "correct": 0, "explanation": "Any device between the wye and the airway adds mechanical dead space.", "srcItem": "Ventilator Circuits"},
    {"id": "q-f202-s14-125", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What are the two jobs of the exhalation valve?", "choices": ["Separate inspiration from expiration and set PEEP", "Humidify gas and filter bacteria", "Measure FiO₂ and trigger breaths", "Warm the gas and measure VT"], "correct": 0, "explanation": "Closed in inspiration, open for exhalation; the expiratory valve controls PEEP.", "srcItem": "Exhalation"},
    {"id": "q-f202-s14-126", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which circuit obstruction is the more serious?", "choices": ["Expiratory obstruction — it can cause rebreathing, asphyxia or barotrauma", "Inspiratory obstruction", "Humidifier obstruction", "Temperature probe obstruction"], "correct": 0, "explanation": "Expiratory obstruction is more serious; it comes with low-volume and high-pressure alarms.", "srcItem": "Exhalation"},
    {"id": "q-f202-s14-127", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why must the expiratory valve be checked during aerosolized ribavirin?", "choices": ["Ribavirin can crystallize and occlude valves and sensors", "Ribavirin raises the FiO₂", "Ribavirin dissolves the circuit", "Ribavirin causes auto-triggering"], "correct": 0, "explanation": "Ribavirin crystals impair expiratory valves and sensors; watch for ↑ peak pressures.", "srcItem": "Exhalation"},
    {"id": "q-f202-s14-128", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does the equation of motion describe?", "choices": ["The pressure needed to deliver a breath to overcome airway resistance and lung/chest wall elastance", "The relationship between FiO₂ and PaO₂", "Cardiac output", "The oxygen content of blood"], "correct": 0, "explanation": "Pressure must overcome R × flow (resistive load) and E × volume (elastic load).", "srcItem": "The Equation of Motion"},
    {"id": "q-f202-s14-129", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In the equation of motion, what is elastance?", "choices": ["The inverse of compliance", "The same as resistance", "The flow rate", "The PEEP level"], "correct": 0, "explanation": "E = respiratory system elastance (lungs + chest wall), the inverse of compliance.", "srcItem": "The Equation of Motion"},
    {"id": "q-f202-s14-130", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "During full ventilatory support, what is Pmus in the equation of motion?", "choices": ["Zero — all pressure comes from the ventilator", "Equal to Paw", "Equal to PEEP", "Maximal"], "correct": 0, "explanation": "Full support: Pmus = 0. Spontaneous breathing: Paw = 0. Partial: both contribute.", "srcItem": "The Equation of Motion"},
    {"id": "q-f202-s14-131", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In ARDS, which term of the equation of motion rises?", "choices": ["The elastic (volume/compliance) term", "The resistive (resistance × flow) term", "Neither term", "Only the PEEP term"], "correct": 0, "explanation": "ARDS: low compliance raises the elastic term; asthma raises the resistive term.", "srcItem": "The Equation of Motion"},
    {"id": "q-f202-s14-132", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What VT and PEEP does the deck recommend during surgery?", "choices": ["VT 6–8 mL/kg PBW with low levels of PEEP", "VT 12 mL/kg with no PEEP", "VT 4 mL/kg with PEEP 20", "VT 10 mL/kg with PEEP 15"], "correct": 0, "explanation": "Intraoperative lung-protective settings: VT 6–8 mL/kg PBW, low PEEP, Pplat < 30.", "srcItem": "Ventilation Around Surgery"},
    {"id": "q-f202-s14-133", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which surgeries carry a 20–70% pulmonary complication rate?", "choices": ["Upper abdominal and thoracic surgeries", "Knee arthroscopy", "Cataract surgery", "Dental extraction"], "correct": 0, "explanation": "Incision site matters: upper abdominal and thoracic surgery carry 20–70% complication rates.", "srcItem": "Ventilation Around Surgery"},
    {"id": "q-f202-s14-134", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does the revised Key Point say about incentive spirometry after surgery?", "choices": ["Evidence does not support routine use of IS alone to prevent postoperative pulmonary complications", "IS alone prevents all complications", "IS is contraindicated after surgery", "IS should replace early ambulation"], "correct": 0, "explanation": "Revised slide: evidence does not support routine IS alone; IS, PEP, CPAP still treat atelectasis.", "srcItem": "Ventilation Around Surgery"},
    {"id": "q-f202-s14-135", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A home patient on pressure control develops a mucus plug in the trach. Why might the high-pressure alarm stay silent?", "choices": ["The ventilator still reaches its set pressure while delivered VT falls", "The plug lowers the pressure", "High-pressure alarms don't exist on home ventilators", "The plug raises the VT"], "correct": 0, "explanation": "In PC, obstruction lowers VT but pressure is still reached; the low exhaled VT/minute volume alarm sounds instead.", "srcItem": "Home ventilators"},
    {"id": "q-f202-s14-136", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does exhaled gas leave a passive home ventilator circuit?", "choices": ["Through an intentional leak port that flushes exhaled CO₂", "Through an exhalation valve", "Through the humidifier", "It is rebreathed"], "correct": 0, "explanation": "Passive circuits use a leak port (risk of CO₂ rebreathing if the leak is wrong); active circuits use a valve.", "srcItem": "Home ventilators"},
    {"id": "q-f202-s14-137", "topic": "f202-s14", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What must ventilator-dependent home patients and caregivers do before discharge?", "choices": ["Demonstrate competency in operation, airway care, alarms and emergency ventilation", "Only watch a video", "Sign a form only", "Nothing — home health handles it"], "correct": 0, "explanation": "They must demonstrate competency, not just hear about it; a resuscitation bag and backup power are needed.", "srcItem": "Home ventilators"},
    {"id": "q-f202-s15-001", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "On this exam, what does 'Vapotherm' mean?", "choices": ["Heated, humidified high-flow nasal cannula", "An ordinary nasal cannula at 15 L/min", "A non-rebreather mask", "A heated aerosol face tent"], "correct": 0, "explanation": "Word-play: \"HFNC = VapoTherm or Optiflow (NOT HFNC up to 15L).\"", "srcItem": "Describe Vapotherm"},
    {"id": "q-f202-s15-002", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why is a conventional nasal cannula limited to about 6–8 L/min?", "choices": ["Higher flows are uncomfortable without heated humidification", "Higher flows are toxic", "The flowmeter cannot go higher", "Higher flows lower the FiO₂"], "correct": 0, "explanation": "Heated humidification makes high flows comfortable; HFNC delivers up to 60 L/min.", "srcItem": "Describe Vapotherm"},
    {"id": "q-f202-s15-003", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What FiO₂ range can HFNC deliver, set independently of the flow?", "choices": ["0.21 to 1.0", "0.24 to 0.44 only", "0.60 to 1.0 only", "Fixed at 0.40"], "correct": 0, "explanation": "The air/O₂ blender sets FiO₂ 0.21–1.0 independently of the flow.", "srcItem": "Describe Vapotherm"},
    {"id": "q-f202-s15-004", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What flow range does the RCP 203 deck give for adult HFNC?", "choices": ["1–40+ L/min", "1–8 L/min", "1–20 L/min", "80–120 L/min"], "correct": 0, "explanation": "Adults 1–40+ L/min, children 1–20 L/min, infants 1–8 L/min.", "srcItem": "Describe Vapotherm"},
    {"id": "q-f202-s15-005", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "When setting up an older HFNC unit, what does the deck say to connect first?", "choices": ["Oxygen", "The humidifier power", "The nasal cannula to the patient", "The analyzer"], "correct": 0, "explanation": "\"ALWAYS connect O₂ 'First'\"; plug in the humidifier last and let it warm before connecting the cannula.", "srcItem": "Describe Vapotherm"},
    {"id": "q-f202-s15-006", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does HFNC produce a modest CPAP effect?", "choices": ["Pharyngeal pressure rises about 1 cm H₂O per 10 L/min with the mouth closed", "It uses a sealed mask", "It has an exhalation valve set to PEEP", "It cycles between two pressures"], "correct": 0, "explanation": "The flow opposes exhalation; the effect is lost if the patient opens their mouth.", "srcItem": "How HFNC works, who it is for, and when it is failing"},
    {"id": "q-f202-s15-007", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the most common indication for HFNC?", "choices": ["Acute hypoxemic respiratory failure", "COPD exacerbation with acidosis", "Status asthmaticus", "Cardiac arrest"], "correct": 0, "explanation": "HFNC decreases the intubation rate compared with conventional O₂ in acute hypoxemic failure.", "srcItem": "How HFNC works, who it is for, and when it is failing"},
    {"id": "q-f202-s15-008", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How is the ROX index calculated?", "choices": ["(SpO₂/FiO₂) ÷ respiratory rate", "PaO₂ ÷ FiO₂", "RR ÷ VT", "SpO₂ × FiO₂ × RR"], "correct": 0, "explanation": "ROX = (SpO₂/FiO₂) ÷ RR; ≥ 4.88 predicts success, < 3.85 consider intubation.", "srcItem": "How HFNC works, who it is for, and when it is failing"},
    {"id": "q-f202-s15-009", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "SpO₂ 92% on FiO₂ 0.50 with a rate of 20. What is the ROX index and what does it predict?", "choices": ["9.2 — success", "4.6 — watch closely", "1.8 — intubate", "46 — success"], "correct": 0, "explanation": "92 ÷ 0.50 = 184; 184 ÷ 20 = 9.2, which is ≥ 4.88.", "srcItem": "How HFNC works, who it is for, and when it is failing"},
    {"id": "q-f202-s15-010", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does HFNC reduce the work of breathing?", "choices": ["By flushing anatomic dead space and lowering upper-airway resistance", "By sealing the airway", "By delivering mandatory breaths", "By paralyzing the diaphragm"], "correct": 0, "explanation": "Dead-space washout and reduced upper-airway resistance lower WOB; a lower RR is common.", "srcItem": "How HFNC works, who it is for, and when it is failing"},
    {"id": "q-f202-s15-011", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the central cause of patient–ventilator asynchrony on NIV?", "choices": ["Leak", "High FiO₂", "Low EPAP", "Humidification"], "correct": 0, "explanation": "Leaks cause missed triggers, auto-triggering and delayed cycling.", "srcItem": "Patient–ventilator asynchrony on NIPPV"},
    {"id": "q-f202-s15-012", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "On the V60, what does a total leak reading of '---' or '0' mean?", "choices": ["The mask is too tight", "The leak is too large", "The patient is not ventilating", "The circuit is disconnected"], "correct": 0, "explanation": "Normal total leak is 7–25; never over 60; '---' or '0' = mask too tight.", "srcItem": "Patient–ventilator asynchrony on NIPPV"},
    {"id": "q-f202-s15-013", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How can cycle asynchrony from a leak on NIV be improved?", "choices": ["Use time-cycled pressure control instead of flow-cycled pressure support", "Increase the leak", "Lower the EPAP to zero", "Remove the backup rate"], "correct": 0, "explanation": "Box 21-3: minimize leak, use time-cycled PC, adjust the flow-cycle setting, reduce PS.", "srcItem": "Patient–ventilator asynchrony on NIPPV"},
    {"id": "q-f202-s15-014", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A patient on NIV pressure support develops periods of apnea at night. What should be added?", "choices": ["A backup rate (S/T mode)", "More leak", "Higher FiO₂ only", "A nasal pillow"], "correct": 0, "explanation": "PS has no backup rate; a backup rate is recommended, especially at night.", "srcItem": "Patient–ventilator asynchrony on NIPPV"},
    {"id": "q-f202-s15-015", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How should the rise time be set on BiPAP?", "choices": ["According to the patient's work of breathing, matching their effort", "According to the backup rate", "Always at the fastest setting", "Always at the slowest setting"], "correct": 0, "explanation": "Rise is \"set according to the pts WOB\"; I-time is set according to the backup rate.", "srcItem": "Patient–ventilator asynchrony on NIPPV"},
    {"id": "q-f202-s15-016", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "For which condition SHOULD NIV be used per the ERS/ATS guideline (CPG 21-2)?", "choices": ["COPD exacerbation with respiratory acidosis", "Hypercapnia without acidosis in COPD", "Established post-extubation respiratory failure", "De novo ARDS"], "correct": 0, "explanation": "NIV should be used: COPD exacerbation, acute cardiogenic pulmonary edema, postop failure, chest trauma, high-risk post-extubation prevention.", "srcItem": "NIPPV guideline"},
    {"id": "q-f202-s15-017", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which patient is excluded from NIV?", "choices": ["A patient with copious secretions and high aspiration risk", "A COPD patient with pH 7.30", "A patient with cardiogenic pulmonary edema", "A patient with RR 28 and accessory-muscle use"], "correct": 0, "explanation": "Exclusions: airway protection problems (arrest, instability, aspiration risk, copious secretions), mask fit problems, uncooperative patient.", "srcItem": "NIPPV guideline"},
    {"id": "q-f202-s15-018", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which finding suggests a patient needs ventilatory support (step 1 of NIV selection)?", "choices": ["pH < 7.35 with PaCO₂ > 45 mm Hg", "RR of 14/min", "SpO₂ 98% on room air", "Normal ABG"], "correct": 0, "explanation": "Box 21-1: respiratory distress, pH < 7.35 with PaCO₂ > 45, RR > 25, or a diagnosis known to respond.", "srcItem": "NIPPV guideline"},
    {"id": "q-f202-s15-019", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which pH does the RCP 203 Ch 11 deck list as a contraindication to NIV?", "choices": ["pH < 7.20", "pH < 7.35", "pH > 7.45", "pH 7.40"], "correct": 0, "explanation": "RCP 203 contraindications include pH < 7.20, upper airway obstruction, uncontrolled arrhythmias, GI bleeding.", "srcItem": "NIPPV guideline"},
    {"id": "q-f202-s15-020", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the primary goal of BiPAP, per the deck notes?", "choices": ["To reverse acute respiratory failure without an artificial airway", "To cure the underlying disease", "To sedate the patient", "To raise the PaCO₂"], "correct": 0, "explanation": "NIV will not cure the disease; it supports the patient until the disease is treated.", "srcItem": "Goals of NIPPV, how success is judged, and when to quit"},
    {"id": "q-f202-s15-021", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A patient on NIV continues to deteriorate. When does the RCP 105 deck say to intubate?", "choices": ["If deteriorating 30 minutes after starting NIV", "After 24 hours", "After 1 week", "Never — NIV must be continued"], "correct": 0, "explanation": "Use the deck's 30 minutes; Hess says 1–2 hours.", "srcItem": "Goals of NIPPV, how success is judged, and when to quit"},
    {"id": "q-f202-s15-022", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why may NPPV be chosen over intubation?", "choices": ["It preserves speech, swallowing and airway defenses and avoids VAP", "It always gives larger VT", "It requires deep sedation", "It guarantees a PaCO₂ of 40"], "correct": 0, "explanation": "NPPV lets the patient eat, drink and talk, and avoids artificial-airway complications.", "srcItem": "Goals of NIPPV, how success is judged, and when to quit"},
    {"id": "q-f202-s15-023", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "To minimize gastric insufflation on NIV, inspiratory pressure should stay below what?", "choices": ["About 20 cm H₂O", "5 cm H₂O", "40 cm H₂O", "60 cm H₂O"], "correct": 0, "explanation": "Hess: avoid inspiratory pressure > 20 cm H₂O; RCP 203: IPAP < 20–25.", "srcItem": "Goals of NIPPV, how success is judged, and when to quit"},
    {"id": "q-f202-s15-024", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which finding on NIV predicts failure, according to Hess?", "choices": ["A VT > 10 mL/kg", "A falling PaCO₂", "Improving comfort", "A lower respiratory rate"], "correct": 0, "explanation": "Hess: VT > 10 mL/kg predicts NIV failure; a faster PaCO₂ fall is seen with success.", "srcItem": "Goals of NIPPV, how success is judged, and when to quit"},
    {"id": "q-f202-s15-025", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the most common cause of cardiogenic pulmonary edema?", "choices": ["Left-sided heart failure", "Pneumonia", "ARDS", "Pulmonary embolism"], "correct": 0, "explanation": "Cardiogenic edema is a \"pressure problem\" from left heart failure backing pressure into the lungs.", "srcItem": "Cardiogenic pulmonary edema"},
    {"id": "q-f202-s15-026", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which sign is classic for cardiogenic pulmonary edema?", "choices": ["Pink, frothy sputum", "Thick green sputum", "Rusty sputum", "No sputum and a dry cough only"], "correct": 0, "explanation": "Classic signs: pink frothy sputum, tachypnea, PND, orthopnea, crackles.", "srcItem": "Cardiogenic pulmonary edema"},
    {"id": "q-f202-s15-027", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which chest radiograph finding fits cardiogenic pulmonary edema?", "choices": ["Cardiomegaly with a bat's-wing pattern and Kerley B lines", "Normal heart size with patchy infiltrates", "Hyperlucency with flat diaphragms", "A single lobar consolidation"], "correct": 0, "explanation": "Cardiomegaly (> 50% of thoracic width), Kerley lines, butterfly opacities, transudative effusion.", "srcItem": "Cardiogenic pulmonary edema"},
    {"id": "q-f202-s15-028", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What BNP level is normal?", "choices": ["< 100 pg/mL", "> 900 pg/mL", "300–600 pg/mL", "> 1,500 pg/mL"], "correct": 0, "explanation": "BNP < 100 normal; 100–300 suggests HF; > 300 mild; > 600 moderate; > 900 severe.", "srcItem": "Cardiogenic pulmonary edema"},
    {"id": "q-f202-s15-029", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the management order for cardiogenic pulmonary edema in the deck?", "choices": ["Decrease preload → decrease afterload → increase contractility", "Increase preload → increase afterload → decrease contractility", "Give fluids, then diuretics", "Intubate before any medication"], "correct": 0, "explanation": "Preload: nitroglycerin, furosemide; afterload: ACE inhibitors, nitroprusside; contractility: dobutamine, milrinone.", "srcItem": "Cardiogenic pulmonary edema"},
    {"id": "q-f202-s15-030", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does CPAP help in acute cardiogenic pulmonary edema?", "choices": ["It decreases preload and afterload and reduces shunt", "It increases venous return", "It raises LV afterload", "It lowers the PaO₂"], "correct": 0, "explanation": "↑ intrathoracic pressure → ↓ preload and afterload, ↑ compliance, ↓ shunt, ↑ PaO₂.", "srcItem": "CPAP/NIV for cardiogenic pulmonary edema"},
    {"id": "q-f202-s15-031", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What CPAP level is best supported for cardiogenic pulmonary edema?", "choices": ["5–10 cm H₂O", "20–25 cm H₂O", "1–2 cm H₂O", "30 cm H₂O"], "correct": 0, "explanation": "Hess Ch 21 and the RCP 103 deck: 5–10 cm H₂O; a 10 cm H₂O start fits every range.", "srcItem": "CPAP/NIV for cardiogenic pulmonary edema"},
    {"id": "q-f202-s15-032", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does the RCP 105 FAQ call the first-line therapy for acute pulmonary edema?", "choices": ["CPAP 8–12 cm H₂O with 100% oxygen", "HFNC at 15 L/min", "Intubation and PEEP 20", "Nasal cannula at 6 L/min"], "correct": 0, "explanation": "RCP 105 NIV FAQ: \"CPAP 8–12 cmH₂O with 100% oxygen.\"", "srcItem": "CPAP/NIV for cardiogenic pulmonary edema"},
    {"id": "q-f202-s15-033", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A CHF patient on CPAP develops hypercapnia. What should be done?", "choices": ["Switch to BiPAP with a backup rate", "Increase the CPAP to 25 cm H₂O", "Remove all positive pressure", "Lower the FiO₂"], "correct": 0, "explanation": "RCP 203: switch to bi-level with a backup rate if hypopnea or hypercapnia appears.", "srcItem": "CPAP/NIV for cardiogenic pulmonary edema"},
    {"id": "q-f202-s15-034", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What normal MAP range does Hess Table 3-1 give?", "choices": ["65–105 mm Hg", "20–40 mm Hg", "120–160 mm Hg", "40–60 mm Hg"], "correct": 0, "explanation": "Hess: MAP 65–105 mm Hg; the decks give minimums of 60 (tissue) and 70 (cerebral).", "srcItem": "Hemodynamics"},
    {"id": "q-f202-s15-035", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What minimum MAP does the deck give to maintain tissue perfusion?", "choices": ["60 mm Hg", "30 mm Hg", "100 mm Hg", "120 mm Hg"], "correct": 0, "explanation": "MAP 60 for tissue perfusion; MAP 70 for cerebral perfusion pressure.", "srcItem": "Hemodynamics"},
    {"id": "q-f202-s15-036", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why can NIPPV lower the MAP?", "choices": ["Increased intrathoracic pressure reduces venous return and cardiac output", "It increases preload", "It raises SVR", "It dilates the coronary arteries"], "correct": 0, "explanation": "↑ PEEP/EPAP → ↑ intrathoracic pressure → ↓ venous return → ↓ CO → ↓ BP.", "srcItem": "Hemodynamics"},
    {"id": "q-f202-s15-037", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does the leak port on a bilevel circuit do?", "choices": ["It serves as the patient's passive exhalation port", "It controls the FiO₂", "It humidifies the gas", "It triggers breaths"], "correct": 0, "explanation": "Bilevel machines use a single-limb circuit; the leak port is the passive exhalation route.", "srcItem": "Leak ports on NIV"},
    {"id": "q-f202-s15-038", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the hazard of a passive leak port if expiratory flow exceeds what it can vent?", "choices": ["CO₂ rebreathing", "Barotrauma from PEEP", "Hypoglycemia", "Oxygen toxicity"], "correct": 0, "explanation": "The patient exhales into the hose and rebreathes CO₂; higher EPAP flushes the hose.", "srcItem": "Leak ports on NIV"},
    {"id": "q-f202-s15-039", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why is the minimum EPAP on many bilevel ventilators 3–4 cm H₂O?", "choices": ["The extra flow it needs flushes exhaled gas from the hose", "Lower EPAP raises the FiO₂", "It prevents oxygen toxicity", "It keeps the mask from leaking"], "correct": 0, "explanation": "Higher expiratory pressure needs more flow, which flushes the hose and reduces rebreathing.", "srcItem": "Leak ports on NIV"},
    {"id": "q-f202-s15-040", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the most dangerous expiratory obstruction?", "choices": ["An obstructed exhalation port on a single-limb NPPV circuit", "A kinked inspiratory limb", "A wet HME", "A loose temperature probe"], "correct": 0, "explanation": "It can cause rebreathing, asphyxia or barotrauma.", "srcItem": "Leak ports on NIV"},
    {"id": "q-f202-s15-041", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "BiPAP is set at IPAP 15 / EPAP 5. What are the pressure support and PEEP?", "choices": ["PS 10 and PEEP 5", "PS 15 and PEEP 5", "PS 20 and PEEP 0", "PS 5 and PEEP 15"], "correct": 0, "explanation": "PS = IPAP − EPAP = 10; EPAP = PEEP = 5.", "srcItem": "Difference between PEEP, PAP, and pharyngeal pressure"},
    {"id": "q-f202-s15-042", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does HFNC's pharyngeal pressure differ from PEEP?", "choices": ["It is not set on the machine; it rises with flow and is lost if the mouth opens", "It is set exactly like PEEP", "It is always 10 cm H₂O", "It is measured with a PA catheter"], "correct": 0, "explanation": "Pharyngeal pressure rises ~1 cm H₂O per 10 L/min with the mouth closed.", "srcItem": "Difference between PEEP, PAP, and pharyngeal pressure"},
    {"id": "q-f202-s15-043", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does PAP treat obstructive sleep apnea?", "choices": ["It acts as a pneumatic splint holding the upper airway open", "It stimulates the diaphragm", "It lowers the PaCO₂ directly", "It sedates the patient"], "correct": 0, "explanation": "Hess: PAP counteracts negative inspiratory pressure and prevents airway collapse.", "srcItem": "Difference between PEEP, PAP, and pharyngeal pressure"},
    {"id": "q-f202-s15-044", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does PEEP affect pulmonary artery pressure (PAP)?", "choices": ["It raises it by compressing pulmonary capillaries", "It lowers it", "It has no effect", "It drops it to zero"], "correct": 0, "explanation": "PPV with PEEP → ↑ PAP from capillary compression and higher PVR.", "srcItem": "Difference between PEEP, PAP, and pharyngeal pressure"},
    {"id": "q-f202-s15-045", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A BiPAP patient has a high PaCO₂. What should be changed?", "choices": ["Increase IPAP (pressure support)", "Increase EPAP only", "Decrease IPAP", "Increase the FiO₂ only"], "correct": 0, "explanation": "High CO₂ → raise IPAP/PS to increase VT and minute ventilation.", "srcItem": "BiPAP settings, adjustment rules and alarms"},
    {"id": "q-f202-s15-046", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A BiPAP patient on 10/5 needs better oxygenation but has normal CO₂. What is the NBRC answer?", "choices": ["Raise both equally to 12/7", "Raise IPAP only to 15/5", "Lower both to 8/3", "Raise EPAP only to 10/7"], "correct": 0, "explanation": "Oxygenation only → raise both equally so ΔP stays the same.", "srcItem": "BiPAP settings, adjustment rules and alarms"},
    {"id": "q-f202-s15-047", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the BiPAP rule about raising EPAP?", "choices": ["Never raise EPAP without raising IPAP by the same amount", "Always raise EPAP alone", "EPAP should exceed IPAP", "EPAP is never adjusted"], "correct": 0, "explanation": "Raising EPAP alone shrinks PS; pressures change in increments of 2, and PS is never < 4.", "srcItem": "BiPAP settings, adjustment rules and alarms"},
    {"id": "q-f202-s15-048", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Where is the backup rate set in S/T mode?", "choices": ["Two to five breaths below the patient's spontaneous rate", "Above the patient's rate", "At zero", "Equal to the patient's rate"], "correct": 0, "explanation": "S/T backup rate: 2–5 breaths below the spontaneous RR.", "srcItem": "BiPAP settings, adjustment rules and alarms"},
    {"id": "q-f202-s15-049", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which NIV interface would NOT be recommended for BiPAP per the RCP 105 deck?", "choices": ["Nasal pillows", "Oronasal mask", "Full-face mask", "Nasal mask"], "correct": 0, "explanation": "Nasal pillows are smallest and most comfortable, but \"would NOT be recommended for BiPAP.\"", "srcItem": "NIV interfaces: advantages and disadvantages"},
    {"id": "q-f202-s15-050", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the biggest complication of a nasal mask?", "choices": ["Leakage in mouth-breathers", "Claustrophobia", "Aspiration", "Increased dead space"], "correct": 0, "explanation": "Nasal masks have less aspiration risk and dead space, but leak in mouth-breathers; try a chin strap.", "srcItem": "NIV interfaces: advantages and disadvantages"},
    {"id": "q-f202-s15-051", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How tight should NIV headgear be?", "choices": ["Loose enough to pass one or two fingers underneath", "As tight as possible to stop all leak", "Loose enough to fall off", "It should not be used"], "correct": 0, "explanation": "Hess: pass one or two fingers under the headgear; pressure sores on the nasal bridge are common.", "srcItem": "NIV interfaces: advantages and disadvantages"},
    {"id": "q-f202-s15-052", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does HiVNI stand for?", "choices": ["High Velocity Nasal Insufflation", "High Volume Noninvasive Inflation", "Humidified Inspiratory Ventilation Interface", "Heated Inline Ventilator Nebulizer"], "correct": 0, "explanation": "HiVNI = High Velocity Nasal Insufflation (Vapotherm); Airvo is Fisher & Paykel's home HFNC.", "srcItem": "Vapotherm HiVNI and the Airvo"},
    {"id": "q-f202-s15-053", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why does Vapotherm use a small-bore cannula?", "choices": ["It gives high velocity and leaves room around the prongs for exhaled gas to escape", "It delivers less flow", "It seals the nostrils completely", "It lowers the FiO₂"], "correct": 0, "explanation": "Narrow ID → high velocity; small OD leaves room for egress, flushing CO₂ from dead space.", "srcItem": "Vapotherm HiVNI and the Airvo"},
    {"id": "q-f202-s15-054", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Can the Airvo deliver high flow without added oxygen?", "choices": ["Yes — heated, humidified room air at high flow", "No — it always delivers 100% O₂", "No — it needs a ventilator", "Only at 2 L/min"], "correct": 0, "explanation": "High flow is not the same as high O₂; Airvo can give room air or an O₂-enriched mix.", "srcItem": "Vapotherm HiVNI and the Airvo"},
    {"id": "q-f202-s15-055", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does mouthpiece ventilation work during the day?", "choices": ["The patient takes assisted breaths from a mouthpiece on a flexible arm as needed", "The patient wears a full-face mask all day", "It requires a tracheostomy", "It delivers breaths only during sleep"], "correct": 0, "explanation": "Daytime MPV lets the patient talk, eat and stay active; a mask is used at night.", "srcItem": "Mouthpiece ventilation and air stacking"},
    {"id": "q-f202-s15-056", "topic": "f202-s15", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does air stacking improve?", "choices": ["Inspiratory capacity and peak cough flow", "Expiratory reserve only", "Gastric emptying", "Heart rate"], "correct": 0, "explanation": "Stacked breaths held with a closed glottis raise IC and peak cough flow and combat atelectasis.", "srcItem": "Mouthpiece ventilation and air stacking"},
    {"id": "q-f202-s16-001", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which bedside finding fits pneumonia with consolidation?", "choices": ["Dull percussion with bronchial breath sounds", "Hyperresonance with absent breath sounds", "Normal percussion with wheezes only", "Tympany with stridor"], "correct": 0, "explanation": "RCP 103: dull over consolidation; crackles, bronchial breath sounds, whispered pectoriloquy.", "srcItem": "Signs and symptoms of pneumonia"},
    {"id": "q-f202-s16-002", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does the pneumonia cough typically change?", "choices": ["Starts dry and hacking, then becomes productive", "Starts productive, then becomes dry", "Always stays dry", "Is always bloody from the start"], "correct": 0, "explanation": "Dry and hacking, then productive (yellow/green), possibly rust-colored or blood-streaked.", "srcItem": "Signs and symptoms of pneumonia"},
    {"id": "q-f202-s16-003", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What fever pattern does the RCP 103 deck give for bacterial vs viral pneumonia?", "choices": ["Bacterial > 101 °F; viral < 101 °F", "Bacterial < 99 °F; viral > 103 °F", "Both always > 104 °F", "Neither causes fever"], "correct": 0, "explanation": "Bacterial pneumonia > 101 °F; viral < 101 °F.", "srcItem": "Signs and symptoms of pneumonia"},
    {"id": "q-f202-s16-004", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which lab finding is listed in Hess Box 36-1 for pneumonia?", "choices": ["Leukocytosis or increased bands", "Polycythemia", "Low BUN", "Hypercalcemia"], "correct": 0, "explanation": "Lab: leukocytosis, ↑ bands, or leukopenia.", "srcItem": "Signs and symptoms of pneumonia"},
    {"id": "q-f202-s16-005", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How is pneumonia diagnosed according to Hess?", "choices": ["Clinically — no single test can diagnose it", "By a single blood culture", "By CRP alone", "By spirometry"], "correct": 0, "explanation": "\"Pneumonia is a clinical diagnosis... no single test can diagnose pneumonia.\"", "srcItem": "How pneumonia is diagnosed"},
    {"id": "q-f202-s16-006", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does a CBC show in bacterial vs viral pneumonia?", "choices": ["↑ WBC in bacterial; normal or ↓ WBC in viral", "↓ WBC in bacterial; ↑ WBC in viral", "Always normal", "↑ platelets only"], "correct": 0, "explanation": "RCP 103: ↑ WBC bacterial, ↓ (or normal) WBC viral.", "srcItem": "How pneumonia is diagnosed"},
    {"id": "q-f202-s16-007", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is 'the cornerstone' of microbiologic diagnosis of pneumonia?", "choices": ["Sputum Gram stain and culture", "Serology", "Chest CT", "Procalcitonin"], "correct": 0, "explanation": "Hess: sputum Gram stain and culture; positive ≥ 10⁶ CFU/mL.", "srcItem": "How pneumonia is diagnosed"},
    {"id": "q-f202-s16-008", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which ABG pattern is seen early in pneumonia?", "choices": ["Respiratory alkalosis with hypoxemia", "Respiratory acidosis with normal PaO₂", "Metabolic alkalosis", "Normal ABG"], "correct": 0, "explanation": "Early: respiratory alkalosis with hypoxemia; severe disease → respiratory acidosis.", "srcItem": "How pneumonia is diagnosed"},
    {"id": "q-f202-s16-009", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is procalcitonin mainly used for in pneumonia?", "choices": ["Guiding when to stop antibiotics", "Diagnosing viral pneumonia", "Measuring oxygenation", "Staging lung cancer"], "correct": 0, "explanation": "Procalcitonin rises in bacterial but not viral infection; its main use is stopping antibiotics.", "srcItem": "How pneumonia is diagnosed"},
    {"id": "q-f202-s16-010", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How is hospital-acquired pneumonia defined?", "choices": ["Onset ≥ 48 hours after admission and not incubating at admission", "Onset within 24 hours of admission", "Any pneumonia in a nursing home", "Pneumonia only after surgery"], "correct": 0, "explanation": "HAP = ≥ 48 hours after admission, not present at admission.", "srcItem": "Categories of pneumonia"},
    {"id": "q-f202-s16-011", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the most common bacterial cause of community-acquired pneumonia?", "choices": ["Streptococcus pneumoniae", "Pseudomonas aeruginosa", "Acinetobacter", "MRSA"], "correct": 0, "explanation": "S. pneumoniae is the most common CAP bacterium.", "srcItem": "Categories of pneumonia"},
    {"id": "q-f202-s16-012", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "For the exam, how is VAP timing defined?", "choices": ["≥ 48 hours after intubation", "Within 12 hours of intubation", "After 30 days of ventilation", "Before intubation"], "correct": 0, "explanation": "Use \"≥ 48 hours after intubation\"; the RCP 105 slide's \"within 48 hours\" is contradicted by its notes.", "srcItem": "Categories of pneumonia"},
    {"id": "q-f202-s16-013", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What happened to the HCAP (healthcare-associated pneumonia) category?", "choices": ["It was retired in 2016", "It was expanded to include all patients", "It replaced CAP", "It became the same as VAP"], "correct": 0, "explanation": "Hess: HCAP was retired in 2016 and is no longer separate from HAP.", "srcItem": "Categories of pneumonia"},
    {"id": "q-f202-s16-014", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which is the 'most important chronic pneumonia pathogen'?", "choices": ["Mycobacterium tuberculosis", "Streptococcus pneumoniae", "Influenza A", "Mycoplasma"], "correct": 0, "explanation": "TB is the most important chronic pneumonia pathogen, with fungi such as Histoplasma.", "srcItem": "Categories of pneumonia"},
    {"id": "q-f202-s16-015", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why is atypical pneumonia called 'atypical'?", "choices": ["The organism escapes standard bacteriologic tests and there is no consolidation", "It always affects children", "It causes very high WBC counts", "It is always fatal"], "correct": 0, "explanation": "Atypical: escapes standard tests, moderate sputum, no consolidation, only moderate WBC rise.", "srcItem": "Atypical pneumonia"},
    {"id": "q-f202-s16-016", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the most common cause of atypical pneumonia?", "choices": ["Mycoplasma pneumoniae", "Legionella", "Chlamydia psittaci", "Coxiella burnetii"], "correct": 0, "explanation": "Mycoplasma causes \"walking pneumonia,\" common in crowded settings.", "srcItem": "Atypical pneumonia"},
    {"id": "q-f202-s16-017", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why don't penicillins work against Mycoplasma pneumoniae?", "choices": ["It lacks a cell wall", "It is a virus", "It is resistant to all drugs", "It lives only in water"], "correct": 0, "explanation": "Mycoplasma is the smallest free-living organism and lacks a cell wall.", "srcItem": "Atypical pneumonia"},
    {"id": "q-f202-s16-018", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does the RCP 104 deck call the 'go-to' for atypical pneumonia?", "choices": ["Macrolides such as azithromycin", "Penicillin", "Vancomycin", "Aminoglycosides"], "correct": 0, "explanation": "\"Atypical pneumonia? → Think macrolide\"; doxycycline is also strong atypical coverage.", "srcItem": "Atypical pneumonia"},
    {"id": "q-f202-s16-019", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does the chest radiograph typically show in atypical pneumonia?", "choices": ["Diffuse interstitial or peribronchial opacities", "Lobar consolidation with air bronchograms", "A large pleural effusion only", "A normal film always"], "correct": 0, "explanation": "Typical: lobar consolidation; atypical: diffuse interstitial opacities.", "srcItem": "Atypical pneumonia"},
    {"id": "q-f202-s16-020", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Where does Legionella pneumophila live?", "choices": ["Water systems such as showers, fountains and mist machines", "Bird droppings", "Livestock dust", "Soil only"], "correct": 0, "explanation": "Legionella colonizes water systems; aerosolized bacteria cause Legionnaires disease.", "srcItem": "Legionella infections"},
    {"id": "q-f202-s16-021", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which atypical organism is most likely to lead to ARDS?", "choices": ["Legionella", "Mycoplasma", "Chlamydophila pneumoniae", "Coxiella burnetii"], "correct": 0, "explanation": "Hess: of the atypical organisms, Legionella is most likely to lead to ARDS.", "srcItem": "Legionella infections"},
    {"id": "q-f202-s16-022", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is a limitation of the Legionella urinary antigen test?", "choices": ["It detects only serogroup 1", "It is affected by antibiotics", "It takes 6 weeks", "It has very low specificity"], "correct": 0, "explanation": "Sensitivity 70–90%, specificity ~99%, but only serogroup 1 — up to 20% test falsely negative.", "srcItem": "Legionella infections"},
    {"id": "q-f202-s16-023", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why are ventilator humidifiers filled with sterile water?", "choices": ["To keep out heat-resistant organisms such as Legionella", "To raise the humidity", "To prevent condensation", "To lower the FiO₂"], "correct": 0, "explanation": "Legionella in hospital tap water has caused epidemic VAP.", "srcItem": "Legionella infections"},
    {"id": "q-f202-s16-024", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is first-line treatment for Legionella?", "choices": ["A fluoroquinolone or a macrolide", "Penicillin alone", "Antifungals", "Antivirals"], "correct": 0, "explanation": "Hess: fluoroquinolone or macrolide.", "srcItem": "Legionella infections"},
    {"id": "q-f202-s16-025", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Per the instructor's RCP 203 deck, which oral care is part of the CDC VAP bundle?", "choices": ["Daily oral care with chlorhexidine", "Oral care only once a week", "Oral nystatin", "No oral care"], "correct": 0, "explanation": "Exam answer: daily chlorhexidine oral care (Hess's newer bundle says \"no longer recommended\").", "srcItem": "Chlorhexidine"},
    {"id": "q-f202-s16-026", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What head-of-bed elevation is part of the VAP bundle?", "choices": ["30° to 45°", "0° (flat)", "10°", "90°"], "correct": 0, "explanation": "HOB 30–45° unless contraindicated.", "srcItem": "Chlorhexidine"},
    {"id": "q-f202-s16-027", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which ETT feature helps prevent VAP?", "choices": ["Subglottic suction that removes pooled secretions above the cuff", "A smaller cuff", "No cuff at all", "A nasal route"], "correct": 0, "explanation": "Subglottic ETTs continuously remove secretions; use the oral route and avoid nasal intubation.", "srcItem": "Chlorhexidine"},
    {"id": "q-f202-s16-028", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What cuff pressure helps prevent VAP?", "choices": ["20–30 cm H₂O", "5–10 cm H₂O", "40–50 cm H₂O", "As low as possible with a minimal leak"], "correct": 0, "explanation": "Cuff pressure 20–30 cm H₂O; avoid the minimal leak technique.", "srcItem": "Chlorhexidine"},
    {"id": "q-f202-s16-029", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Besides oral care, what is chlorhexidine used for in these sources?", "choices": ["Skin antisepsis before an arterial line or thoracentesis", "Treating Legionella", "Nebulized bronchodilation", "Reversing sedation"], "correct": 0, "explanation": "Scrub the insertion site with chlorhexidine before an arterial line; used before thoracentesis too.", "srcItem": "Chlorhexidine"},
    {"id": "q-f202-s16-030", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "According to the deck's clinical pearl, what is the single greatest risk factor for VAP?", "choices": ["Prolonged mechanical ventilation", "The ventilator's brand", "High FiO₂", "Low PEEP"], "correct": 0, "explanation": "Deck: prolonged MV is the single greatest risk factor; the ETT is the pathway.", "srcItem": "Ventilator-associated pneumonia"},
    {"id": "q-f202-s16-031", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the most important bedside finding of VAP?", "choices": ["Purulent tracheobronchial secretions", "Low blood pressure", "Bradycardia", "Dry skin"], "correct": 0, "explanation": "Clinical VAP: fever, leukocytosis/leukopenia, purulent secretions, new infiltrate.", "srcItem": "Ventilator-associated pneumonia"},
    {"id": "q-f202-s16-032", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which organisms cause late-onset (> 4–5 days) VAP?", "choices": ["MRSA, Pseudomonas and Acinetobacter", "S. pneumoniae and H. influenzae", "Mycoplasma", "Influenza only"], "correct": 0, "explanation": "Late-onset or MDR risk: MRSA, Pseudomonas, Acinetobacter, Stenotrophomonas, ESBL organisms.", "srcItem": "Ventilator-associated pneumonia"},
    {"id": "q-f202-s16-033", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the primary mechanism of VAP?", "choices": ["Microaspiration of secretions pooled above the cuff", "Inhaling contaminated ventilator gas", "Bloodstream spread", "Spread from the skin"], "correct": 0, "explanation": "The ETT bypasses defenses; microaspiration around the cuff is the primary mechanism.", "srcItem": "Ventilator-associated pneumonia"},
    {"id": "q-f202-s16-034", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How long is the 2016 IDSA/ATS antibiotic course for VAP?", "choices": ["7 days", "3 days", "21 days", "6 weeks"], "correct": 0, "explanation": "7 days for VAP and ≤ 7 days for HAP; de-escalate when cultures return.", "srcItem": "Ventilator-associated pneumonia"},
    {"id": "q-f202-s16-035", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does aspiration pneumonitis differ from aspiration pneumonia?", "choices": ["Pneumonitis is a non-infectious chemical injury from gastric contents", "Pneumonitis is always bacterial", "Pneumonia is always non-infectious", "They are identical"], "correct": 0, "explanation": "Pneumonitis is chemical (gastric acid); aspiration pneumonia can be toxic, obstructive or infectious.", "srcItem": "Aspiration pneumonia vs aspiration pneumonitis"},
    {"id": "q-f202-s16-036", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Aspiration of gastric fluid with what pH is 'often fatal'?", "choices": ["pH ≤ 2.5", "pH 7.4", "pH 8.0", "pH 6.0"], "correct": 0, "explanation": "RCP 103: aspiration of gastric fluid with pH ≤ 2.5 is often fatal.", "srcItem": "Aspiration pneumonia vs aspiration pneumonitis"},
    {"id": "q-f202-s16-037", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is Mendelson's syndrome?", "choices": ["Tachycardia, dyspnea and cyanosis after acid aspiration, usually in pregnant women", "Pneumonia from bird droppings", "A fungal lung infection", "Legionella outbreak"], "correct": 0, "explanation": "Mendelson's syndrome follows acid aspiration, usually in pregnancy.", "srcItem": "Aspiration pneumonia vs aspiration pneumonitis"},
    {"id": "q-f202-s16-038", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which antibiotic does RCP 104 link with aspiration pneumonia?", "choices": ["Clindamycin", "Azithromycin", "Isoniazid", "Acyclovir"], "correct": 0, "explanation": "\"Aspiration pneumonia → clindamycin\" (anaerobic coverage).", "srcItem": "Aspiration pneumonia vs aspiration pneumonitis"},
    {"id": "q-f202-s16-039", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does CURB-65 stand for?", "choices": ["Confusion, BUN ≥ 20, RR ≥ 30, low BP, age ≥ 65", "Cough, Uremia, Rales, Bradycardia, age 65", "Cyanosis, Urine output, Rate, Blood gas, 65 kg", "Crackles, Upper lobe, Radiograph, Breath sounds, 65%"], "correct": 0, "explanation": "1 point each: Confusion, BUN ≥ 20, RR ≥ 30, SBP < 90 or DBP ≤ 60, age ≥ 65.", "srcItem": "CAP severity scoring"},
    {"id": "q-f202-s16-040", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A CAP patient has a CURB-65 score of 3. What is the likely disposition?", "choices": ["Hospitalization and possibly ICU", "Outpatient treatment", "Discharge without antibiotics", "Home oxygen only"], "correct": 0, "explanation": "0–1 outpatient; 2 hospitalization; ≥ 3 hospital and possibly ICU.", "srcItem": "CAP severity scoring"},
    {"id": "q-f202-s16-041", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Who should receive annual influenza vaccination?", "choices": ["Everyone older than 6 months", "Only adults over 65", "Only healthcare workers", "Only children"], "correct": 0, "explanation": "Hess: annual influenza vaccination for everyone older than 6 months.", "srcItem": "CAP severity scoring"},
    {"id": "q-f202-s16-042", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which pneumococcal vaccines does Hess name?", "choices": ["PCV13 and PPSV23", "MMR and DTaP", "BCG and HPV", "Hib and IPV"], "correct": 0, "explanation": "PCV13 (13 serotypes) and PPSV23 (23 serotypes).", "srcItem": "CAP severity scoring"},
    {"id": "q-f202-s16-043", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What place does pneumonia hold among postoperative complications?", "choices": ["Third most common", "Most common", "Rarely seen", "Fifth most common"], "correct": 0, "explanation": "Pneumonia is the third most common postoperative complication.", "srcItem": "Postoperative Pneumonia"},
    {"id": "q-f202-s16-044", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A postoperative patient has atelectasis and a fever. What does the fever suggest?", "choices": ["Infection from retained secretions — atelectasis alone does not cause fever", "Atelectasis is the cause of the fever", "Normal post-surgical recovery", "Pulmonary embolism only"], "correct": 0, "explanation": "Hess: atelectasis without infection does not result in fever; look for the infection.", "srcItem": "Postoperative Pneumonia"},
    {"id": "q-f202-s16-045", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which lobe is the most common site of clinically significant atelectasis after abdominal surgery?", "choices": ["Left lower lobe", "Right upper lobe", "Right middle lobe", "Left upper lobe"], "correct": 0, "explanation": "Clinically significant atelectasis after abdominal surgery runs 15–20%; LLL is most common.", "srcItem": "Postoperative Pneumonia"},
    {"id": "q-f202-s16-046", "topic": "f202-s16", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What contributes to alveolar collapse during general anesthesia?", "choices": ["High oxygen concentrations above 40%", "Low FiO₂ of 21%", "Hyperventilation", "Upright positioning"], "correct": 0, "explanation": "20–25% of basal lung collapses after induction; FiO₂ > 40% contributes.", "srcItem": "Postoperative Pneumonia"},
    {"id": "q-f202-s17-001", "topic": "f202-s17", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is atelectrauma?", "choices": ["Injury from repetitive opening and closing of alveoli", "Injury from too much volume", "Injury from too much pressure causing air leak", "Inflammatory cytokine release"], "correct": 0, "explanation": "Atelectrauma = repetitive collapse and re-opening (shear stress); prevented by PEEP and recruitment.", "srcItem": "Atelectrauma vs Biotrauma vs \"Pneumotrauma\""},
    {"id": "q-f202-s17-002", "topic": "f202-s17", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is volutrauma, and how is it prevented?", "choices": ["Overstretching from too much volume; prevented by low VT (~6 mL/kg PBW)", "Rupture from too much pressure; prevented by high PEEP", "Collapse of alveoli; prevented by higher VT", "Infection from the ETT; prevented by antibiotics"], "correct": 0, "explanation": "Deck: \"too much volume\" overstretches healthy alveoli; \"Lower VT → reduce volutrauma.\"", "srcItem": "Atelectrauma vs Biotrauma vs \"Pneumotrauma\""},
    {"id": "q-f202-s17-003", "topic": "f202-s17", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "On this exam, what does the instructor's term 'pneumotrauma' mean?", "choices": ["Barotrauma — rupture and air leak from too much pressure", "Pneumonia from the ventilator", "Pneumothorax from trauma only", "Atelectrauma"], "correct": 0, "explanation": "No source uses \"pneumotrauma\"; read it as barotrauma (pneumothorax, subcutaneous emphysema).", "srcItem": "Atelectrauma vs Biotrauma vs \"Pneumotrauma\""},
    {"id": "q-f202-s17-004", "topic": "f202-s17", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is biotrauma?", "choices": ["The inflammatory cytokine response to ventilator-induced lung injury", "Bacterial infection from the ventilator", "Rupture of alveoli", "Oxygen toxicity only"], "correct": 0, "explanation": "Hess: VILI increases inflammatory cytokines that can spill into the blood and contribute to multiorgan dysfunction.", "srcItem": "Atelectrauma vs Biotrauma vs \"Pneumotrauma\""},
    {"id": "q-f202-s17-005", "topic": "f202-s17", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does the deck summarize lung-protective strategy?", "choices": ["Low VT prevents overdistention and PEEP prevents collapse — we need both", "High VT and zero PEEP", "High PEEP alone is enough", "Low VT alone is enough"], "correct": 0, "explanation": "\"Low VT protects the alveoli from overdistention. PEEP helps prevent them from collapsing. We need both!\"", "srcItem": "Atelectrauma vs Biotrauma vs \"Pneumotrauma\""},
    {"id": "q-f202-s17-006", "topic": "f202-s17", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How was ALI defined by the AECC?", "choices": ["P/F less than 300 but greater than 200", "P/F less than 100", "P/F greater than 400", "P/F less than 50"], "correct": 0, "explanation": "AECC: ALI P/F 201–300; ARDS < 200. The Berlin definition eliminated the term ALI.", "srcItem": "Rates of Mortality for Acute Lung Injury (ALI)"},
    {"id": "q-f202-s17-007", "topic": "f202-s17", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What proportion of ALI/ARDS patients die primarily of refractory hypoxemia?", "choices": ["Only 10–15%", "About 90%", "About 50%", "None"], "correct": 0, "explanation": "Most deaths are from nonpulmonary organ failure; only 10–15% die of refractory hypoxemia.", "srcItem": "Rates of Mortality for Acute Lung Injury (ALI)"},
    {"id": "q-f202-s17-008", "topic": "f202-s17", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In the ARDSnet trial, what was mortality with 6 mL/kg vs 12 mL/kg tidal volumes?", "choices": ["31% vs 40%", "40% vs 31%", "10% vs 60%", "50% vs 50%"], "correct": 0, "explanation": "Low VT (6 mL/kg) reduced mortality to 31% from 40% with 12 mL/kg.", "srcItem": "Rates of Mortality for Acute Lung Injury (ALI)"},
    {"id": "q-f202-s17-009", "topic": "f202-s17", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Where does the majority of ARDS mortality occur?", "choices": ["In the setting of sepsis or multisystem organ failure", "From respiratory failure alone", "From pneumothorax", "From oxygen toxicity"], "correct": 0, "explanation": "Hess: only ~15% die from respiratory failure; most deaths come with sepsis or MOF.", "srcItem": "Rates of Mortality for Acute Lung Injury (ALI)"},
    {"id": "q-f202-s17-010", "topic": "f202-s17", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which patients have the highest risk of developing ARDS?", "choices": ["Patients with sepsis (about 40% incidence)", "Patients with asthma", "Patients with stable COPD", "Healthy postoperative patients"], "correct": 0, "explanation": "Hess: sepsis is the highest-risk group (40% incidence); the deck calls it the most common cause.", "srcItem": "Patients with the Highest Incidence of ARDS"},
    {"id": "q-f202-s17-011", "topic": "f202-s17", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which is a DIRECT (primary) cause of ARDS?", "choices": ["Aspiration of gastric contents", "Sepsis", "Acute pancreatitis", "Blood transfusion"], "correct": 0, "explanation": "Direct: pneumonia, aspiration, contusion, inhalation injury. Indirect: sepsis, trauma with shock, transfusion, pancreatitis.", "srcItem": "Patients with the Highest Incidence of ARDS"},
    {"id": "q-f202-s17-012", "topic": "f202-s17", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "About what fraction of patients with a witnessed aspiration develop ARDS?", "choices": ["About one-third", "Nearly all", "About 1%", "About 90%"], "correct": 0, "explanation": "ARDS deck notes: about one-third of witnessed aspiration events lead to ARDS.", "srcItem": "Patients with the Highest Incidence of ARDS"},
    {"id": "q-f202-s17-013", "topic": "f202-s17", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How soon after the inciting event do ARDS signs typically appear?", "choices": ["6–72 hours", "2–3 weeks", "Within 1 minute", "After 6 months"], "correct": 0, "explanation": "Clinical signs appear 6–72 hours after the insult and progress rapidly.", "srcItem": "Patients with the Highest Incidence of ARDS"},
    {"id": "q-f202-s17-014", "topic": "f202-s17", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does increased alveolar-capillary permeability in ARDS produce?", "choices": ["Noncardiogenic pulmonary edema", "Cardiogenic pulmonary edema", "Emphysema", "Pleural thickening only"], "correct": 0, "explanation": "Inflammation → ↑ permeability → protein-rich fluid leaks → noncardiogenic edema.", "srcItem": "What Causes Decreased Lung Compliance in ARDS"},
    {"id": "q-f202-s17-015", "topic": "f202-s17", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why is surfactant lost in ARDS?", "choices": ["Type II cells are damaged and protein-rich edema inactivates surfactant", "Surfactant is overproduced", "Type I cells produce too much", "Oxygen therapy creates surfactant"], "correct": 0, "explanation": "Type II cell apoptosis/necrosis and protein-rich edema reduce surfactant → atelectasis.", "srcItem": "What Causes Decreased Lung Compliance in ARDS"},
    {"id": "q-f202-s17-016", "topic": "f202-s17", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What are hyaline membranes in ARDS?", "choices": ["Fibrin and cellular debris lining the alveolar walls", "Healthy surfactant layers", "Calcium deposits", "Mucus plugs in bronchi"], "correct": 0, "explanation": "Hyaline membranes increase stiffness and decrease compliance.", "srcItem": "What Causes Decreased Lung Compliance in ARDS"},
    {"id": "q-f202-s17-017", "topic": "f202-s17", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What breathing pattern results from stiff ARDS lungs?", "choices": ["Rapid, shallow breathing with increased WOB", "Slow, deep breathing", "Normal breathing", "Apnea"], "correct": 0, "explanation": "Smaller VT forces a faster rate; minute ventilation and WOB rise.", "srcItem": "What Causes Decreased Lung Compliance in ARDS"},
    {"id": "q-f202-s17-018", "topic": "f202-s17", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What PFT pattern does ARDS produce?", "choices": ["Restrictive — volumes decreased, FEV₁/FVC normal or increased", "Obstructive — FEV₁/FVC decreased", "Normal pattern", "Mixed pattern with high TLC"], "correct": 0, "explanation": "ARDS is a restrictive disorder: ↓ volumes and capacities, FEV₁/FVC normal or ↑.", "srcItem": "What Causes Decreased Lung Compliance in ARDS"},
    {"id": "q-f202-s17-019", "topic": "f202-s17", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Using the Berlin categories for this exam, a P/F of 150 is classified as what?", "choices": ["Moderate ARDS (101–200)", "Mild ARDS", "Severe ARDS", "Normal"], "correct": 0, "explanation": "Use 201–300 mild, 101–200 moderate, ≤ 100 severe.", "srcItem": "Berlin Definition and P/F Severity Categories"},
    {"id": "q-f202-s17-020", "topic": "f202-s17", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A patient's PaO₂ is 58 mm Hg on FiO₂ 0.60. What is the P/F and classification?", "choices": ["About 97 — severe ARDS", "About 350 — normal", "About 180 — moderate ARDS", "About 250 — mild ARDS"], "correct": 0, "explanation": "58 ÷ 0.60 ≈ 97 → severe (≤ 100); rule out hypoventilation first.", "srcItem": "Berlin Definition and P/F Severity Categories"},
    {"id": "q-f202-s17-021", "topic": "f202-s17", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "At what minimum PEEP is oxygenation graded under the Berlin definition?", "choices": ["At least 5 cm H₂O of PEEP or CPAP", "Zero PEEP", "At least 15 cm H₂O", "Any PEEP"], "correct": 0, "explanation": "P/F is measured with at least 5 cm H₂O of PEEP or CPAP.", "srcItem": "Berlin Definition and P/F Severity Categories"},
    {"id": "q-f202-s17-022", "topic": "f202-s17", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does a PCWP above 18 mm Hg suggest under the older AECC definition?", "choices": ["Cardiogenic pulmonary edema rather than ARDS", "ARDS", "Pneumothorax", "Normal fluid status"], "correct": 0, "explanation": "AECC used PCWP ≤ 18 to exclude a cardiogenic cause.", "srcItem": "Berlin Definition and P/F Severity Categories"},
    {"id": "q-f202-s17-023", "topic": "f202-s17", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the Berlin timing criterion for ARDS?", "choices": ["Onset within 1 week of a known insult or new/worsening symptoms", "Onset over 6 months", "Onset within 1 hour", "No timing requirement"], "correct": 0, "explanation": "Berlin: within 1 week; bilateral opacities; not fully explained by cardiac failure; graded by P/F.", "srcItem": "Berlin Definition and P/F Severity Categories"},
    {"id": "q-f202-s17-024", "topic": "f202-s17", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What tidal volume should be used in ARDS?", "choices": ["About 6 mL/kg predicted body weight", "12 mL/kg actual weight", "10 mL/kg ideal weight", "2 mL/kg"], "correct": 0, "explanation": "\"If you remember one number for ARDS, remember 6 mL/kg.\"", "srcItem": "Lung-Protective Ventilation for ARDS"},
    {"id": "q-f202-s17-025", "topic": "f202-s17", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What driving pressure target does Hess give for ARDS?", "choices": ["15 cm H₂O or less", "30 cm H₂O or more", "5 cm H₂O exactly", "25 cm H₂O"], "correct": 0, "explanation": "Hess Key Points: VT 6 mL/kg, driving pressure ≤ 15, Pplat < 30.", "srcItem": "Lung-Protective Ventilation for ARDS"},
    {"id": "q-f202-s17-026", "topic": "f202-s17", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What oxygenation goals does the deck give for ARDS?", "choices": ["PaO₂ 55–80 mm Hg, SpO₂ 88–95%", "PaO₂ > 150 mm Hg, SpO₂ 100%", "PaO₂ 40–50 mm Hg", "SpO₂ 80–85%"], "correct": 0, "explanation": "Procedures deck: PaO₂ 55–80, SpO₂ 88–95%.", "srcItem": "Lung-Protective Ventilation for ARDS"},
    {"id": "q-f202-s17-027", "topic": "f202-s17", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is permissive hypercapnia in ARDS?", "choices": ["Allowing PaCO₂ above 50 mm Hg with low VT, as long as pH ≥ 7.25", "Hyperventilating to PaCO₂ 25", "Keeping PaCO₂ exactly 40", "Giving bicarbonate to all patients"], "correct": 0, "explanation": "Low VT (4–7 mL/kg) with PaCO₂ allowed > 50; Burn deck: pH ≥ 7.25.", "srcItem": "Lung-Protective Ventilation for ARDS"},
    {"id": "q-f202-s17-028", "topic": "f202-s17", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How long should severe ARDS patients be placed prone (Hess)?", "choices": ["More than 12 hours per day", "15 minutes per day", "Only at night for 2 hours", "Never"], "correct": 0, "explanation": "Proning > 12 h/day; with P/F < 150 it reduced absolute mortality by 16.8%.", "srcItem": "Lung-Protective Ventilation for ARDS"},
    {"id": "q-f202-s17-029", "topic": "f202-s17", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Should ARDS patients in respiratory failure be tried on NIV first?", "choices": ["No — place them on invasive ventilation with full support", "Yes — always try NIV first", "Yes — for 24 hours", "Only with a nasal mask"], "correct": 0, "explanation": "Deck: invasive full support rather than a NIPPV trial; Hess agrees they are not NIV candidates.", "srcItem": "Lung-Protective Ventilation for ARDS"},
    {"id": "q-f202-s18-001", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How does acetylcysteine (Mucomyst) reduce mucus viscosity?", "choices": ["Its free sulfhydryl groups break disulfide bonds in mucoproteins", "It dilates the bronchi", "It hydrates mucus by osmosis", "It kills bacteria in the mucus"], "correct": 0, "explanation": "NAC substitutes free thiol groups for disulfide bonds connecting mucin proteins.", "srcItem": "Acetylcysteine (N-Acetylcysteine, NAC, Mucomyst)"},
    {"id": "q-f202-s18-002", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the most important hazard of aerosolized acetylcysteine?", "choices": ["Bronchospasm, especially in asthmatics", "Tachycardia", "Hyperkalemia", "Hypoglycemia"], "correct": 0, "explanation": "Bronchospasm (less with 10%), nausea, rotten-egg odor, mechanical obstruction; give a bronchodilator first.", "srcItem": "Acetylcysteine (N-Acetylcysteine, NAC, Mucomyst)"},
    {"id": "q-f202-s18-003", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is acetylcysteine's most important use today?", "choices": ["Antidote for acetaminophen overdose to protect the liver", "Routine mucolytic for COPD", "Treatment of status asthmaticus", "Reversal of opioids"], "correct": 0, "explanation": "\"NAC saves the liver!\" — very testable. Routine aerosolized NAC for airway clearance is not recommended.", "srcItem": "Acetylcysteine (N-Acetylcysteine, NAC, Mucomyst)"},
    {"id": "q-f202-s18-004", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "When giving acetylcysteine with a bronchodilator, which is given first?", "choices": ["The bronchodilator, always", "The acetylcysteine", "Both mixed together", "It doesn't matter"], "correct": 0, "explanation": "Pharm Ch 9: about 10–15 minutes between drugs, and the bronchodilator is ALWAYS given first.", "srcItem": "Acetylcysteine (N-Acetylcysteine, NAC, Mucomyst)"},
    {"id": "q-f202-s18-005", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What odor is associated with acetylcysteine?", "choices": ["Sulfur (rotten egg)", "Sweet fruit", "Almonds", "None"], "correct": 0, "explanation": "NAC has a strong hydrogen sulfide (rotten egg) smell.", "srcItem": "Acetylcysteine (N-Acetylcysteine, NAC, Mucomyst)"},
    {"id": "q-f202-s18-006", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the critical rule about neuromuscular blocking agents?", "choices": ["They do not sedate or relieve pain — give analgesia, then sedation, then the paralytic", "They provide full sedation", "They relieve pain", "They stimulate breathing"], "correct": 0, "explanation": "\"Paralysis ≠ sedation\"; order: analgesia → sedation → paralytic, and the patient must be ventilated.", "srcItem": "Neuromuscular Blocking Agents"},
    {"id": "q-f202-s18-007", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which is the only depolarizing neuromuscular blocker?", "choices": ["Succinylcholine", "Vecuronium", "Rocuronium", "Cisatracurium"], "correct": 0, "explanation": "Succinylcholine is the only depolarizing NMBA; it causes fasciculations first.", "srcItem": "Neuromuscular Blocking Agents"},
    {"id": "q-f202-s18-008", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the most important complication of succinylcholine?", "choices": ["Hyperkalemia", "Hypokalemia", "Hypoglycemia", "Hypertension only"], "correct": 0, "explanation": "\"If you remember ONE complication\" — hyperkalemia; caution in burns, trauma, denervation.", "srcItem": "Neuromuscular Blocking Agents"},
    {"id": "q-f202-s18-009", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What reverses succinylcholine?", "choices": ["Nothing — you ride it out", "Neostigmine", "Sugammadex", "Naloxone"], "correct": 0, "explanation": "Succinylcholine has no reversal; adding ACh makes it worse.", "srcItem": "Neuromuscular Blocking Agents"},
    {"id": "q-f202-s18-010", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which agent reverses nondepolarizing NMBAs by letting more ACh compete at the receptor?", "choices": ["Neostigmine", "Succinylcholine", "Naloxone", "Flumazenil"], "correct": 0, "explanation": "Cholinesterase inhibitors (neostigmine, edrophonium, pyridostigmine); sugammadex reverses only rocuronium/vecuronium.", "srcItem": "Neuromuscular Blocking Agents"},
    {"id": "q-f202-s18-011", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which NMBA is the optimal choice in liver or kidney failure?", "choices": ["Cisatracurium (Hofmann degradation)", "Pancuronium", "Vecuronium", "Succinylcholine"], "correct": 0, "explanation": "Cisatracurium is degraded by body pH and temperature, independent of organs.", "srcItem": "Neuromuscular Blocking Agents"},
    {"id": "q-f202-s18-012", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How is pancuronium mainly eliminated?", "choices": ["By the kidneys ('Panc = pee')", "By the liver", "By plasma cholinesterase", "By the lungs"], "correct": 0, "explanation": "Pancuronium: kidneys; vecuronium: liver (\"Vec = liver\").", "srcItem": "Neuromuscular Blocking Agents"},
    {"id": "q-f202-s18-013", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What triggers malignant hyperthermia, and how is it treated?", "choices": ["Succinylcholine and volatile anesthetics; dantrolene", "Opioids; naloxone", "Benzodiazepines; flumazenil", "Propofol; neostigmine"], "correct": 0, "explanation": "Rising ETCO₂ comes before the fever; treat with dantrolene sodium.", "srcItem": "Neuromuscular Blocking Agents"},
    {"id": "q-f202-s18-014", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How do nondepolarizing NMBAs work?", "choices": ["They competitively block ACh at nicotinic receptors without activating them", "They depolarize the endplate like ACh", "They stimulate ACh release", "They block sodium channels in nerves"], "correct": 0, "explanation": "Competitive antagonists — no fasciculations; dose-related effect.", "srcItem": "Neuromuscular Blocking Agents"},
    {"id": "q-f202-s18-015", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the difference between sedation and analgesia?", "choices": ["Sedation diminishes awareness; analgesia relieves pain", "They are the same", "Sedation relieves pain; analgesia causes sleep", "Analgesia paralyzes muscles"], "correct": 0, "explanation": "\"Sedative ≠ Analgesic\": propofol/midazolam sedate; morphine/fentanyl relieve pain.", "srcItem": "Sedatives"},
    {"id": "q-f202-s18-016", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which sedative gives sedation, anxiolysis and some analgesia without respiratory depression?", "choices": ["Dexmedetomidine (Precedex)", "Midazolam", "Propofol", "Lorazepam"], "correct": 0, "explanation": "Dexmedetomidine, a selective α₂ agonist; it can be continued through extubation.", "srcItem": "Sedatives"},
    {"id": "q-f202-s18-017", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why is propofol called 'milk of amnesia', and what must be watched?", "choices": ["It is a lipid emulsion; watch for hypotension and rising triglycerides", "It is a water solution; watch for hypertension", "It is a gas; watch for fire", "It is a pill; watch for nausea"], "correct": 0, "explanation": "Propofol is a lipid emulsion (adds calories, raises triglycerides); watch BP, apnea, bradycardia.", "srcItem": "Sedatives"},
    {"id": "q-f202-s18-018", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which induction agent is the 'hemodynamically stable choice' for RSI?", "choices": ["Etomidate", "Propofol", "Midazolam at high dose", "Dexmedetomidine"], "correct": 0, "explanation": "Etomidate: onset 30–60 s, duration 3–5 min, no analgesia; airway deck calls it hemodynamically stable.", "srcItem": "Sedatives"},
    {"id": "q-f202-s18-019", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which sedative preserves respiratory drive and suits hypotension or bronchospasm?", "choices": ["Ketamine", "Propofol", "Midazolam", "Thiopental"], "correct": 0, "explanation": "Ketamine gives analgesia, amnesia and sedation with sympathetic stimulation; watch reemergence phenomena.", "srcItem": "Sedatives"},
    {"id": "q-f202-s18-020", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why must a patient sedated with propofol also receive an opioid for pain?", "choices": ["Propofol provides no meaningful analgesia", "Propofol causes pain", "Opioids reverse propofol", "Propofol requires a second sedative"], "correct": 0, "explanation": "Propofol gives analgesia only at high dose; Hess: it \"does not provide analgesia.\"", "srcItem": "Sedatives"},
    {"id": "q-f202-s18-021", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What do benzodiazepines do to opioid-induced respiratory depression?", "choices": ["They augment it", "They reverse it", "They have no effect", "They prevent it"], "correct": 0, "explanation": "Benzos alone cause little respiratory change, but they augment opioid respiratory depression.", "srcItem": "Sedatives"},
    {"id": "q-f202-s18-022", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does the deck call the #1 thing opioids can kill?", "choices": ["Breathing", "The heart", "The liver", "The kidneys"], "correct": 0, "explanation": "Respiratory depression is the most important opioid side effect.", "srcItem": "Opiates (Opioids)"},
    {"id": "q-f202-s18-023", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What reverses opioids?", "choices": ["Naloxone (Narcan)", "Flumazenil", "Neostigmine", "Dantrolene"], "correct": 0, "explanation": "Naloxone, which also comes as a nasal spray; withdrawal may appear within minutes in dependent patients.", "srcItem": "Opiates (Opioids)"},
    {"id": "q-f202-s18-024", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How much stronger is hydromorphone (Dilaudid) than morphine?", "choices": ["5–10 times", "About half as strong", "100 times", "Equal"], "correct": 0, "explanation": "Hydromorphone is 5–10× stronger than morphine.", "srcItem": "Opiates (Opioids)"},
    {"id": "q-f202-s18-025", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which opioid has an almost immediate onset and no histamine release with boluses?", "choices": ["Fentanyl", "Morphine", "Hydromorphone", "Codeine"], "correct": 0, "explanation": "Fentanyl: almost immediate onset; large boluses can cause muscle rigidity.", "srcItem": "Opiates (Opioids)"},
    {"id": "q-f202-s18-026", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "For a patient on a PCA opioid pump, what should be in the room at all times?", "choices": ["A bag-mask and naloxone", "A defibrillator only", "Flumazenil", "Dantrolene"], "correct": 0, "explanation": "CNS deck: keep a bag-mask and naloxone available for PCA patients.", "srcItem": "Opiates (Opioids)"},
    {"id": "q-f202-s18-027", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is a drug's plasma half-life?", "choices": ["The time for plasma concentration to fall by one-half", "The time to reach peak effect", "Half the dose given", "The duration of action"], "correct": 0, "explanation": "T½ = time for the plasma concentration to decrease by one-half.", "srcItem": "Half-Life of Medications"},
    {"id": "q-f202-s18-028", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why are older adults and patients with liver or kidney disease at greater risk of drug toxicity?", "choices": ["Drug half-lives are longer in these conditions", "Their drugs are absorbed faster", "They metabolize drugs too quickly", "They have more receptors"], "correct": 0, "explanation": "Hess: half-lives are longer with age and hepatic or renal impairment.", "srcItem": "Half-Life of Medications"},
    {"id": "q-f202-s18-029", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which drug has an extremely short half-life of about 12 seconds?", "choices": ["Adenosine", "Lorazepam", "Omalizumab", "Theophylline"], "correct": 0, "explanation": "Adenosine ~12 seconds (\"super short\").", "srcItem": "Half-Life of Medications"},
    {"id": "q-f202-s18-030", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which benzodiazepine has a much longer half-life?", "choices": ["Lorazepam compared with midazolam", "Midazolam compared with lorazepam", "They are identical", "Neither has a half-life"], "correct": 0, "explanation": "Hess: lorazepam has a much longer half-life than midazolam.", "srcItem": "Half-Life of Medications"},
    {"id": "q-f202-s18-031", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which route is 'parenteral'?", "choices": ["Intravenous", "Oral tablet", "Rectal suppository", "Sublingual"], "correct": 0, "explanation": "Parenteral = any route other than enteral (IV, IM, SubQ, IO, IT).", "srcItem": "Routes of Administration"},
    {"id": "q-f202-s18-032", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which is an advantage of the inhaled route?", "choices": ["Smaller dose with fewer side effects and rapid onset", "Always 100% bioavailable", "Requires no technique", "Avoids the lungs"], "correct": 0, "explanation": "Inhaled: smaller dose, fewer side effects, rapid onset, targets the lungs, painless.", "srcItem": "Routes of Administration"},
    {"id": "q-f202-s18-033", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why must nondepolarizing NMBAs be given IV?", "choices": ["They are poorly absorbed in the GI tract", "They cause vomiting", "They are inhaled gases", "They need the liver to activate"], "correct": 0, "explanation": "Nondepolarizing NMBAs are poorly absorbed orally, so IV only.", "srcItem": "Routes of Administration"},
    {"id": "q-f202-s18-034", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "On this exam, how is the intrathecal route classified?", "choices": ["Parenteral (the deck's classification)", "Enteral", "Topical", "Inhaled"], "correct": 0, "explanation": "The deck lists intrathecal as parenteral; Hess calls it percutaneous/mucosal. Use the deck.", "srcItem": "Routes of Administration"},
    {"id": "q-f202-s18-035", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does bioavailability indicate?", "choices": ["The proportion of a drug that reaches the systemic circulation", "How fast a drug is eliminated", "The drug's half-life", "The drug's cost"], "correct": 0, "explanation": "IV is the standard at 100% bioavailability.", "srcItem": "Bioavailability"},
    {"id": "q-f202-s18-036", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What does high first-pass metabolism do to an oral drug?", "choices": ["Reduces its bioavailability", "Increases its bioavailability", "Has no effect", "Makes it inhaled"], "correct": 0, "explanation": "The liver inactivates much of the drug before it reaches the circulation.", "srcItem": "Bioavailability"},
    {"id": "q-f202-s18-037", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which practice raises the lung/total (L/T) ratio of an inhaled drug?", "choices": ["Mouth rinsing and a breath hold", "Swallowing the drug", "Using no spacer", "Inhaling rapidly without holding"], "correct": 0, "explanation": "Higher L/T = more efficient lung delivery: efficient devices, reservoirs, rinse and spit, breath hold, instruction.", "srcItem": "Bioavailability"},
    {"id": "q-f202-s18-038", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which drug has no oral bioavailability?", "choices": ["Epinephrine", "Acetaminophen", "Theophylline", "Prednisone"], "correct": 0, "explanation": "Hess: epinephrine lacks oral bioavailability.", "srcItem": "Bioavailability"},
    {"id": "q-f202-s18-039", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What are the major organs of drug elimination (Hess)?", "choices": ["The kidney and, to a lesser extent, the liver", "The lungs and skin", "The spleen and heart", "The stomach and intestines"], "correct": 0, "explanation": "Kidney and liver are major; lungs, saliva and sweat are minor routes.", "srcItem": "Organs of Elimination"},
    {"id": "q-f202-s18-040", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What primarily determines how quickly drugs are eliminated?", "choices": ["Renal function measured by creatinine clearance or eGFR", "Hair growth", "Body temperature only", "Blood type"], "correct": 0, "explanation": "Elimination depends primarily on renal function (CrCl or eGFR).", "srcItem": "Organs of Elimination"},
    {"id": "q-f202-s18-041", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "According to Chang's memory line, where are benzodiazepines metabolized and excreted?", "choices": ["Liver = metabolism; kidneys = excretion", "Kidneys = metabolism; liver = excretion", "Lungs = both", "Spleen = both"], "correct": 0, "explanation": "\"Liver = Metabolism, Kidneys = Excretion.\"", "srcItem": "Organs of Elimination"},
    {"id": "q-f202-s18-042", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which is more specific for kidney function?", "choices": ["Creatinine", "BUN", "Glucose", "Albumin"], "correct": 0, "explanation": "Creatinine (from muscle) is filtered with little reabsorption; BUN reflects protein metabolism and hydration.", "srcItem": "Creatinine vs Blood Urea Nitrogen (BUN)"},
    {"id": "q-f202-s18-043", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the normal BUN range in the RCP 202 Renal deck?", "choices": ["7–20 mg/dL", "0.7–1.3 mg/dL", "70–110 mg/dL", "135–145 mg/dL"], "correct": 0, "explanation": "BUN 7–20 mg/dL; creatinine men 0.7–1.3, women 0.6–1.1.", "srcItem": "Creatinine vs Blood Urea Nitrogen (BUN)"},
    {"id": "q-f202-s18-044", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "A patient has a high BUN with a normal creatinine. What does this suggest?", "choices": ["Dehydration or high protein intake", "Kidney failure", "Low muscle mass", "Liver failure only"], "correct": 0, "explanation": "High BUN with normal creatinine → dehydration or high protein; both high → kidney disease/AKI.", "srcItem": "Creatinine vs Blood Urea Nitrogen (BUN)"},
    {"id": "q-f202-s18-045", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "What is the normal BUN/creatinine ratio?", "choices": ["About 10:1 to 20:1", "About 1:1", "About 50:1", "About 1:10"], "correct": 0, "explanation": "Normal ratio ~10:1–20:1; it helps separate prerenal, renal and postrenal causes.", "srcItem": "Creatinine vs Blood Urea Nitrogen (BUN)"},
    {"id": "q-f202-s18-046", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Why is serum creatinine called 'relatively insensitive'?", "choices": ["It may not rise until more than 50% of renal function is lost", "It rises with every meal", "It changes with temperature", "It is affected only by the lungs"], "correct": 0, "explanation": "Hess: creatinine may not increase until > 50% of renal function has deteriorated.", "srcItem": "Creatinine vs Blood Urea Nitrogen (BUN)"},
    {"id": "q-f202-s18-047", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "On train-of-four monitoring, how many twitches is the ICU goal?", "choices": ["1–2 twitches (~90–95% blockade)", "0 twitches", "4 twitches", "10 twitches"], "correct": 0, "explanation": "NMBA deck: 1–2 twitches = ~90–95%, the ICU goal; more twitches = less paralysis.", "srcItem": "Monitoring NMBAs and What Strengthens or Weakens the Block"},
    {"id": "q-f202-s18-048", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "In what order does paralysis occur, and which muscle recovers first?", "choices": ["Eyelids first to diaphragm last; the diaphragm recovers first", "Diaphragm first; eyelids recover first", "All muscles at once", "Legs first; arms last"], "correct": 0, "explanation": "Eyelids → face → neck → extremities → abdomen → intercostals → diaphragm; recovery is the reverse.", "srcItem": "Monitoring NMBAs and What Strengthens or Weakens the Block"},
    {"id": "q-f202-s18-049", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "Which condition POTENTIATES neuromuscular blockade?", "choices": ["Acidosis and low electrolytes", "Alkalosis", "Hypercalcemia", "Hyperkalemia only"], "correct": 0, "explanation": "\"Acidotic and low electrolytes = MORE paralysis\"; alkalosis and hypercalcemia inhibit.", "srcItem": "Monitoring NMBAs and What Strengthens or Weakens the Block"},
    {"id": "q-f202-s18-050", "topic": "f202-s18", "course": "rcp202f", "pool": "both", "difficulty": 2, "q": "How is comfort judged in a paralyzed patient?", "choices": ["Tachycardia, hypertension, diaphoresis and lacrimation", "Facial grimacing", "Asking the patient", "Movement of the limbs"], "correct": 0, "explanation": "Paralysis masks signs; judge comfort by vital-sign and autonomic changes.", "srcItem": "Monitoring NMBAs and What Strengthens or Weakens the Block"}
